local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>高庭 審判庭內</color>",
  ui_story_5043_50430101_2_dialog_content = "審判官大人，絕對沒有這回事！",
  ui_story_5043_50430101_3_dialog_content = "光之神在上，我絕對沒有在「愛」這件事情上欺騙過她啊！",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50430101_5_dialog_content = "法庭莊嚴，請被告不要打斷原告發言。",
  ui_story_5043_50430101_6_dialog_content = "繼續吧，零恩審判官。",
  ui_story_5043_50430101_7_dialog_content = "原告，妳主張被告在訂婚期間未履行未婚夫義務，是這樣嗎？",
  ui_story_5043_50430101_8_dialog_content = "沒錯！",
  ui_story_5043_50430101_9_dialog_content = "在法庭辯論開始前，原告還可以做最後的陳述。",
  ui_story_5043_50430101_10_dialog_content = "上個月的冠月節，我們迎來了訂婚七個月紀念日。",
  ui_story_5043_50430101_11_dialog_content = "可是這個傢伙，根本沒把這件事放在心上！",
  ui_story_5043_50430101_12_dialog_content = "饒了我吧，每個月都要慶祝的話，我真的吃不消啊！",
  ui_story_5043_50430101_13_dialog_content = "沒慶祝就算了，他還在當天送禮物給好幾個人！",
  ui_story_5043_50430101_14_dialog_content = "等等，我都說了是因為對方和我們家族有生意往來……",
  ui_story_5043_50430101_15_dialog_content = "等、等一下，請不要吵架呀，兩位……",
  ui_story_5043_50430101_16_dialog_content = "<size=30>蒂娜，妳現在也是審判官，要拿出氣勢來！</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>對哦，你說得沒錯！看我的，咳咳……</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>肅靜、肅靜！</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>嘰嘰喳喳……嘰嘰喳喳……</color>",
  ui_story_5043_50430101_20_dialog_content = "（所以說，我為什麼會坐在這裡旁聽陌生情侶吵架啊……）",
  ui_story_5043_50430101_21_dialog_content = "不耐煩了嗎，PlayerName？你的表情看起來有點勉強。",
  ui_story_5043_50430101_22_dialog_content = "沒、沒這回事……好吧，妳還真敏銳啊，卡蓮。",
  ui_story_5043_50430101_23_dialog_content = "說實話，我的心情跟你一模一樣。",
  ui_story_5043_50430101_24_dialog_content = "但我不可以隨便表現出來，畢竟——",
  ui_story_5043_50430101_25_dialog_content = "我明白。畢竟，妳的一言一行也代表了坐在那邊的城主大人。",
  ui_story_5043_50430101_26_dialog_content = "……",
  ui_story_5043_50430101_27_dialog_content = "城主倒是一直沒有表態。",
  ui_story_5043_50430101_28_dialog_content = "抱歉，本來是想邀請你來高庭的會議廳做龍洲大陸的匯報。",
  ui_story_5043_50430101_29_dialog_content = "但現在看來，他似乎還沒辦法從繁忙的工作中抽身。",
  ui_story_5043_50430101_30_dialog_content = "沒關係，我這段時間本來也沒有什麼緊急的規劃。",
  ui_story_5043_50430101_31_dialog_content = "<size=30>不如說，我反而有點抗拒再次進入那間嚴肅的會議室……</size>",
  ui_story_5043_50430101_32_dialog_content = "嗯，什麼？",
  ui_story_5043_50430101_33_dialog_content = "沒什麼！",
  ui_story_5043_50430101_34_dialog_content = "（這麼一想，上一次坐在這裡，還是因為<color=#FFB400>那件事</color>……）",
  ui_story_5043_50430101_35_dialog_content = "（伊淪汀也是坐在同樣的位置，宣讀審判庭對卡蓮的判決。）",
  ui_story_5043_50430101_36_dialog_content = "（現在的卡蓮……已經比那時又變了許多呢。）",
  ui_story_5043_50430101_37_dialog_content = "PlayerName，你在發呆嗎？",
  ui_story_5043_50430101_38_dialog_content = "啊，這個……我在想……",
  ui_story_5043_50430101_39_dialog_content = "我在想，冠月節似乎為白夜城帶來了不少變化呢……",
  ui_story_5043_50430101_40_dialog_content = "是的，每年這段時間，這種狀況都會持續一陣子。",
  ui_story_5043_50430101_41_dialog_content = "青年男女沉浸在冠月節的餘韻中，有人開啟了新緣分，有人彼此產生嫌隙。",
  ui_story_5043_50430101_42_dialog_content = "更有一些熱愛享樂的貴族們，會想方設法延續冠月節的快樂。",
  ui_story_5043_50430101_43_dialog_content = "因此，審判庭每年這個時候都得處理大量的感情糾紛。",
  ui_story_5043_50430101_44_dialog_content = "城主也會在這時增加旁聽的頻率，防止審判庭爆發出無法控制的突發事件。",
  ui_story_5043_50430101_45_dialog_content = "其實，偶爾像這樣坐在旁聽席，要比站在被告席來得輕鬆多了，不是嗎？",
  ui_story_5043_50430101_46_dialog_content = "卡蓮……",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>肅靜！</size>",
  ui_story_5043_50430101_49_dialog_content = "總之，這是絕對不能原諒的事！",
  ui_story_5043_50430101_50_dialog_content = "我要求透過訴訟的方式取消婚約！",
  ui_story_5043_50430101_51_dialog_content = "呵呵，美麗的原告小姐，我已經完全理解您的訴求了。",
  ui_story_5043_50430101_52_dialog_content = "據我所知，二位的家族締結婚約已久，您和被告也是青梅竹馬的關係。",
  ui_story_5043_50430101_53_dialog_content = "也難怪啊，如果不是青梅竹馬，被告這樣的男人，很難跟您這樣的小姐戀愛。",
  ui_story_5043_50430101_54_dialog_content = "唔……史瓦審判官說得沒錯，我們確實從小一起長大，我是最瞭解他的人。",
  ui_story_5043_50430101_55_dialog_content = "真是讓人羡慕的關係啊，我都有點嫉妒被告了呢。",
  ui_story_5043_50430101_56_dialog_content = "（哇？！這個審判官……還真是油膩！）",
  ui_story_5043_50430101_57_dialog_content = "史、史瓦審判官……",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50430101_59_dialog_content = "史瓦審判官，請注意維持你的專業。",
  ui_story_5043_50430101_60_dialog_content = "畢竟即使是我和審判長，也對被告的品性毫不瞭解。",
  ui_story_5043_50430101_61_dialog_content = "妳會提出訴訟，恐怕也是基於對他多年的瞭解，深思熟慮後的判斷。",
  ui_story_5043_50430101_62_dialog_content = "咦……？",
  ui_story_5043_50430101_63_dialog_content = "（呵，還真是輕易就上鉤了。）",
  ui_story_5043_50430101_64_dialog_content = "我、我……",
  ui_story_5043_50430101_65_dialog_content = "在伊倫汀審判長敲下裁決的法槌之前，被告，你還有什麼話要說嗎？",
  ui_story_5043_50430101_66_dialog_content = "<size=45>親愛的，我從小到大愛的人一直都只有妳啊！</size>",
  ui_story_5043_50430101_67_dialog_content = "啊……你、你這個人……！突然在這種地方講這種話……",
  ui_story_5043_50430101_68_dialog_content = "好了～那麼，接下來——",
  ui_story_5043_50430101_69_dialog_content = "<size=45>等等！</size>",
  ui_story_5043_50430101_70_dialog_content = "對不起，剛剛我重新思考了我和他之間的關係……",
  ui_story_5043_50430101_71_dialog_content = "我要申請<color=#FFB400>撤訴</color>。",
  ui_story_5043_50430101_72_dialog_content = "（這麼輕易就撤訴了？！）",
  ui_story_5043_50430101_73_dialog_content = "非常抱歉，我有欠缺考慮的地方，我們之間也沒有及時處理誤會。",
  ui_story_5043_50430101_74_dialog_content = "不，是我的態度過於消極了，我才是做得不好的那個人。",
  ui_story_5043_50430101_75_dialog_content = "駁回申請。審判庭是一個嚴肅的地方，上訴與撤訴都必須經過正式的流程。",
  ui_story_5043_50430101_76_dialog_content = "不過，也有比撤訴更便捷的處理方法。",
  ui_story_5043_50430101_77_dialog_content = "我宣布——",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50430101_79_dialog_content = "被告無罪。",
  ui_story_5043_50430101_80_dialog_content = "親愛的～",
  ui_story_5043_50430101_81_dialog_content = "寶貝，我們去附近的沙龍喝下午茶吧……",
  ui_story_5043_50430101_82_dialog_content = "……本案的審理到此結束，閉庭。",
  ui_story_5043_50430101_83_dialog_content = "史瓦大人請留步～！",
  ui_story_5043_50430101_84_dialog_content = "史瓦大人，恭喜您今天庭審順利！這是慶祝花束～！",
  ui_story_5043_50430101_85_dialog_content = "還、還有，我也為您準備了白巧克力，請收下……",
  ui_story_5043_50430101_86_dialog_content = "（嘖……）",
  ui_story_5043_50430101_87_dialog_content = "不要著急，小百合花們～請一個一個來吧～",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>高庭 審判長辦公室</color>",
  ui_story_5043_50430101_89_dialog_content = "「規則」的意義，是為了能夠讓人一眼就發現何處存在亂象。",
  ui_story_5043_50430101_90_dialog_content = "這種混亂的感情糾紛案件，在審判庭出現多久了？",
  ui_story_5043_50430101_91_dialog_content = "報告城主大人，只是在最近一個月受理得相對頻繁。",
  ui_story_5043_50430101_92_dialog_content = "原來如此，年輕真好。",
  ui_story_5043_50430101_93_dialog_content = "但是審判庭終究是一個神聖、嚴肅的地方。",
  ui_story_5043_50430101_94_dialog_content = "您的意思是，停止審理此類案件嗎？",
  ui_story_5043_50430101_95_dialog_content = "不，現在還遠不是時候。",
  ui_story_5043_50430101_96_dialog_content = "這樣做只會讓民眾把過剩的情緒對準審判庭。",
  ui_story_5043_50430101_97_dialog_content = "請城主大人指示。",
  ui_story_5043_50430101_98_dialog_content = "成立一個臨時分部吧，專門承接這類戀愛糾紛案。",
  ui_story_5043_50430101_99_dialog_content = "把它同樣下設在高庭內，但要與現在的審判庭拉開距離。",
  ui_story_5043_50430101_100_dialog_content = "至於人手，就調幾個新來的年輕人過去鍛鍊鍛鍊吧。",
  ui_story_5043_50430101_101_dialog_content = "這樣的話，這個臨時分部也需要一位臨時審判長呢。",
  ui_story_5043_50430101_102_dialog_content = "您心裡有人選了嗎？",
  ui_story_5043_50430101_103_dialog_content = "嗯，我剛才注意到一個年輕人……",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>高庭 審判庭內</color>",
  ui_story_5043_50430101_105_dialog_content = "城主和伊倫汀審判長似乎在商量重要的事。",
  ui_story_5043_50430101_106_dialog_content = "今天的會議看樣子要取消了。我記得，他下一次有空的時間是在……",
  ui_story_5043_50430101_107_dialog_content = "抱歉啊，PlayerName，要害你再多等幾天了。",
  ui_story_5043_50430101_108_dialog_content = "習慣之後你就會發現，他就是這種喜歡爽約、喜歡無視別人意見的人。",
  ui_story_5043_50430101_109_dialog_content = "不、不用說這種話……我們現在也算是難得清閒，不是嗎？",
  ui_story_5043_50430101_110_dialog_content = "看著這幾位審判官整理資料，也是個打發時間的好方法。",
  ui_story_5043_50430101_111_dialog_content = "訴狀、證據、辯護意見……好，都收拾齊了。",
  ui_story_5043_50430101_112_dialog_content = "這樣應該就整理得差不多了。蒂娜，妳那邊呢？",
  ui_story_5043_50430101_113_dialog_content = "嗯……嗯……？",
  ui_story_5043_50430101_114_dialog_content = "啊，抱歉啊零恩，剛才的庭審時間都超過三個小時了，我已經……哈欠～",
  ui_story_5043_50430101_115_dialog_content = "真是的，既然如此……",
  ui_story_5043_50430101_116_dialog_content = "辛苦工作了一天～來一杯放鬆精神的慰勞茶吧，蒂娜大人！請——",
  ui_story_5043_50430101_117_dialog_content = "唔，謝謝你啊零恩，咕嚕……",
  ui_story_5043_50430101_118_dialog_content = "噢？！！",
  ui_story_5043_50430101_119_dialog_content = "怎、怎麼是熱巧克力！！！",
  ui_story_5043_50430101_120_dialog_content = "哼哼，醒了吧？就算妳有「強睡症」，也要起來做完工作再睡啊。",
  ui_story_5043_50430101_121_dialog_content = "不過，話說回來，怎麼感覺妳這兩天比平時更嗜睡了？",
  ui_story_5043_50430101_122_dialog_content = "有嗎……我每天都是固定清醒四個小時啊。",
  ui_story_5043_50430101_123_dialog_content = "至少今天絕對不是吧，妳昨天也是還沒下班就開始打哈欠了。",
  ui_story_5043_50430101_124_dialog_content = "難道是晚上沒睡夠嗎？不會連妳都有失眠的時候吧？",
  ui_story_5043_50430101_125_dialog_content = "別、別開玩笑了，怎麼可能……",
  ui_story_5043_50430101_126_dialog_content = "好了，我這邊的資料都整理好了，我要下班啦。",
  ui_story_5043_50430101_127_dialog_content = "明天見，各位！",
  ui_story_5043_50430101_128_dialog_content = "嗯，我也差不多可以走了。",
  ui_story_5043_50430101_129_dialog_content = "坐在那邊旁聽席上的卡蓮殿下和男伴，再見。",
  ui_story_5043_50430101_130_dialog_content = "哦，再見！",
  ui_story_5043_50430101_131_dialog_content = "（我淪為「男伴」了嗎……）",
  ui_story_5043_50430101_132_dialog_content = "哎呀～好久不見啊，公主殿下的「男伴」。",
  ui_story_5043_50430101_133_dialog_content = "這個聲音是……",
  ui_story_5043_50430101_134_dialog_content = "馬太！還有洛維，果然是你們！",
  ui_story_5043_50430101_135_dialog_content = "看來馬太閣下還是一樣愛耍嘴皮又遊手好閒。",
  ui_story_5043_50430101_136_dialog_content = "別生氣嘛，公主殿下，我可不是來閒逛的。",
  ui_story_5043_50430101_137_dialog_content = "有一件「有意思的事情」，你們要不要加入？",
  ui_story_5043_50430101_138_dialog_content = "「有意思的事情」？",
  ui_story_5043_50430101_139_dialog_content = "沒錯，這可是我剛剛才探聽到的消息，普通庶民要等到明天才能知道了。",
  ui_story_5043_50430101_140_dialog_content = "快說。",
  ui_story_5043_50430101_141_dialog_content = "是這樣的，審判庭最近接到一樁奇怪的案件，雖然還沒有分派下來……",
  ui_story_5043_50430101_142_dialog_content = "但是我已經勢在必得了～",
  ui_story_5043_50430101_143_dialog_content = "也就是求了審判長好久才得到口頭應允。",
  ui_story_5043_50430101_144_dialog_content = "喂！你少插嘴啊！",
  ui_story_5043_50430101_145_dialog_content = "總之，這樁案件也跟最近的冠月節風潮有關……",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>高庭 住宅區</color>",
  ui_story_5043_50430101_147_dialog_content = "哼哼～哼……哼～♪",
  ui_story_5043_50430101_148_dialog_content = "（走到家門前的第一件事，檢查一下信箱和門口的包裹～）",
  ui_story_5043_50430101_149_dialog_content = "啊……",
  ui_story_5043_50430101_150_dialog_content = "還是沒有收到呢。",
  ui_story_5043_50430101_151_dialog_content = "（<color=#FFB400>他</color>上個月當作禮物寄給我的葉子和果實，我至今都還好好留著。）",
  ui_story_5043_50430101_152_dialog_content = "（明明到了我寄回禮的時候了，可是<color=#FFB400>他</color>完全沒有給我新的地址……）",
  ui_story_5043_50430101_153_dialog_content = "（這麼一說，我快一個月沒有收到<color=#FFB400>他</color>的回信了。）",
  ui_story_5043_50430101_154_dialog_content = "（真讓人擔心啊……不知道我準備的這份餅乾，何時才能送到<color=#FFB400>他</color>手中。）",
  ui_story_5043_50430101_155_dialog_content = "（我果然應該……更主動一點嗎？）",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>次日</color>",
  ui_story_5043_50430201_2_dialog_content = "總之，情況就是這樣。",
  ui_story_5043_50430201_3_dialog_content = "城主大人決定在高庭內，臨時開設處理近期戀愛糾紛的分部。",
  ui_story_5043_50430201_4_dialog_content = "我把它命名為「<color=#FFB400>審判庭戀愛分部</color>」。",
  ui_story_5043_50430201_5_dialog_content = "我明白了，我會在戀愛分部繼續做好我的工作。",
  ui_story_5043_50430201_6_dialog_content = "容我多問一句，戀愛分部的審判長是哪位？是由您身兼兩職嗎？",
  ui_story_5043_50430201_7_dialog_content = "不，關於這一點，城主大人欽點了<color=#FFB400>史瓦</color>審判官。",
  ui_story_5043_50430201_8_dialog_content = "雖然我不是特別理解，但他昨天的表現似乎讓城主大人留下了難忘的印象……",
  ui_story_5043_50430201_9_dialog_content = "也許那樣的風格，才能更靈活地應對各種戀愛訴訟案吧。",
  ui_story_5043_50430201_10_dialog_content = "好吧，史瓦昨天對那場混亂局面的解決方法確實很獨到，我心服口服。",
  ui_story_5043_50430201_11_dialog_content = "那個傢伙，的確很會利用自己的異性緣……",
  ui_story_5043_50430201_12_dialog_content = "你也不用灰心，零恩。",
  ui_story_5043_50430201_13_dialog_content = "你們這批新人雖然才剛剛成為正式的審判官，但城主很看好你們的能力。",
  ui_story_5043_50430201_14_dialog_content = "從戀愛分部回來之後，你們也就有了名正言順的晉升理由。",
  ui_story_5043_50430201_15_dialog_content = "是，謝謝審判長。",
  ui_story_5043_50430201_16_dialog_content = "此外，還有一項工作要交代給你。",
  ui_story_5043_50430201_17_dialog_content = "不如說，這已經算是戀愛分部目前最棘手的訴訟案了。",
  ui_story_5043_50430201_18_dialog_content = "你也許已經聽說了，就是那樁「<color=#FFB400>斷頭雕像案</color>」。",
  ui_story_5043_50430201_19_dialog_content = "欸？我這麼快就可以開始準備第一次開庭了嗎？",
  ui_story_5043_50430201_20_dialog_content = "聽你這麼說，我就安心了。在你之前，已經有五六個人拒絕掉這個案子了。",
  ui_story_5043_50430201_21_dialog_content = "他們為什麼要拒絕？",
  ui_story_5043_50430201_22_dialog_content = "除了案件本身就夠怪異之外，他們的理由多是要和伴侶參加沙龍等等。",
  ui_story_5043_50430201_23_dialog_content = "啊，我明白了……",
  ui_story_5043_50430201_24_dialog_content = "（唉，這群老貴族的作風還真是一如既往……）",
  ui_story_5043_50430201_25_dialog_content = "「斷頭雕像案」的原告，是一位名叫<color=#FFB400>彼瑪隆</color>的中庭貴族。",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>四日前</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>叮鈴叮鈴——叮鈴——</color>",
  ui_story_5043_50430201_28_dialog_content = "聽到了聽到了，不要再搖啦！",
  ui_story_5043_50430201_29_dialog_content = "先生，是您搖響了訴訟之鈴嗎？",
  ui_story_5043_50430201_30_dialog_content = "是的，我要起訴！起訴我的鄰居！",
  ui_story_5043_50430201_31_dialog_content = "他破壞了審判庭前面的雕像<color=#FFB400>加拉泰婭</color>！我看到了，千真萬確！",
  ui_story_5043_50430201_32_dialog_content = "等一下，審判庭象徵正義的雕像什麼時候叫「加拉泰婭」了？",
  ui_story_5043_50430201_33_dialog_content = "雖然說它前幾天確實壞了，我們還以為是年久失修的關係……",
  ui_story_5043_50430201_34_dialog_content = "小姐，注意妳的用詞，是「<color=#FFB400>她</color>」！這是我替她取的名字。",
  ui_story_5043_50430201_35_dialog_content = "唔，好的好的，那請把您的起訴狀交給我吧。",
  ui_story_5043_50430201_36_dialog_content = "讓我看看……",
  ui_story_5043_50430201_37_dialog_content = "嗯？彼瑪隆先生，您對鄰居的罪名指控……沒有寫錯嗎？",
  ui_story_5043_50430201_38_dialog_content = "您指控他破壞雕像，但罪名卻是……「<color=#FFB400>妨礙戀愛</color>」？！！",
  ui_story_5043_50430201_39_dialog_content = "千真萬確，因為……",
  ui_story_5043_50430201_40_dialog_content = "加拉泰婭就是我的<color=#FFB400>愛人</color>！",
  ui_story_5043_50430201_41_dialog_content = "因為愛上了雕像……所以要追究雕像的破壞者？",
  ui_story_5043_50430201_42_dialog_content = "是的，因為雕像屬於公共設施，我們無權阻止任何人愛上雕像。",
  ui_story_5043_50430201_42X1_dialog_content = "所以嚴格來說，也應該歸為戀愛分部需要處理的訴訟。",
  ui_story_5043_50430201_43_dialog_content = "除此之外，我已經派人調查過被告了，但是卻很遺憾地發現——",
  ui_story_5043_50430201_44_dialog_content = "起訴狀的內容漏洞百出，把被告當作嫌疑人並不恰當。",
  ui_story_5043_50430201_45_dialog_content = "審判庭向來是「查審一體」，零恩，我們務必要在開庭前掌握更多案件資料。",
  ui_story_5043_50430201_46_dialog_content = "不然的話，就只能草草休庭等待再次開庭。但戀愛分部的設立時限可不等人。",
  ui_story_5043_50430201_47_dialog_content = "明白了，我會在戀愛分部有限的設立時間之內解決掉。",
  ui_story_5043_50430201_48_dialog_content = "有勞了。除了你之外，還有兩位同事也會和你一起參與這樁案件。",
  ui_story_5043_50430201_49_dialog_content = "一位是你的老搭檔蒂娜，我早上已經確認了她的意願。",
  ui_story_5043_50430201_50_dialog_content = "我把整理卷宗的工作交給她了，她現在應該正在補眠。",
  ui_story_5043_50430201_51_dialog_content = "另外一位……雖然總讓人感到頭疼，但也算你們的<color=#FFB400>前輩</color>，可以替你們指點一二。",
  ui_story_5043_50430201_52_dialog_content = "你現在去那個被破壞的雕像前面跟他會合吧。",
  ui_story_5043_50430201_53_dialog_content = "調查完，就可以去和蒂娜同步你們之間的資料了。",
  ui_story_5043_50430201_54_dialog_content = "好，我立刻就去。",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>高庭 雕像旁</color>",
  ui_story_5043_50430201_56_dialog_content = "（也不知道審判長神神祕祕提到的前輩會是哪一位。）",
  ui_story_5043_50430201_57_dialog_content = "咦呃，現在的審判庭，已經可以不論出身，接納庶民新人了嗎？",
  ui_story_5043_50430201_58_dialog_content = "（果然是他啊……）",
  ui_story_5043_50430201_59_dialog_content = "跟馬太閣下比起來，這個審判官確實更像樣一點。",
  ui_story_5043_50430201_60_dialog_content = "日安，卡蓮衛隊長！轉輪騎士零恩向您致以問候。",
  ui_story_5043_50430201_61_dialog_content = "不必拘禮，旁邊這位是PlayerName，受馬太閣下邀請，我們也會盡量協助此事。",
  ui_story_5043_50430201_62_dialog_content = "原來您就是傳說中的那位空裔？您比傳聞要親切多了！",
  ui_story_5043_50430201_63_dialog_content = "不、不用這麼客氣，請多指教……",
  ui_story_5043_50430201_64_dialog_content = "<size=32>傳聞到底都是些什麼東西啊……</size>",
  ui_story_5043_50430201_65_dialog_content = "感謝光之神的賜福吧，庶民新人，有了我們幾個，你的工作絕對進展順利。",
  ui_story_5043_50430201_66_dialog_content = "不出錯就已經很不錯了。",
  ui_story_5043_50430201_67_dialog_content = "怎麼，新人，看你的表情好像不太激動？",
  ui_story_5043_50430201_68_dialog_content = "這可是審判庭歷史上接到最奇怪的訴訟案件，給我打起精神來！",
  ui_story_5043_50430201_69_dialog_content = "是啊，奇怪的雕像、奇怪的罪名、奇怪的原告、奇怪的前輩。",
  ui_story_5043_50430201_70_dialog_content = "喂，臭小子！你的態度最好放尊重一點。",
  ui_story_5043_50430201_71_dialog_content = "好了，我今天不是來跟你鬥嘴的。這個雕像你已經觀察過了吧？",
  ui_story_5043_50430201_72_dialog_content = "你說這個存錢筒？",
  ui_story_5043_50430201_73_dialog_content = "不好意思啊，看著這個沒有頭的空心石膏像，就讓人很想扔一枚白夜幣進去。",
  ui_story_5043_50430201_74_dialog_content = "真是的，能不能稍微認真一點啊……",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>喀嚓……</color>",
  ui_story_5043_50430201_76_dialog_content = "什麼聲音？",
  ui_story_5043_50430201_77_dialog_content = "嘎咕……吼！！！",
  ui_story_5043_50430201_78_dialog_content = "沒搞錯吧？！高庭還有沒有規矩了？怎麼能讓髒東西混進來？！",
  ui_story_5043_50430201_79_dialog_content = "不可能……！白夜城明明日夜都有人守衛，絕對不可能放暗鬼進來……",
  ui_story_5043_50430201_80_dialog_content = "衛兵！",
  ui_story_5043_50430201_81_dialog_content = "是！",
  ui_story_5043_50430201_82_dialog_content = "帶我去嚴查近期所有通行證紀錄！聯絡守夜人，匯總近期的日誌向我匯報！",
  ui_story_5043_50430201_83_dialog_content = "至於這幾隻暗鬼……PlayerName，交給你們沒問題吧？",
  ui_story_5043_50430201_84_dialog_content = "放心，妳快去吧！",
  ui_story_5043_50430201_85_dialog_content = "既然如此，就讓這幾隻暗鬼接受制裁吧。",
  ui_story_5043_50430202_1_dialog_content = "結束了！大家，都沒受傷吧？",
  ui_story_5043_50430202_2_dialog_content = "我沒什麼事，就是有點噁心。",
  ui_story_5043_50430202_3_dialog_content = "一天的工作才剛開始，現在又要再洗一次澡了。",
  ui_story_5043_50430202_4_dialog_content = "喂，庶民新人，你沒事吧？",
  ui_story_5043_50430202_5_dialog_content = "多謝關心，我還遠遠不如你們這些動不動就要洗澡的老貴族嬌氣。",
  ui_story_5043_50430202_6_dialog_content = "那還真是不好意思～要這麼說的話，洛維才是最潔癖的人吧？",
  ui_story_5043_50430202_7_dialog_content = "你全身上下包得這麼緊，空氣在你眼裡都是髒的吧。",
  ui_story_5043_50430202_8_dialog_content = "這座雕像要是碎了，你們也可以不用做了。",
  ui_story_5043_50430202_9_dialog_content = "別無視我啊！",
  ui_story_5043_50430202_10_dialog_content = "好了，看夠了，審判庭快把它收好吧。",
  ui_story_5043_50430202_11_dialog_content = "重要的<color=#FFB400>物證</color>不該一直擺在這裡。",
  ui_story_5043_50430202_12_dialog_content = "對原告來說，這應該是「<color=#FFB400>被害人</color>」才對吧。",
  ui_story_5043_50430202_13_dialog_content = "讓我再仔細調查一下……",
  ui_story_5043_50430202_14_dialog_content = "唔……斷裂面的顏色明顯比雕像外表還新，應該不是老化後自然裂開。",
  ui_story_5043_50430202_15_dialog_content = "這個斷裂面的走向，確實也很像暴力破壞的痕跡。",
  ui_story_5043_50430202_16_dialog_content = "PlayerName，您有什麼高見嗎？",
  ui_story_5043_50430202_17_dialog_content = "這麼一說，我倒是覺得有一點很奇怪。",
  ui_story_5043_50430202_18_option_content = "消失的頭部",
  ui_story_5043_50430202_19_dialog_content = "這個雕像看起來不像是被隨便破壞的，它的斷裂面很完整，而且……",
  ui_story_5043_50430202_20_dialog_content = "脖子以下幾乎沒有損傷，只有頭消失了。",
  ui_story_5043_50430202_21_option_content = "多餘的碎片",
  ui_story_5043_50430202_22_dialog_content = "它的周圍好乾淨，那些多餘的碎片在哪裡？",
  ui_story_5043_50430202_23_dialog_content = "呃，這個，我覺得應該是負責整理物證的人員已經把這裡打掃過了。",
  ui_story_5043_50430202_24_dialog_content = "說、說得也是！這麼看來，奇怪的地方果然是——消失的頭部。",
  ui_story_5043_50430202_25_dialog_content = "你說得有道理，這麼一看，簡直像雕像頭部被什麼人<color=#FFB400>偷走</color>了一樣……",
  ui_story_5043_50430202_26_dialog_content = "我說，從剛才開始，你們有沒有注意到<color=#FFB400>那個</color>？",
  ui_story_5043_50430202_27_dialog_content = "就在那邊的窗戶外面，白夜城的上空，突然之間……",
  ui_story_5043_50430202_28_dialog_content = "升起了一輪<color=#FFB400>月亮</color>。",
  ui_story_5043_50430202_29_dialog_content = "真、真的！",
  ui_story_5043_50430202_30_dialog_content = "怪事真是越來越多了，這到底是什麼情況？",
  ui_story_5043_50430202_31_dialog_content = "有意思，我們去看看？",
  ui_story_5043_50430202_32_dialog_content = "喂……工作還沒結束啊！",
  ui_story_5043_50430202_33_dialog_content = "唔，大家都在呀？",
  ui_story_5043_50430202_34_dialog_content = "妳來了啊，蒂娜。這位是PlayerName，就是那位空裔。",
  ui_story_5043_50430202_35_dialog_content = "呵呵，其實我們在上個月的冠月節就已經見過面了。",
  ui_story_5043_50430202_36_dialog_content = "貴安，PlayerName，很高興在早上就見到你～！",
  ui_story_5043_50430202_37_dialog_content = "妳好蒂娜，但是，現在不是早上吧……",
  ui_story_5043_50430202_38_dialog_content = "蒂娜這傢伙，每次剛睡醒的時候都習慣說「早安」。",
  ui_story_5043_50430202_39_dialog_content = "蒂娜小姐，妳來得正是時候，我們來核對一下目前掌握的調查結果吧。",
  ui_story_5043_50430202_40_dialog_content = "這樣的話，我們……我們一起說吧，我目前的調查結果是——",
  ui_story_5043_50430202_41_dialog_content = "無。",
  ui_story_5043_50430202_42_dialog_content = "唉，果然啊，你們那邊也沒什麼進展。",
  ui_story_5043_50430202_43_dialog_content = "從審判長大人那裡拿到案件資料後，我仔細讀了很多遍。",
  ui_story_5043_50430202_44_dialog_content = "卻只有一些前後矛盾、邏輯混亂，我無法理解的文字。",
  ui_story_5043_50430202_45_dialog_content = "硬要說的話，我們這邊有了一個不確定的推測。",
  ui_story_5043_50430202_46_dialog_content = "我和PlayerName懷疑，這座雕像的頭部是被人拿走的。",
  ui_story_5043_50430202_47_dialog_content = "唔……為什麼會有人想偷雕像的頭？",
  ui_story_5043_50430202_48_dialog_content = "誰知道！說不定是那個初階法官老頭在幫自己找新頭套呢。",
  ui_story_5043_50430202_49_dialog_content = "既然都沒有什麼進展，那今天的工作就只能這麼結束囉？",
  ui_story_5043_50430202_50_dialog_content = "等一下！那個……其實……",
  ui_story_5043_50430202_51_dialog_content = "其實我來找各位，是有一件私人的事情想拜託大家！",
  ui_story_5043_50430202_52_dialog_content = "呃，「私人的事情」是什麼？我沒有什麼參與的意願……",
  ui_story_5043_50430202_53_dialog_content = "好吧……是、是我最近遇到困擾，想聽聽別人的意見……",
  ui_story_5043_50430202_54_dialog_content = "哎呀～在現在這個時期嗎？",
  ui_story_5043_50430202_55_dialog_content = "這也是可以理解的事，是感情煩惱吧？",
  ui_story_5043_50430202_56_dialog_content = "瞧你精神都來了。",
  ui_story_5043_50430202_57_dialog_content = "唔……總之，我想請大家來寒舍做客，我會用茶點好好招待的。",
  ui_story_5043_50430202_58_dialog_content = "PlayerName，請你也一起來吧。",
  ui_story_5043_50430202_59_dialog_content = "總是聽說空裔可以一眼就看穿人心，請你一定要聽聽我的困擾。",
  ui_story_5043_50430202_60_dialog_content = "這是我的榮幸，但空裔的本領也沒有那麼誇張啦……",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>高庭 住宅區 蒂娜家</color>",
  ui_story_5043_50430301_2_dialog_content = "事情是這樣的……",
  ui_story_5043_50430301_3_dialog_content = "我在上個月的冠月節，收到了<color=#FFB400>他</color>送的禮物。",
  ui_story_5043_50430301_4_dialog_content = "雖然都是一些普通的東西，但能夠從那份包裹中感受到<color=#FFB400>他</color>的心意。",
  ui_story_5043_50430301_5_dialog_content = "等、等一下，我沒聽錯吧？蒂娜，妳這是戀愛了？",
  ui_story_5043_50430301_6_dialog_content = "咦？這種心情，也算是「戀愛」嗎？我覺得好像不算呢……",
  ui_story_5043_50430301_7_dialog_content = "聽起來確實很像戀愛時才會做的事。",
  ui_story_5043_50430301_8_dialog_content = "既然PlayerName也這麼說的話……",
  ui_story_5043_50430301_9_dialog_content = "唔，先不討論這個了！先讓我把事情說完。",
  ui_story_5043_50430301_10_dialog_content = "轉眼間，冠月節過去快一個月了，按照慣例，我應該回禮給<color=#FFB400>他</color>才對。",
  ui_story_5043_50430301_11_dialog_content = "為此，我親自烤了餅乾想要送給<color=#FFB400>他</color>，每一塊形狀都是我精挑細選的。",
  ui_story_5043_50430301_12_dialog_content = "本來只等著把這些餅乾寄過去給他，可是……",
  ui_story_5043_50430301_13_dialog_content = "可是<color=#FFB400>他</color>卻再也不回應我的訊息了。",
  ui_story_5043_50430301_14_dialog_content = "我不僅沒有和<color=#FFB400>他</color>偷偷見面的機會，現在連<color=#FFB400>他</color>的來信也收不到了。",
  ui_story_5043_50430301_15_dialog_content = "為此，我最近常常失眠，導致睡眠不足，每天只睡16個小時……",
  ui_story_5043_50430301_16_dialog_content = "哎呀，好惡劣的人！",
  ui_story_5043_50430301_17_dialog_content = "聽起來比馬太還要惡劣一點。",
  ui_story_5043_50430301_18_dialog_content = "這樣的人，不要也罷啦～",
  ui_story_5043_50430301_19_dialog_content = "但是，我還是暫時不想放棄，我想他應該也有他的難處吧。",
  ui_story_5043_50430301_20_dialog_content = "畢竟，<color=#FFB400>他</color>的形象過於突出，走到哪裡都會引起別人的注意。",
  ui_story_5043_50430301_21_dialog_content = "還真是無可救藥的想法。",
  ui_story_5043_50430301_22_dialog_content = "嗯……？",
  ui_story_5043_50430301_23_dialog_content = "<size=32>我說，PlayerName、馬太、洛維，你們覺不覺得……</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>蒂娜說的這個「<color=#FFB400>他</color>」，聽起來好像有點熟悉！</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>還真是！無論是「走到哪裡都會引起別人注意」……</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>還是「面對追求者時態度消極，只做表面功夫」……</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>以及「性格惡劣、浮誇、自戀、自大」。</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>你才沒資格說，這一點倒是跟你一樣。</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>總之，蒂娜說的那個人，果然就是<color=#FFB400>史瓦</color>吧？</size>",
  ui_story_5043_50430301_30_dialog_content = "嗯？你們在說什麼悄悄話嗎？",
  ui_story_5043_50430301_31_dialog_content = "咳……蒂娜，我們已經知道妳說的那個人是誰了！",
  ui_story_5043_50430301_32_dialog_content = "哎？！這樣就猜到了？我、我還沒打算承認……",
  ui_story_5043_50430301_33_dialog_content = "（蒂娜看上去確實被我們問得措手不及……）",
  ui_story_5043_50430301_34_dialog_content = "我第一次見到他，是在薩拉爾家族的莊園。",
  ui_story_5043_50430301_35_dialog_content = "當時，我受邀參加薩拉爾家族舉辦的社交舞會。",
  ui_story_5043_50430301_36_dialog_content = "我比邀請函上的時間來得稍微早了一點，僕人就安排我在花園中稍作等候。",
  ui_story_5043_50430301_37_dialog_content = "可是薩拉爾莊園的花園十分氣派，我沒繞幾圈，就在苗圃迷宮迷路了。",
  ui_story_5043_50430301_38_dialog_content = "在我不知道走了多久之後，終於在一座涼亭裡見到了他。",
  ui_story_5043_50430301_39_dialog_content = "他看到我的到來也非常驚訝，我們就這麼在美麗的藍天下對視許久……",
  ui_story_5043_50430301_40_dialog_content = "我第一次注意到，他是那麼柔軟、溫和、善良，跟周圍的樹木花朵是那麼和諧。",
  ui_story_5043_50430301_41_dialog_content = "後來他先離開了涼亭，可是我直到那天舞會結束，都無法再注意其他人了。",
  ui_story_5043_50430301_42_dialog_content = "嘖嘖，真是羅曼蒂克的相遇呢。",
  ui_story_5043_50430301_43_dialog_content = "（薩拉爾莊園，那果然是史瓦 · 薩拉爾沒錯了。）",
  ui_story_5043_50430301_44_dialog_content = "（柔軟、溫和、善良？！！好吧……）",
  ui_story_5043_50430301_45_dialog_content = "既然你們已經猜到了，我其實還有一個小請求。",
  ui_story_5043_50430301_46_dialog_content = "我希望大家能幫我實現「<color=#FFB400>盡偶出</color>」計畫！",
  ui_story_5043_50430301_47_dialog_content = "這是什麼奇怪的名字……",
  ui_story_5043_50430301_48_dialog_content = "也就是說，「<color=#FFB400>盡量以偶然的機會出現在他面前</color>」！簡稱「盡偶出」！",
  ui_story_5043_50430301_49_dialog_content = "不幫妳實行計畫的話，妳也不會死心吧？",
  ui_story_5043_50430301_50_dialog_content = "不、不好意思……",
  ui_story_5043_50430301_51_dialog_content = "好吧，同事一場，我就幫妳這個忙了。",
  ui_story_5043_50430301_52_dialog_content = "我也加入。",
  ui_story_5043_50430301_53_dialog_content = "嘎咕嘎咕。",
  ui_story_5043_50430301_54_dialog_content = "有髒東西！！！",
  ui_story_5043_50430301_55_dialog_content = "唉呀！真是的，僕人？僕人！",
  ui_story_5043_50430301_56_dialog_content = "算了，「神之手」也很久沒有使用的機會了。",
  ui_story_5043_50430301_57_dialog_content = "這次的清掃工作我就自己來吧。",
  ui_story_5043_50430301_58_dialog_content = "這裡是妳家吧？不要表現得像出現一隻蟑螂一樣平靜啊！！！",
  ui_story_5043_50430302_1_dialog_content = "真是暢快的戰鬥……哈欠～",
  ui_story_5043_50430302_2_dialog_content = "我還是第一次注意到，蒂娜竟然是左撇子嗎？",
  ui_story_5043_50430302_3_dialog_content = "啊哈哈，是這樣啦，為了承襲「神之手」的力量，我從小就接受了相關訓練。",
  ui_story_5043_50430302_4_dialog_content = "不過戰鬥結束後，總覺得有點累呢……",
  ui_story_5043_50430302_5_dialog_content = "妳現在要睡覺的話，我們就要回去了喔？",
  ui_story_5043_50430302_6_dialog_content = "沒——有！我還很有精神～",
  ui_story_5043_50430302_7_dialog_content = "繼續我們剛才的話題吧，請大家幫助我，實施「盡偶出」計畫！",
  ui_story_5043_50430302_8_dialog_content = "不過，我們應該怎麼做？",
  ui_story_5043_50430302_9_dialog_content = "這個嘛……因為我其實也沒有什麼追求經驗，所以才想要問問各位……",
  ui_story_5043_50430302_10_dialog_content = "我應該注意哪些事情呢？",
  ui_story_5043_50430302_11_dialog_content = "嗯……我想想啊，書上說過，知恥而後勇，承認自己的無知就是改變的第一步。",
  ui_story_5043_50430302_12_dialog_content = "要想成功讓對方答應妳，首先就是——<color=#FFB400>主動告白</color>。",
  ui_story_5043_50430302_13_dialog_content = "在對方經常出現的地方，等待對方的身影。",
  ui_story_5043_50430302_14_dialog_content = "一旦對方出現，就要立刻主動出擊，給對方一個措手不及！",
  ui_story_5043_50430302_15_dialog_content = "哦哦！原來如此……",
  ui_story_5043_50430302_16_dialog_content = "錯啦，庶民新人，光是主動還不夠，還要學會——<color=#FFB400>隱藏自己</color>。",
  ui_story_5043_50430302_17_dialog_content = "隱藏自己的真實心意，隱藏自己緊張的神情。",
  ui_story_5043_50430302_18_dialog_content = "有了主動的勇氣但不敢直視對方時，裝作害羞就能以退為進。",
  ui_story_5043_50430302_19_dialog_content = "這樣啊！我明白了……",
  ui_story_5043_50430302_20_dialog_content = "另外就是——<color=#FFB400>學會試探</color>。",
  ui_story_5043_50430302_21_dialog_content = "用一些普通的話題看看對方的態度。",
  ui_story_5043_50430302_22_dialog_content = "互相拉扯兩三次，就能看出對方的本性。",
  ui_story_5043_50430302_23_dialog_content = "似乎有點困難！但我會試試的……",
  ui_story_5043_50430302_24_dialog_content = "仔細想想的話，我覺得應該要——<color=#FFB400>拿出真心</color>吧。",
  ui_story_5043_50430302_25_dialog_content = "和對方認識久了之後，你們之間的習慣和缺點也會逐漸顯露。",
  ui_story_5043_50430302_26_dialog_content = "這個時候可能什麼掩飾計畫都不管用了，只有你們的真心才是最珍貴的。",
  ui_story_5043_50430302_27_dialog_content = "你說得對！希望我能和他進行到這個階段呢……",
  ui_story_5043_50430302_28_dialog_content = "謝謝大家，我都記住了！",
  ui_story_5043_50430302_29_dialog_content = "話說回來，這些方法，你們都實踐過嗎？",
  ui_story_5043_50430302_30_dialog_content = "咳……",
  ui_story_5043_50430302_31_dialog_content = "沒有實踐經驗還真是對不起啊……",
  ui_story_5043_50430302_32_dialog_content = "沒、沒有責怪大家的意思！這樣的話……果然還是要親自去嘗試。",
  ui_story_5043_50430302_33_dialog_content = "但是，現在到底該去哪裡找他呢？",
  ui_story_5043_50430302_34_dialog_content = "那傢伙這種時候應該會喜歡待在人多熱鬧的地方吧。",
  ui_story_5043_50430302_35_dialog_content = "哎？是這樣嗎……",
  ui_story_5043_50430302_36_dialog_content = "哦～要說熱鬧的地方，果然應該是那裡吧。",
  ui_story_5043_50430302_37_dialog_content = "那個貴族和庶民都會湊在一起的地方——「月亮」的正下方。",
  ui_story_5043_50430302_38_dialog_content = "為、為什麼？！",
  ui_story_5043_50430302_39_dialog_content = "我倒是先前就有聽過這個「月亮」的新聞，我們還是親眼看看比較好。",
  ui_story_5043_50430302_40_dialog_content = "是你自己想去吧。",
  ui_story_5043_50430302_41_dialog_content = "不僅是馬太閣下，我自己也還挺好奇的，那我們現在就去吧！",
  ui_story_5043_50430302_42_dialog_content = "啊不對，稍等一下！",
  ui_story_5043_50430302_43_dialog_content = "我要戴上我們初次見面牽手時的<color=#FFB400>手套</color>。",
  ui_story_5043_50430302_44_dialog_content = "還有我準備送給他的餅乾！",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>高庭 住宅區</color>",
  ui_story_5043_50430401_2_dialog_content = "你是說，最近這個「月亮」一樣的熱氣球，經常這麼飄在空中？",
  ui_story_5043_50430401_3_dialog_content = "我竟然從來沒有留意過……",
  ui_story_5043_50430401_4_dialog_content = "在我的認知裡，已經預設太陽和高庭是肉眼可見最高的東西了。",
  ui_story_5043_50430401_5_dialog_content = "你沒注意到也很正常啦，你們這種庶民，怎麼會懂得抬頭欣賞天空的景色呢。",
  ui_story_5043_50430401_6_dialog_content = "喂，你再說一遍！",
  ui_story_5043_50430401_7_dialog_content = "好啦好啦，怎麼走著走著又吵起來了～",
  ui_story_5043_50430401_8_dialog_content = "小時候第一次來千星階梯時，母親跟我說階梯上方能看到星星。",
  ui_story_5043_50430401_9_dialog_content = "每一級台階對應一顆星星，整個階梯加在一起，能看到一千顆。",
  ui_story_5043_50430401_10_dialog_content = "我當時樂壞了，一口氣爬到最上面。",
  ui_story_5043_50430401_11_dialog_content = "然後妳看到幾顆星星？",
  ui_story_5043_50430401_12_dialog_content = "一顆都沒有。當時是中午，天上只有太陽。",
  ui_story_5043_50430401_13_dialog_content = "好歹等晚上再去爬啊！",
  ui_story_5043_50430401_14_dialog_content = "可是晚上是睡覺時間……",
  ui_story_5043_50430401_15_dialog_content = "……",
  ui_story_5043_50430401_16_dialog_content = "話說回來，馬太閣下聽到的，有關「月亮」的新聞是什麼樣的？",
  ui_story_5043_50430401_17_dialog_content = "總之就是有關那些冠月節狂熱分子的活動。",
  ui_story_5043_50430401_18_dialog_content = "他們在白夜城中升起月亮般的熱氣球，旨在宣傳自由戀愛風潮。",
  ui_story_5043_50430401_19_dialog_content = "這群人會以升起的熱氣球為標誌，迅速聚集到同一個地方，舉辦快閃沙龍。",
  ui_story_5043_50430401_20_dialog_content = "那些喜歡追趕潮流、附庸風雅的貴族對此非常熱衷。",
  ui_story_5043_50430401_21_dialog_content = "原來如此……冠月節狂熱嗎？我好像有聽卡蓮說過。",
  ui_story_5043_50430401_22_dialog_content = "因為名字叫「冠月節」，所以用月亮作為象徵物……",
  ui_story_5043_50430401_23_dialog_content = "你們這些貴族還真是省事啊。",
  ui_story_5043_50430401_24_dialog_content = "我反而可以理解呢，因為月亮和愛情一樣，都是很純潔、很珍貴的東西。",
  ui_story_5043_50430401_25_dialog_content = "沙龍的主辦人一定寄託了這種美好的寓意吧。",
  ui_story_5043_50430401_26_dialog_content = "這話聽起來真不得了，這就是戀愛中的少女嗎……",
  ui_story_5043_50430401_27_dialog_content = "都說了這種心情不是戀愛啦……算了，你就不要取笑我了！",
  ui_story_5043_50430401_28_dialog_content = "總之，看熱氣球現在的方向，這次沙龍的地點應該在中庭那邊。",
  ui_story_5043_50430401_29_dialog_content = "嘖嘖，到了，又要沒完沒了地走路了，衛隊什麼時候才要在千星階梯設個馬車啊？",
  ui_story_5043_50430401_30_dialog_content = "可不是什麼人都像你一樣坐得起馬車。",
  ui_story_5043_50430401_31_dialog_content = "千星階梯是中庭與高庭之間的通道。",
  ui_story_5043_50430401_32_dialog_content = "準備好進入庶民的世界了嗎，馬太？",
  ui_story_5043_50430401_33_dialog_content = "囉嗦！",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>中庭 草地廣場</color>",
  ui_story_5043_50430401_35_dialog_content = "哇——",
  ui_story_5043_50430401_36_dialog_content = "中庭什麼時候有這麼一塊綠地了？真漂亮。",
  ui_story_5043_50430401_37_dialog_content = "聽說是春季剛批准修建的人造草坪，靠光能術來進行日常養護。",
  ui_story_5043_50430401_38_dialog_content = "咦？你們聽到了嗎……",
  ui_story_5043_50430401_39_dialog_content = "場地中央的月亮下方，好像放起了音樂。",
  ui_story_5043_50430401_39X1_dialog_content = "哦，按照新聞裡的說法，沙龍會分為聚談、舞會、欣賞讚美詩三部分。",
  ui_story_5043_50430401_40_dialog_content = "嗯～中規中矩的交誼舞音樂，品味還算過得去。",
  ui_story_5043_50430401_40X1_dialog_content = "年輕人，你們是第一次來月亮沙龍吧？",
  ui_story_5043_50430401_40X2_dialog_content = "不要這麼拘束地站著，來來來。",
  ui_story_5043_50430401_40X3_dialog_content = "喂！等一下，不要拉我啊，噁心死了！",
  ui_story_5043_50430401_41_dialog_content = "原來如此，這就是月亮沙龍的舞會時間呀！",
  ui_story_5043_50430401_42_dialog_content = "在一旁圍觀太失禮了，我們也加入他們吧，順便藉此觀察一下人群！",
  ui_story_5043_50430401_43_dialog_content = "可、可是我不懂你們這些亂七八糟的禮儀和舞步啊！",
  ui_story_5043_50430401_44_dialog_content = "我也完全不會跳……",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5043_50430401_46_dialog_content = "所以說……為什麼我得跟這個庶民新人一起跳啊？！我要吐了！",
  ui_story_5043_50430401_47_dialog_content = "你不會以為我很想跳吧！",
  ui_story_5043_50430401_48_dialog_content = "哎喲！！！",
  ui_story_5043_50430401_49_dialog_content = "你是笨蛋嗎？注意一下腳邊……哎呀！！！",
  ui_story_5043_50430401_50_dialog_content = "你絕對是故意的吧？",
  ui_story_5043_50430401_51_dialog_content = "等一下！你想幹嘛？！",
  ui_story_5043_50430401_52_dialog_content = "不行！不要拉我頭髮……",
  ui_story_5043_50430401_53_dialog_content = "噗哈哈哈哈！他們那邊好像很熱鬧呢。",
  ui_story_5043_50430401_54_dialog_content = "PlayerName，你很緊張嗎？",
  ui_story_5043_50430401_55_dialog_content = "沒事沒事，我還好……",
  ui_story_5043_50430401_56_dialog_content = "向左進、再踮腳、向右退、轉一圈……",
  ui_story_5043_50430401_57_dialog_content = "我我我我我我的手為什麼會打到妳啊！",
  ui_story_5043_50430401_58_dialog_content = "不要緊張啦，PlayerName，這只是禮儀性質的社交舞。",
  ui_story_5043_50430401_59_dialog_content = "就是這個舞步，我們再來一圈吧？",
  ui_story_5043_50430401_60_dialog_content = "好……我再努力一下！",
  ui_story_5043_50430401_61_dialog_content = "哈哈哈，你看，你這不是做得到嘛。",
  ui_story_5043_50430401_62_dialog_content = "你學得很快哦！",
  ui_story_5043_50430401_63_dialog_content = "呼～音樂結束了，全身都活動到了呢。",
  ui_story_5043_50430401_64_dialog_content = "我可不想再來一遍了……",
  ui_story_5043_50430401_65_dialog_content = "嘖，沒向你索賠已經是我最大的仁慈了。",
  ui_story_5043_50430401_66_dialog_content = "洛維那傢伙到底跑哪去了……",
  ui_story_5043_50430401_67_dialog_content = "看來我躲過了一劫。",
  ui_story_5043_50430401_68_dialog_content = "剛才場外有幾個明顯不是來參加沙龍的可疑人士。",
  ui_story_5043_50430401_69_dialog_content = "我過去查看的時候，發現了卡蓮殿下。",
  ui_story_5043_50430401_70_dialog_content = "感謝你帶路。呃，你說的「可疑人士」，其實是我安排的。",
  ui_story_5043_50430401_71_dialog_content = "嗚哇？卡蓮殿下也在這邊～！",
  ui_story_5043_50430401_72_dialog_content = "卡蓮，怎麼樣了？暗鬼的調查有結果嗎？",
  ui_story_5043_50430401_73_dialog_content = "還沒有，但已經排除了一些可能性。",
  ui_story_5043_50430401_74_dialog_content = "所有通行證都沒有問題，因此暗鬼不會有冒名頂替混入白夜城的機會。",
  ui_story_5043_50430401_75_dialog_content = "守夜工作和白夜城上空的防護罩也沒有疏漏。",
  ui_story_5043_50430401_76_dialog_content = "由於最近節日眾多，各種運送貨物的貿易商或傭兵也會出入白夜城。",
  ui_story_5043_50430401_77_dialog_content = "不能排除衛兵檢查不力，讓暗鬼藏在貨艙中混進來的可能性。",
  ui_story_5043_50430401_78_dialog_content = "咦？卡蓮殿下在搜查混入白夜城的暗鬼嗎？",
  ui_story_5043_50430401_79_dialog_content = "果然啊……要趕快找到他才行……",
  ui_story_5043_50430401_80_dialog_content = "倒也不用擔心那傢伙，他肯定安全得很。",
  ui_story_5043_50430401_81_dialog_content = "真、真的嗎……",
  ui_story_5043_50430401_82_dialog_content = "（總覺得蒂娜的擔憂有點奇怪？）",
  ui_story_5043_50430401_83_dialog_content = "總之，能躲過衛隊的搜查，領頭的暗鬼也許懂什麼<color=#FFB400>偽裝術</color>，能混跡在人群裡。",
  ui_story_5043_50430401_84_dialog_content = "為避免引起民眾恐慌，我沒有讓衛隊展開地毯式搜索。",
  ui_story_5043_50430401_85_dialog_content = "只是讓他們身穿便裝，在人多的地方盯著，防止有什麼不測。",
  ui_story_5043_50430401_86_dialog_content = "總覺得……卡蓮和城主大人，面對冠月節餘熱採取的措施很一致呢。",
  ui_story_5043_50430401_87_dialog_content = "……這在我聽來並不是誇獎。",
  ui_story_5043_50430401_88_dialog_content = "啊哈哈哈……抱歉啊，既然如此，我也一起幫忙吧？",
  ui_story_5043_50430401_89_dialog_content = "至少要保證在這種人多的地方沒有暗鬼的蹤影……",
  ui_story_5043_50430401_90_option_content = "強制感應",
  ui_story_5043_50430401_91_dialog_content = "多謝了，PlayerName。",
  ui_story_5043_50430401_92_dialog_content = "怎麼樣？有什麼異常嗎？",
  ui_story_5043_50430401_93_dialog_content = "唔……",
  ui_story_5043_50430401_94_dialog_content = "不行。場面太混亂了，完全沒有效果……",
  ui_story_5043_50430401_95_dialog_content = "喂，公主殿下，還有PlayerName！",
  ui_story_5043_50430401_96_dialog_content = "別呆站在那邊啦，快過來吧！",
  ui_story_5043_50430401_97_dialog_content = "嗯，既然已經來了，PlayerName，我們過去看看吧。",
  ui_story_5043_50430401_98_dialog_content = "湊近看的話，這個月亮熱氣球還真是震撼呢。",
  ui_story_5043_50430401_99_dialog_content = "殿下也這麼覺得嗎？",
  ui_story_5043_50430401_100_dialog_content = "春日的草地、戀愛的男女，還能隱約聽見唱詩班的歌聲。",
  ui_story_5043_50430401_101_dialog_content = "在不能輕易看到的月亮下面，人們彼此跨越階級，暢快地談論自己的思辨……",
  ui_story_5043_50430401_102_dialog_content = "簡直就像神話傳說裡才有的場景啊～",
  ui_story_5043_50430401_103_dialog_content = "呃，哪有什麼「思辨」，這裡不過是一個便利的戀愛場地罷了。",
  ui_story_5043_50430401_104_dialog_content = "我還是第一次同時見到這麼多庶民，空氣裡有一股下城的味道，嘔……",
  ui_story_5043_50430401_105_dialog_content = "現在後悔也來不及了。",
  ui_story_5043_50430401_106_dialog_content = "我說，庶民新人，你在發什麼呆？",
  ui_story_5043_50430401_107_dialog_content = "我總覺得……這個月亮有點奇怪。",
  ui_story_5043_50430401_108_dialog_content = "明明沒用繩索拴著，卻可以穩定浮在空中……難道是有光能術在操控……",
  ui_story_5043_50430401_109_dialog_content = "算了，只是一些基於庶民生活常識的擔憂罷了，不用過問我這種庶民的意見。",
  ui_story_5043_50430401_110_dialog_content = "這位先生猜得沒錯，除此之外……",
  ui_story_5043_50430401_111_dialog_content = "這些光能術，還維護著裡面那些<color=#FFB400>古老節日的饋贈</color>。",
  ui_story_5043_50430401_112_dialog_content = "不好意思，您是？",
  ui_story_5043_50430401_113_dialog_content = "我是一名普通的白夜城修女，閣下，您直接稱呼我修女就好。",
  ui_story_5043_50430401_114_dialog_content = "我是近期所有月亮沙龍的主辦人。",
  ui_story_5043_50430401_115_dialog_content = "您看起來像生面孔，怎麼樣，您對月亮沙龍還滿意嗎？",
  ui_story_5043_50430401_116_dialog_content = "雖、雖然我才剛來這裡沒多久，不過感覺挺新鮮的……",
  ui_story_5043_50430401_117_dialog_content = "整體氛圍和以往的白夜城都不太一樣。",
  ui_story_5043_50430401_118_dialog_content = "呵呵，感謝您的點評，光之神賜福您，那麼我就不繼續打擾了。",
  ui_story_5043_50430401_119_dialog_content = "桌上的茶和點心都可以隨意取用，另外，也可以去聆聽唱詩班的讚美詩。",
  ui_story_5043_50430401_120_dialog_content = "（所謂的唱詩班，該不會是……）",
  ui_story_5043_50430401_121_dialog_content = "您來參加月亮沙龍了呀～♪",
  ui_story_5043_50430401_122_dialog_content = "真來了哎～♪",
  ui_story_5043_50430401_123_dialog_content = "在沙龍上無所事事遊手好閒的樣子～♪",
  ui_story_5043_50430401_124_dialog_content = "依舊是單身吧？是單身呢～♪",
  ui_story_5043_50430401_125_dialog_content = "看吧，是一群可愛的孩子呢。",
  ui_story_5043_50430401_126_dialog_content = "哪裡可愛了啊！！！",
  ui_story_5043_50430401_127_dialog_content = "一戳就爆，身體胖～♪",
  ui_story_5043_50430401_128_dialog_content = "高高住在天空上～♪",
  ui_story_5043_50430401_129_dialog_content = "要問唱頌的是什麼～♪",
  ui_story_5043_50430401_130_dialog_content = "是無聊的貴族們和熱氣球月亮～♪",
  ui_story_5043_50430401_131_dialog_content = "哦，黎明學院的唱詩班被請過來了啊。",
  ui_story_5043_50430401_132_dialog_content = "他們讚美詩的風格還是一如既往地熟悉呢……",
  ui_story_5043_50430401_133_dialog_content = "男人和女人站在月亮下談笑～♪",
  ui_story_5043_50430401_134_dialog_content = "貴族和平民圍成一桌吃蛋糕～♪",
  ui_story_5043_50430401_135_dialog_content = "我可敬的、可愛的，修女阿姨～♪",
  ui_story_5043_50430401_136_dialog_content = "月亮沙龍辦得好～♪",
  ui_story_5043_50430401_137_dialog_content = "雖然乍聽有點難以理解，不過仔細一想好像又唱得不錯……",
  ui_story_5043_50430401_138_dialog_content = "啊，在這種地方碰到了唱詩班，果然還是應該禱告一下。",
  ui_story_5043_50430401_139_dialog_content = "白夜至上，光之神，請一定要保佑我見到他。",
  ui_story_5043_50430401_140_dialog_content = "這不在光之神的管轄範圍內吧……",
  ui_story_5043_50430401_141_dialog_content = "白夜城人人都可以信仰光之神～♪",
  ui_story_5043_50430401_142_dialog_content = "但貴族和平民卻不能自由通婚～♪",
  ui_story_5043_50430401_143_dialog_content = "我可敬的、可憐的，修女阿姨～♪",
  ui_story_5043_50430401_144_dialog_content = "觸怒那群愚蠢的大人，您馬上就要大難臨頭啦～♪",
  ui_story_5043_50430401_145_dialog_content = "什、什麼？",
  ui_story_5043_50430401_146_dialog_content = "肅清這片空地，把這些非法集會的人都抓起來。",
  ui_story_5043_50430401_147_dialog_content = "一定要把為首的策劃者帶回去。",
  ui_story_5043_50430401_148_dialog_content = "呀啊——",
  ui_story_5043_50430401_149_dialog_content = "高庭的衛隊來抓人了，快跑！",
  ui_story_5043_50430401_150_dialog_content = "我、我乃居住在上城區的貴族，誰敢抓我……",
  ui_story_5043_50430401_151_dialog_content = "噫？！！",
  ui_story_5043_50430401_152_dialog_content = "啊……<color=#FFB400>餅乾</color>！",
  ui_story_5043_50430401_153_dialog_content = "我帶出來打算交給他的餅乾<color=#FFB400>不見了</color>！",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>嘰嘰喳喳……嘰嘰喳喳……</color>",
  ui_story_5043_50430401_155_dialog_content = "（不可能，這絕對不是我的衛隊！）",
  ui_story_5043_50430401_156_dialog_content = "沒有我的命令，誰敢……",
  ui_story_5043_50430401_157_dialog_content = "衛隊長大人！",
  ui_story_5043_50430401_158_dialog_content = "他們不是高庭衛隊的士兵。",
  ui_story_5043_50430401_159_dialog_content = "除了高庭之外，鮮少有貴族掌握兵權。",
  ui_story_5043_50430401_160_dialog_content = "這些參與沙龍的人一定會把這次圍剿當作高庭的意見！",
  ui_story_5043_50430401_161_dialog_content = "……我明白你的意思，但先平息混亂要緊！",
  ui_story_5043_50430401_162_dialog_content = "各位，請不要驚慌！跟著我從這邊走！",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_5043_50430401_164_dialog_content = "（什麼聲音？！）",
  ui_story_5043_50430401_165_dialog_content = "PlayerName、轉輪騎士，麻煩助我一臂之力。",
  ui_story_5043_50430401_166_dialog_content = "和周圍這些便衣衛兵一起，制服這群肆意妄為、亂抓民眾的士兵！",
  ui_story_5043_50430401_167_dialog_content = "沒問題！",
  ui_story_5043_50430401_168_dialog_content = "一切聽您差遣。",
  ui_story_5043_50430501_1_dialog_content = "這群衛兵跑得到是挺快的啊！",
  ui_story_5043_50430501_2_dialog_content = "衛隊長大人，需要我繼續追嗎？",
  ui_story_5043_50430501_3_dialog_content = "……不必。你做好分內事就夠了。",
  ui_story_5043_50430501_4_dialog_content = "只可惜沙龍就這麼被毀了，想找的人也還沒找到。",
  ui_story_5043_50430501_5_dialog_content = "找人？你在找誰？",
  ui_story_5043_50430501_6_dialog_content = "蒂娜啦。蒂娜想親手送史瓦冠月節的回禮。",
  ui_story_5043_50430501_7_dialog_content = "哦，原來他們倆還有這樣的往來啊。",
  ui_story_5043_50430501_8_dialog_content = "這就是冠月節的威力嗎，讓兩個雙方沒有家族婚約的青年決定展開自由戀愛。",
  ui_story_5043_50430501_9_dialog_content = "不過……恕我直言，那樣輕浮的男人有什麼好？",
  ui_story_5043_50430501_10_dialog_content = "就是說啊……",
  ui_story_5043_50430501_11_dialog_content = "話說，你們有人看到洛維嗎？",
  ui_story_5043_50430501_12_dialog_content = "那群衛兵撤退之後，就沒看到他了。",
  ui_story_5043_50430501_13_dialog_content = "我請洛維去調查那些衛兵的來頭，你們就繼續推進案子的調查吧。",
  ui_story_5043_50430501_14_dialog_content = "雖說不用查也能猜個八九不離十，但還是想確定一下。",
  ui_story_5043_50430501_15_dialog_content = "出、出事啦！",
  ui_story_5043_50430501_16_dialog_content = "嗯，我也注意到了，就在不久前，你準備好的餅乾不見了吧？",
  ui_story_5043_50430501_17_dialog_content = "我們再翻一翻這些凌亂的剩菜空盤吧。",
  ui_story_5043_50430501_18_dialog_content = "不，如果只是「弄丟了餅乾」還算好的！",
  ui_story_5043_50430501_19_dialog_content = "是佇立在廣場入口處的那尊雕像……",
  ui_story_5043_50430501_20_dialog_content = "它在剛才的騷動期間被<color=#FFB400>打碎</color>了。",
  ui_story_5043_50430501_21_dialog_content = "什麼？！",
  ui_story_5043_50430501_22_dialog_content = "人群四處逃竄的時候，我有聽見一聲清脆的碎裂聲。",
  ui_story_5043_50430501_23_dialog_content = "湊巧的是，這雕像的損壞方式跟審判庭門前那尊一模一樣。",
  ui_story_5043_50430501_24_dialog_content = "彷彿就像被某個「雕像頭顱收割者」給「殺害」。",
  ui_story_5043_50430501_25_dialog_content = "這種事情……果然還是該向那位代理審判長報告最新狀況才是吧。",
  ui_story_5043_50430501_26_dialog_content = "這麼說來，他目前不在月亮沙龍，那肯定是在——",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>高庭‧史瓦辦公室</color>",
  ui_story_5043_50430501_28_dialog_content = "嗯……嗯，我明白了！",
  ui_story_5043_50430501_29_dialog_content = "你們回來得正好，雕像的事先放一邊，等原告更新訴訟流程。",
  ui_story_5043_50430501_30_dialog_content = "馬上有一個新的戀愛訴訟案件要開庭，準備上工吧，我親愛的下屬們。",
  ui_story_5043_50430501_31_dialog_content = "這麼突然？",
  ui_story_5043_50430501_32_dialog_content = "這就是戀愛分部啊，像被施加了光能術的馬車，一刻也不得停歇～",
  ui_story_5043_50430501_33_dialog_content = "不坐在審判長的位置，你是不會懂的，小、蒲、公、英～",
  ui_story_5043_50430501_34_dialog_content = "小、小蒲公英？？？",
  ui_story_5043_50430501_35_dialog_content = "（確定是在叫我嗎……我快吐了！）",
  ui_story_5043_50430501_36_dialog_content = "我想您會慢慢習慣，PlayerName……",
  ui_story_5043_50430501_37_dialog_content = "不過話說回來，史瓦審判長，蒂娜她一直有話想……",
  ui_story_5043_50430501_38_dialog_content = "我說啊，現在不是說那種事情的時候吧？",
  ui_story_5043_50430501_39_dialog_content = "（就是啊……零恩真是的，也不必急著跟史瓦代理審判長報告吧。）",
  ui_story_5043_50430501_40_dialog_content = "呀？看來我的下屬們的關係已經好到可以共享祕密的程度啦？",
  ui_story_5043_50430501_41_dialog_content = "總之，起訴狀和相關資料都在這裡了，案件很簡單，我們戀愛分部見。",
  ui_story_5043_50430501_42_dialog_content = "唔，看起來確實不複雜，案由還跟剛才的月亮沙龍有關……",
  ui_story_5043_50430501_43_dialog_content = "咦？！等一下！大家，請看這個「理由」部分的內容……！",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>審判庭戀愛分部</color>",
  ui_story_5043_50430501_45_dialog_content = "城主大人還真是雷厲風行，把這個地方修建得頗具規模哩。",
  ui_story_5043_50430501_46_dialog_content = "嗯，從一天內受理的起訴狀數量來看，財政預算撥給這個地方也不算浪費。",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50430501_48_dialog_content = "開庭！",
  ui_story_5043_50430501_49_dialog_content = "首先核對當事人和其他訴訟參加人的基本資料！",
  ui_story_5043_50430501_50_dialog_content = "原告，下城區男性。因原告方隱私原因無法公開姓名。",
  ui_story_5043_50430501_51_dialog_content = "被告，下城區女性。因被告方隱私原因無法公開姓名。",
  ui_story_5043_50430501_52_dialog_content = "（根本聽不清楚啊！！！）",
  ui_story_5043_50430501_53_dialog_content = "本次訴訟由本人史瓦‧薩拉爾擔任審判長。",
  ui_story_5043_50430501_54_dialog_content = "由審判官馬太‧薩耶、蒂娜‧坎貝爾和零恩……",
  ui_story_5043_50430501_55_dialog_content = "以及陪審團成員若干，組成合議庭。",
  ui_story_5043_50430501_56_dialog_content = "（噢！史瓦正經起來還挺有那麼一回事嘛……）",
  ui_story_5043_50430501_57_dialog_content = "若雙方對出庭人員均無異議，即可參加本案之訴訟。",
  ui_story_5043_50430501_58_dialog_content = "等一下，為什麼到了我們這裡就是「若干」人等啦！",
  ui_story_5043_50430501_59_dialog_content = "好的～接著進入本案的法庭調查階段。",
  ui_story_5043_50430501_60_dialog_content = "請原告陳述訴訟請求、事實和理由。",
  ui_story_5043_50430501_61_dialog_content = "嗚嗚嗚嗚……事情是這樣的……",
  ui_story_5043_50430501_62_dialog_content = "我和我的婚約對象，也就是被告，今天一起去中庭的綠地參加月亮沙龍……",
  ui_story_5043_50430501_63_dialog_content = "可是、可是她……",
  ui_story_5043_50430501_64_dialog_content = "請原告有話好好說，不要用哭的～",
  ui_story_5043_50430501_65_dialog_content = "我真的很喜歡她，今年是我們戀愛的第四年，她喜歡的食物是巧克力配咖啡……",
  ui_story_5043_50430501_66_dialog_content = "請原告就重點敘述與本案相關的內容。",
  ui_story_5043_50430501_67_dialog_content = "對、對不起，我真是什麼事都辦不好……",
  ui_story_5043_50430501_68_dialog_content = "我們一起去月亮沙龍，本來開開心心的，沒想到她突然臉色一變，說要跟我分手！",
  ui_story_5043_50430501_69_dialog_content = "我該怎麼跟我家裡人交代啊，嗚嗚……",
  ui_story_5043_50430501_70_dialog_content = "好的。接下來，由被告進行陳述。",
  ui_story_5043_50430501_71_dialog_content = "我會這樣做當然事出有因。",
  ui_story_5043_50430501_72_dialog_content = "這個傢伙，也就是原告，明明跟我出來約會……",
  ui_story_5043_50430501_73_dialog_content = "卻在沙龍上接受別人送給他的禮物！",
  ui_story_5043_50430501_74_dialog_content = "（總覺得這個女生更像原告呢。）",
  ui_story_5043_50430501_75_dialog_content = "我、我沒有……",
  ui_story_5043_50430501_76_dialog_content = "不然你解釋一下，那一籃<color=#FFB400>餅乾</color>是怎麼回事？",
  ui_story_5043_50430501_77_dialog_content = "（一籃餅乾？難不成……）",
  ui_story_5043_50430501_78_dialog_content = "就是這個，這是物證！",
  ui_story_5043_50430501_79_dialog_content = "這個餅乾放在你的座位上，裡面還夾著小卡片。",
  ui_story_5043_50430501_80_dialog_content = "最過分的是，卡片上面還寫著本該只用於我們彼此稱呼的<color=#FFB400>暱稱</color>！",
  ui_story_5043_50430501_81_dialog_content = "完蛋了……",
  ui_story_5043_50430501_82_dialog_content = "果然啊，就如同起訴資料所述顯示，蒂娜準備送出的餅乾被這對情侶撿到了。",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5043_50430501_84_dialog_content = "肅靜～！",
  ui_story_5043_50430501_85_dialog_content = "蔑視法庭的白夜城居民，會被審判長判處死刑哦……開玩笑的啦～",
  ui_story_5043_50430501_86_dialog_content = "<size=32>喂，蒂娜，他們說的餅乾，就是妳弄丟的那一籃吧？</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>咦？是PlayerName的聲音……！</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>不好吧，我們不可以在審判期間偷偷講話。</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>既然這樣，那就——</size>",
  ui_story_5043_50430501_90_option_content = "強制感應！",
  ui_story_5043_50430501_91_dialog_content = "哦，好厲害！這就是空裔的那個能力吧？我總算見識到了！",
  ui_story_5043_50430501_92_dialog_content = "現在不是說這個的時候。事實到底如何？那些餅乾是妳的嗎？",
  ui_story_5043_50430501_93_dialog_content = "是的，是我的！真是的，沒想到我的疏忽讓一對無辜情侶產生如此的誤會……",
  ui_story_5043_50430501_94_dialog_content = "PlayerName，你覺得我應該怎麼做呢？",
  ui_story_5043_50430501_95_option_content = "實話實說",
  ui_story_5043_50430501_96_dialog_content = "我覺得妳應該坦率承認是妳準備了這籃餅乾，並且本來打算送給別人。",
  ui_story_5043_50430501_97_dialog_content = "……只不過，這對妳來說不是適合的告白時機。",
  ui_story_5043_50430501_98_dialog_content = "考量到妳自己的意願，如果妳不想這麼做，我倒也可以理解……",
  ui_story_5043_50430501_99_dialog_content = "唔？告白……什麼告白？",
  ui_story_5043_50430501_100_option_content = "靜觀其變",
  ui_story_5043_50430501_101_dialog_content = "不如等一下，先看接下來有什麼發展！",
  ui_story_5043_50430501_102_dialog_content = "現在隨便站出來，恐怕會被扣上「蔑視法庭」的帽子吧。",
  ui_story_5043_50430501_103_dialog_content = "按照審理流程，接下來要做什麼？",
  ui_story_5043_50430501_104_dialog_content = "唔，接下來的話，就是原告與被告雙方辯護的階段。",
  ui_story_5043_50430501_105_dialog_content = "雖然不太明白PlayerName為何要顧慮這件事，姑且先讓史瓦繼續正式流程吧。",
  ui_story_5043_50430501_106_dialog_content = "看來原告和被告已經迫不及待了，那現在就進入法庭辯論。",
  ui_story_5043_50430501_107_dialog_content = "<size=32>喂，庶民新人，這樣下去不是辦法啊。</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>我們得做點什麼，但是也得顧及到人家蒂娜的面子。</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>我也是這麼想。但我們還不清楚蒂娜的想法。</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>既然她沒主動表示意見，我們不如……就讓史瓦主動去了解這件事如何？</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>這個可行啊！小子真有一套。</size>",
  ui_story_5043_50430501_112_dialog_content = "接下來，請審判官們輪流訊問原告與被告。",
  ui_story_5043_50430501_113_dialog_content = "咳嗯……請問原告，你說這籃餅乾不是你的，那你認為這籃餅乾是誰的？",
  ui_story_5043_50430501_114_dialog_content = "這……我也不知道哇，它某一刻就突然出現在我面前的桌面上。",
  ui_story_5043_50430501_115_dialog_content = "我覺得它可能是<color=#FFB400>被某人留下來</color>了。",
  ui_story_5043_50430501_116_dialog_content = "哦？那照你的猜想，它出現在月亮沙龍又被遺失在月亮沙龍。",
  ui_story_5043_50430501_117_dialog_content = "它的用途，想必在座的各位都可想而知。",
  ui_story_5043_50430501_118_dialog_content = "是的，我想……它應該是一份<color=#FFB400>禮物</color>。",
  ui_story_5043_50430501_119_dialog_content = "只不過這個禮物不屬於我，也跟我毫無關係。",
  ui_story_5043_50430501_120_dialog_content = "那麼接下來請問被告方，妳有何理由堅信妳的戀人收到餅乾即代表對妳不忠？",
  ui_story_5043_50430501_121_dialog_content = "這還用說嗎，這籃餅乾一看就知道是<color=#FFB400>女孩子</color>準備的！",
  ui_story_5043_50430501_122_dialog_content = "他竟然敢收，我看他早就想分手了。",
  ui_story_5043_50430501_123_dialog_content = "這就是妳們的矛盾所在，原告堅稱沒收下餅乾，妳卻認為餅乾是送給原告的。",
  ui_story_5043_50430501_124_dialog_content = "可是，<color=#FFB400>卡片</color>所寫的內容那麼曖昧……",
  ui_story_5043_50430501_125_dialog_content = "好吧！或許是我太武斷。不然那女孩究竟是為誰準備了餅乾？",
  ui_story_5043_50430501_126_dialog_content = "被告，妳終於說到了重點！",
  ui_story_5043_50430501_127_dialog_content = "這一籃餅乾真正的受贈人就在妳的眼前！",
  ui_story_5043_50430501_128_dialog_content = "我的……眼前？",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5043_50430501_130_dialog_content = "零恩審判官、馬太審判官，請別對被告進行引導性質的發言！",
  ui_story_5043_50430501_131_dialog_content = "這裡是審判庭，有罪就是有罪。",
  ui_story_5043_50430501_132_dialog_content = "哎呀～史瓦審判長，您如此英俊且受眾多少女愛慕，怎能打斷淑女的發言呢？",
  ui_story_5043_50430501_133_dialog_content = "一份愛戀您的物證擺在面前，您卻看不出它出自哪位少女之手。",
  ui_story_5043_50430501_134_dialog_content = "啊……！我好像已經明白了，難道說這籃餅乾真正要送的對象，其實就是——",
  ui_story_5043_50430501_135_dialog_content = "唔呃……？",
  ui_story_5043_50430501_136_dialog_content = "肅靜！！！",
  ui_story_5043_50430501_137_dialog_content = "請大家先安靜一下，我有話要說。",
  ui_story_5043_50430501_138_dialog_content = "蒂娜審判官，請勿隨意擾亂案件的審理程序！",
  ui_story_5043_50430501_139_dialog_content = "史瓦審判長，就身為餅乾證物的主人為由，我申請以<color=#FFB400>證人</color>的身分出席。",
  ui_story_5043_50430501_140_dialog_content = "（很好，蒂娜！就是這個氣勢！）",
  ui_story_5043_50430501_141_dialog_content = "好、好吧，本審判長同意。那麼，證人可以開始發言了。",
  ui_story_5043_50430501_142_dialog_content = "這是我製作的餅乾。",
  ui_story_5043_50430501_143_dialog_content = "是我滿懷著激動與忐忑的心，親手製作的餅乾。",
  ui_story_5043_50430501_144_dialog_content = "我緩慢打發奶油、擠出花紋，選出形狀最漂亮的一批，再烤成金黃色。",
  ui_story_5043_50430501_145_dialog_content = "就只為了做出一份最完美的回禮，送給他。",
  ui_story_5043_50430501_146_dialog_content = "沒想到很不湊巧地在剛才的月亮沙龍上弄丟了。",
  ui_story_5043_50430501_147_dialog_content = "那張卡片，就是證明！",
  ui_story_5043_50430501_148_dialog_content = "那是我親手製作的卡片，我可以一字不漏地說出卡片所寫的署名和內容！",
  ui_story_5043_50430501_149_dialog_content = "噢！這真是……沒想到我們竟然可以和失主以這種方式重逢。",
  ui_story_5043_50430501_150_dialog_content = "這也算是一個美好的愛情故事。",
  ui_story_5043_50430501_151_dialog_content = "……真是拿妳們沒辦法啊，妳們這些小百合花，就知道給我製造甜蜜的負擔。",
  ui_story_5043_50430501_152_dialog_content = "既然如此，在法槌落下之前，請證方與被告開始核對證物。",
  ui_story_5043_50430501_153_dialog_content = "既然如此，我們就一起念出卡片上寫的名字吧。",
  ui_story_5043_50430501_154_dialog_content = "好，就這麼辦吧！三、二、一……",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>狗蛋</color>！</size>",
  ui_story_5043_50430501_X156_dialog_content = "啥？？？",
  ui_story_5043_50430501_156_dialog_content = "……咦！！！",
  ui_story_5043_50430501_157_dialog_content = "真是意外啊，史瓦審判長，我早早聽說過您出身名門，風流倜儻。",
  ui_story_5043_50430501_158_dialog_content = "沒想到您在私下竟會使用這麼……「平易近人」的稱呼。",
  ui_story_5043_50430501_159_dialog_content = "下城出身的我不禁開始佩服您了。",
  ui_story_5043_50430501_160_dialog_content = "親愛的，妳終於不再懷疑我了，嗚嗚……",
  ui_story_5043_50430501_161_dialog_content = "「狗蛋」……嘖嘖嘖，還是個有點可愛的名字呢。",
  ui_story_5043_50430501_162_dialog_content = "史瓦，這是你的乳名嗎？還是你小時候的外號？",
  ui_story_5043_50430501_163_dialog_content = "哈哈哈哈哈哈……",
  ui_story_5043_50430501_164_dialog_content = "這……這……",
  ui_story_5043_50430501_165_dialog_content = "等一下！這……這到底是怎麼回事？！",
  ui_story_5043_50430501_166_dialog_content = "是啊，這到底是怎麼回事？",
  ui_story_5043_50430501_167_dialog_content = "這籃餅乾和這張卡片……和史瓦審判長有什麼關係？",
  ui_story_5043_50430601_1_dialog_content = "所以……大致就是這麼一回事。",
  ui_story_5043_50430601_2_dialog_content = "這確實是我為狗蛋準備的禮物，但根據剛才的情況，被告似乎誤會了用意……",
  ui_story_5043_50430601_3_dialog_content = "沒想到事情會發展成這樣，還好原告與被告的誤會成功冰釋。",
  ui_story_5043_50430601_4_dialog_content = "啥？？？",
  ui_story_5043_50430601_5_dialog_content = "不僅是那兩位涉案人，我們也誤會了吧？",
  ui_story_5043_50430601_6_dialog_content = "「狗蛋」又是誰？原來你喜歡的人不是這個笨蛋審判長啊！",
  ui_story_5043_50430601_7_dialog_content = "確實有點不對勁……但究竟是在哪個環節理解錯誤啊？",
  ui_story_5043_50430601_8_dialog_content = "對不起，因為這件事有點見不得人，所以我說得也很模糊。",
  ui_story_5043_50430601_9_dialog_content = "在求大家幫忙之前，沒有和大家確認清楚，都是我的疏失……！",
  ui_story_5043_50430601_10_dialog_content = "不過話說回來，為什麼剛才在法庭上，連史瓦審判長也會錯意呢？",
  ui_story_5043_50430601_11_dialog_content = "我們兩個人除了正常的工作接觸、社交接觸之外，並沒有太多交集吧？",
  ui_story_5043_50430601_12_dialog_content = "一個人到底是不是真的喜歡自己，難道不該清晰地感受到嗎？",
  ui_story_5043_50430601_13_dialog_content = "別說了……不要再說了……",
  ui_story_5043_50430601_14_dialog_content = "這些……這些全部都不是重點吧……重要的是……",
  ui_story_5043_50430601_15_dialog_content = "<size=45>現在審判庭內的所有人都認為本審判長的別名叫狗蛋！！！</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>初階法官跟那幾個審判官肯定已經把消息傳出去了！！！</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>用不了多久，整個高庭貴族社交圈都會知道這個大新聞！！！</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>全都是因為你們幾個還有那噁心無比的餅乾和卡片！！！</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>你們這幫滿腦子戀愛的混蛋男女，再加上只會黏過來添亂子的女人……</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>全都是一丘之貉！！！</size>",
  ui_story_5043_50430601_21_dialog_content = "真、真的非常抱歉！！！",
  ui_story_5043_50430601_22_dialog_content = "喂，史瓦。就算是蒂娜有錯在先，你也沒必要說得這麼過分吧。",
  ui_story_5043_50430601_23_dialog_content = "我不清楚期間發生了什麼事情，但蒂娜知道心中另有所屬，真是個好消息。",
  ui_story_5043_50430601_24_dialog_content = "……………………",
  ui_story_5043_50430601_25_dialog_content = "呼……",
  ui_story_5043_50430601_26_dialog_content = "繼續談你們剛才報告的事情吧。",
  ui_story_5043_50430601_27_dialog_content = "中庭草地上被打碎的雕像，跟「斷頭雕像案」的原告彼瑪隆沒多大關聯。",
  ui_story_5043_50430601_28_dialog_content = "但這純屬你們運氣好，別再讓他帶著新的訴訟狀過來了。",
  ui_story_5043_50430601_29_dialog_content = "趕快去準備你們的雕像案開庭吧，快滾。",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>高庭‧審判庭外</color>",
  ui_story_5043_50430601_31_dialog_content = "噗～",
  ui_story_5043_50430601_32_dialog_content = "你們幾個，剛才有沒有留意到史瓦的表情？",
  ui_story_5043_50430601_33_dialog_content = "蒂娜小姐，真有妳的啊！剛才那幾句話真是太狠了。",
  ui_story_5043_50430601_34_dialog_content = "呵呵，那傢伙哪可能聽過女性對他說這種話。",
  ui_story_5043_50430601_35_dialog_content = "啊，你們兩個別再嘲笑我啦……",
  ui_story_5043_50430601_36_dialog_content = "對不起，讓大家陪著我挨罵了。",
  ui_story_5043_50430601_37_dialog_content = "沒關係，挨罵是無所謂，但我此刻很想知道——",
  ui_story_5043_50430601_38_dialog_content = "蒂娜不是說過嗎？在史瓦家的莊園裡碰到了「他」？",
  ui_story_5043_50430601_39_dialog_content = "不是史瓦的話，究竟會是誰？",
  ui_story_5043_50430601_40_dialog_content = "好像真的造成了天大的誤會呢。",
  ui_story_5043_50430601_41_dialog_content = "讓我來從頭說明一遍吧……",
  ui_story_5043_50430601_42_dialog_content = "當時我在薩拉爾莊園的花園中，確實碰到了獨自喝茶看書的史瓦。",
  ui_story_5043_50430601_43_dialog_content = "史瓦立刻查覺到我的存在，他也沒料到會有人闖進那麼隱祕的地方。",
  ui_story_5043_50430601_44_dialog_content = "但他卻只看到了我，完全沒發現現場還有其他不屬於該處的東西。",
  ui_story_5043_50430601_45_dialog_content = "史瓦背後的灌木叢中，狗蛋只露出一個毛茸茸的小腦袋，瑟瑟發抖和我對視。",
  ui_story_5043_50430601_46_dialog_content = "牠似乎很擔心我洩漏牠的藏身之處，畢竟一隻暗鬼壓根不該出現在那種地方。",
  ui_story_5043_50430601_47_dialog_content = "但牠分明是那麼可愛又毫無攻擊性，這小可憐，也在路徑複雜的花園中迷路了。",
  ui_story_5043_50430601_48_dialog_content = "史瓦發現我之前，我還看到牠悄悄幫認真看書的史瓦趕走了趴在茶杯上的飛蟲。",
  ui_story_5043_50430601_49_dialog_content = "舞會結束後，我立刻返回花園，拉著牠的手，帶牠離開了薩拉爾莊園。",
  ui_story_5043_50430601_50_dialog_content = "為了防止我們的光能和暗能互相干擾，我還特地戴上新買的手套。",
  ui_story_5043_50430601_51_dialog_content = "牠懂光靈通用語，也會說簡單詞語，跟牠告別後不久，我就在冠月節收到了謝禮。",
  ui_story_5043_50430601_52_dialog_content = "以上就是全部的事實。",
  ui_story_5043_50430601_53_dialog_content = "（原來連這麼普通的小暗鬼也有屬於自己的名字啊……）",
  ui_story_5043_50430601_54_dialog_content = "等等，那「牠再也不回應妳的消息」又是怎樣？",
  ui_story_5043_50430601_55_dialog_content = "因為牠在白夜城沒有固定住所嘛，我按照謝禮的地址回信給牠，卻如石沉大海。",
  ui_story_5043_50430601_56_dialog_content = "還有「沒有和牠偷偷見面的機會」這件事？",
  ui_story_5043_50430601_57_dialog_content = "是啊，那之後我不僅沒和牠偷偷見面，甚至壓根找不到牠的行蹤。",
  ui_story_5043_50430601_58_dialog_content = "「牠走到哪裡都會引起別人注意」的話又是……",
  ui_story_5043_50430601_59_dialog_content = "嗯，這一點你們應該也明白吧，白夜城裡的暗鬼就如同過街老鼠啊。",
  ui_story_5043_50430601_60_dialog_content = "所以……妳那時候說「這種心情不算是戀愛」……",
  ui_story_5043_50430601_61_dialog_content = "暗鬼這玩意向來以侵害光靈為生，世界上有無害的暗鬼嗎？",
  ui_story_5043_50430601_62_dialog_content = "如果真是這樣，我還挺想親眼見識。",
  ui_story_5043_50430601_63_dialog_content = "這對光靈來說是一種多餘的情感，但稱之為「戀愛」未免太奇怪了。",
  ui_story_5043_50430601_64_dialog_content = "與其用這種曖昧的詞彙描述，我更想要的是照顧牠。",
  ui_story_5043_50430601_64X1_dialog_content = "但無論怎麼說，暗鬼這種生物也太噁心了。",
  ui_story_5043_50430601_64X2_dialog_content = "嗅嗅、嗅嗅……",
  ui_story_5043_50430601_64X3_dialog_content = "蒂娜小姐，不是我危言聳聽，妳身上好像有一股暗鬼的臭味。",
  ui_story_5043_50430601_64X4_dialog_content = "咦？隔了這麼久都能聞到嗎……不好意思……",
  ui_story_5043_50430601_65_dialog_content = "我事先聲明，白夜城的法律是一道鐵壁，我不會因此對牠網開一面。",
  ui_story_5043_50430601_66_dialog_content = "雖然守衛隊的追捕清單上，還沒有出現妳說的那隻暗鬼。",
  ui_story_5043_50430601_67_dialog_content = "不過，這件事到此也該告一段落了吧？",
  ui_story_5043_50430601_68_dialog_content = "唔……謝謝卡蓮殿下，我身為審判庭的人，自然懂得其中的利弊……",
  ui_story_5043_50430601_69_dialog_content = "對光靈來說，收養暗鬼本來就是天方夜譚。",
  ui_story_5043_50430601_69X1_dialog_content = "很抱歉給大家添麻煩了……接下來，我們回歸案件，努力調查吧。",
  ui_story_5043_50430601_69X2_dialog_content = "也不能完全說是添麻煩，這不是還遇上了有意思的事情嗎？",
  ui_story_5043_50430601_70_dialog_content = "蒂娜，妳這個人……真是把戀愛分部所有人都耍了一遍啊。",
  ui_story_5043_50430601_71_dialog_content = "哈哈哈哈哈！是啊，選擇跟你們一塊工作真是太正確了！",
  ui_story_5043_50430601_72_dialog_content = "果然碰到了比我預想中更有意思的事情。",
  ui_story_5043_50430601_74_dialog_content = "哈哈……雖然案件進度停滯不前，禮物還鬧了烏龍。",
  ui_story_5043_50430601_75_dialog_content = "但是！我的心情和大家也是一樣的……",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50430601_77_dialog_content = "蒂娜？！蒂娜！",
  ui_story_5043_50430601_78_dialog_content = "她是怎麼了……你們幾個別在旁邊發呆啊！快來幫忙！",
  ui_story_5043_50430601_79_dialog_content = "呼～放心吧，公主殿下，這位小姐只是睡著了。",
  ui_story_5043_50430601_80_dialog_content = "今天發生了這麼多事，八成是累得撐不住了吧。",
  ui_story_5043_50430601_81_dialog_content = "我把我家傭人和馬車叫過來，送蒂娜回家吧。",
  ui_story_5043_50430601_82_dialog_content = "呼、呼，卡蓮殿下……",
  ui_story_5043_50430601_83_dialog_content = "哎呀～洛維，若想當我家的傭人，門檻可不低哦～",
  ui_story_5043_50430601_84_dialog_content = "快說，有什麼事？",
  ui_story_5043_50430601_85_dialog_content = "卡蓮殿下，您猜得沒錯。",
  ui_story_5043_50430601_86_dialog_content = "那幫衛兵全都帶著特洛伊家徽。",
  ui_story_5043_50430601_87_dialog_content = "此外，我還發現，沙龍這地方也挺詭異。",
  ui_story_5043_50430601_88_dialog_content = "怎麼說？",
  ui_story_5043_50430601_89_dialog_content = "每次月亮沙龍結束，暗鬼的騷亂就隨之而來。",
  ui_story_5043_50430601_90_dialog_content = "沙龍場地附近的雕像的頭部也會跟著失蹤。",
  ui_story_5043_50430601_91_dialog_content = "抱歉，我已經盡力了。",
  ui_story_5043_50430601_92_dialog_content = "……",
  ui_story_5043_50430601_93_dialog_content = "辛苦你了，洛維。",
  ui_story_5043_50430601_94_dialog_content = "很快就可以休息了，馬上。",
  ui_story_5043_50430702_1_dialog_content = "既然摸清楚了衛兵的來歷，我也不能再坐視不管。",
  ui_story_5043_50430702_2_dialog_content = "PlayerName，我要去跟高庭衛隊開會，制定下一步的應對計畫。",
  ui_story_5043_50430702_3_dialog_content = "順便讓讓城主知悉最近的暗鬼亂象。",
  ui_story_5043_50430702_4_dialog_content = "快去吧，不必為我們擔心。",
  ui_story_5043_50430702_5_dialog_content = "嗯。我最晚會在開庭當日跟你們會合一次。",
  ui_story_5043_50430702_6_dialog_content = "保重吧。",
  ui_story_5043_50430702_7_dialog_content = "今天大家都很累了，我們也先各自回去吧。",
  ui_story_5043_50430702_8_dialog_content = "至於明天的工作計畫……",
  ui_story_5043_50430702_9_dialog_content = "明天要做什麼，各位也很清楚了吧？",
  ui_story_5043_50430702_10_dialog_content = "這麼可疑的沙龍，主辦人該等著收傳票了。",
  ui_story_5043_50430702_11_dialog_content = "按照目前情況，這個沙龍確實有不少引人疑竇之處……",
  ui_story_5043_50430702_12_dialog_content = "這樣吧，我們明天循著月亮熱氣球的方向，去找那位修女。",
  ui_story_5043_50430702_13_dialog_content = "誰來跟我解釋一下剛才發生了什麼事。",
  ui_story_5043_50430702_14_dialog_content = "以及蒂娜怎麼又睡趴了？",
  ui_story_5043_50430702_15_dialog_content = "真麻煩，等回去的路上我再仔細跟你解釋吧。",
  ui_story_5043_50430702_16_dialog_content = "馬車到了，我們先送蒂娜回去。PlayerName、零恩，明天見。",
  ui_story_5043_50430702_17_dialog_content = "咦？",
  ui_story_5043_50430702_18_dialog_content = "什麼事？",
  ui_story_5043_50430702_19_dialog_content = "怎麼不是叫我「庶民新人」？",
  ui_story_5043_50430702_20_dialog_content = "煩死了！",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50430702_22_dialog_content = "哦……原來是這樣啊。",
  ui_story_5043_50430702_23_dialog_content = "沒錯，每次月亮沙龍的地點，都經過我的精挑細選。",
  ui_story_5043_50430702_24_dialog_content = "我喜歡更有人文氣息的場地，所以尤其偏好附近佇立著雕像的地方。",
  ui_story_5043_50430702_25_dialog_content = "那些「老人」、「男人」、「孩童」，還有你們剛才說的兩座受損的「女人」。",
  ui_story_5043_50430702_26_dialog_content = "都是白夜城文明的基石。",
  ui_story_5043_50430702_27_dialog_content = "可是所有沙龍地點的雕像都出了問題也是不爭的事實。",
  ui_story_5043_50430702_28_dialog_content = "嗯，我並不打算否認沙龍造成的混亂，也沒有任何不在場證明。但是……",
  ui_story_5043_50430702_29_dialog_content = "白夜至上，無論是打碎的雕像還是圍過來的暗鬼，都跟我沒有關係。",
  ui_story_5043_50430702_30_dialog_content = "（這位修女的表情非常平靜，就像她的語調一樣柔和又毫無波瀾。）",
  ui_story_5043_50430702_31_dialog_content = "（而且氣場也非常強大，這就是信仰的力量嗎……）",
  ui_story_5043_50430702_32_dialog_content = "（憑我的感覺……她真的跟案件沒什麼關係。）",
  ui_story_5043_50430702_33_dialog_content = "嘖……又碰到瓶頸了。但我們也不能單靠嫌疑就亂抓人。",
  ui_story_5043_50430702_34_dialog_content = "修女閣下，光之神在上，若您所言句句屬實……",
  ui_story_5043_50430702_35_dialog_content = "您是否願意在案件審理當日出庭作證？",
  ui_story_5043_50430702_36_dialog_content = "我近期因沙龍的事鎮日忙碌，但若這是審判庭的意思。",
  ui_story_5043_50430702_37_dialog_content = "我可以盡力配合。",
  ui_story_5043_50430702_38_dialog_content = "可是……！",
  ui_story_5043_50430702_39_dialog_content = "（如果把她帶到審判庭，會不會帶給她多餘的麻煩啊……）",
  ui_story_5043_50430702_40_dialog_content = "……哎呀？小姑娘，妳好像有話想說呢？",
  ui_story_5043_50430702_41_dialog_content = "我想知道，您如何做到這麼坦然？",
  ui_story_5043_50430702_42_dialog_content = "我並不討厭月亮沙龍，相反地還很喜歡沙龍的氛圍，它讓白夜城變了副樣子。",
  ui_story_5043_50430702_43_dialog_content = "但在白夜城的規矩中，別說是自由戀愛了，連離婚都不被常識所接受。",
  ui_story_5043_50430702_44_dialog_content = "您頂著神職人員的身分，又是如此虔誠的信徒……",
  ui_story_5043_50430702_45_dialog_content = "為什麼下定決心，為白夜城的民眾們創辦這個沙龍？",
  ui_story_5043_50430702_46_dialog_content = "您甚至連去審判庭這樣的地方都不怕……這種心態讓我非常敬佩。",
  ui_story_5043_50430702_47_dialog_content = "蒂娜……",
  ui_story_5043_50430702_48_dialog_content = "呵呵……孩子，這是妳自己的困擾與思考嗎？",
  ui_story_5043_50430702_49_dialog_content = "其實到了我這個年紀，反而不會產生這麼多瞻前顧後的念頭。",
  ui_story_5043_50430702_50_dialog_content = "我只是在聽從自己信仰著光之神的心。",
  ui_story_5043_50430702_51_dialog_content = "白夜城在漫長的歷史下演化出禁慾的等級制度和各種繁文縟節。",
  ui_story_5043_50430702_52_dialog_content = "但在最初也不外乎是由老人、男人、女人、孩童這些普通又聖潔的光靈所建立。",
  ui_story_5043_50430702_53_dialog_content = "光之神的教義也在歷史長河中數度更迭演變。",
  ui_story_5043_50430702_54_dialog_content = "但它們在誕生之初都是既簡單又至真至善的東西。",
  ui_story_5043_50430702_55_dialog_content = "那些東西，是光之神真正的賜福與教誨。",
  ui_story_5043_50430702_56_dialog_content = "我現在所做的事情不過是回歸光靈的原點，遵從本心而已。",
  ui_story_5043_50430702_57_dialog_content = "這件事本來並沒有造成罪孽，只是不被規則與制度所接納，僅此而已。",
  ui_story_5043_50430702_58_dialog_content = "信仰呀、戀愛呀……都是一樣的道理。",
  ui_story_5043_50430702_59_dialog_content = "我、我似乎明白您的意思了，十分感謝您的解惑。",
  ui_story_5043_50430702_60_dialog_content = "這樣的話，我就先告辭了。",
  ui_story_5043_50430702_61_dialog_content = "後續的相關調查，我也會繼續配合。",
  ui_story_5043_50430702_62_dialog_content = "不過，審判庭的諸位，如果你們遇到困難，也可以聽一聽我的建議。",
  ui_story_5043_50430702_63_dialog_content = "唔......？",
  ui_story_5043_50430702_64_dialog_content = "要是你們真的想在開庭前獲得更有用的資訊，而非應付工作流程的話……",
  ui_story_5043_50430702_65_dialog_content = "就該摒除機械性的目的，多方思考原告本人的真實想法。",
  ui_story_5043_50430702_66_dialog_content = "多謝您的忠告，我們會多加考慮的……",
  ui_story_5043_50430702_67_dialog_content = "嗯～就這樣吧，下次再會。",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>又過了一天</color>",
  ui_story_5043_50430801_2_dialog_content = "這就是全部的調查結果？",
  ui_story_5043_50430801_3_dialog_content = "別說解決之前的問題了，居然又有其他雕像被打破？！",
  ui_story_5043_50430801_4_dialog_content = "非常抱歉，案件還在調查中，目前還沒有突破性進展……",
  ui_story_5043_50430801_5_dialog_content = "這不叫沒有「突破性」進展，這叫毫無進展！！！",
  ui_story_5043_50430801_6_dialog_content = "堂堂白夜城的審判庭，就這點辦事效率？",
  ui_story_5043_50430801_7_dialog_content = "我還不如去找一條瞎掉的老狗，好歹能嗅出犯人的氣味！",
  ui_story_5043_50430801_8_dialog_content = "對不起，我們盡量提高效率……",
  ui_story_5043_50430801_9_dialog_content = "我算是看清了，審判庭根本不重視民眾的感情問題！",
  ui_story_5043_50430801_10_dialog_content = "看看這個所謂的「戀愛法庭」，都養了群怎樣的飯桶！",
  ui_story_5043_50430801_11_dialog_content = "領著審判庭的高工資，每天上班都在睡覺嗎！",
  ui_story_5043_50430801_12_dialog_content = "無法反駁，確實是有那樣的人在。",
  ui_story_5043_50430801_13_dialog_content = "睡、睡覺對工作也很有幫助啦……",
  ui_story_5043_50430801_14_dialog_content = "我的耐心用完了，後天就是開庭日。",
  ui_story_5043_50430801_15_dialog_content = "我話就說到這裡，明天之前，如果你們拿不出成果，我就要繼續起訴那個鄰居。",
  ui_story_5043_50430801_16_dialog_content = "否則我就去找伊倫汀大人投訴！",
  ui_story_5043_50430801_17_dialog_content = "握著高額收入，卻沒能力為民眾解決問題。這樣的法庭不如拆掉算了！",
  ui_story_5043_50430801_18_dialog_content = "拆掉？！",
  ui_story_5043_50430801_19_dialog_content = "欸，有這麼嚴重嗎？",
  ui_story_5043_50430801_20_dialog_content = "彼瑪隆先生，請您千萬別衝動……",
  ui_story_5043_50430801_21_dialog_content = "哼，你們好自為之吧！",
  ui_story_5043_50430801_22_dialog_content = "走、走掉了……",
  ui_story_5043_50430801_23_dialog_content = "不妙啊，看來戀愛法庭的處境比我想像的還糟。",
  ui_story_5043_50430801_24_dialog_content = "好啦，這下徹底完蛋啦。",
  ui_story_5043_50430801_25_dialog_content = "伊倫汀審判長最在乎民眾的意見反饋，要是她收到投訴……",
  ui_story_5043_50430801_26_dialog_content = "是啊，審判長大人一定會非常生氣。",
  ui_story_5043_50430801_27_dialog_content = "作為一個臨時設立的法庭，一旦上頭覺得戀愛法庭沒發揮作用……",
  ui_story_5043_50430801_28_dialog_content = "搞不好這裡真的立刻會被廢除。",
  ui_story_5043_50430801_29_dialog_content = "沒想到還真被我給說中了……",
  ui_story_5043_50430801_30_dialog_content = "事情發展至此，就算你們都被卸任也不奇怪。",
  ui_story_5043_50430801_31_dialog_content = "卸任？！",
  ui_story_5043_50430801_32_dialog_content = "這麼嚴重？絕對不行！",
  ui_story_5043_50430801_33_dialog_content = "請、請不要說那麼可怕的話……",
  ui_story_5043_50430801_34_dialog_content = "卸任之後我只能百無聊賴待在家裡，沒辦法找樂子了！",
  ui_story_5043_50430801_35_dialog_content = "等等……你在意的就是這個？！",
  ui_story_5043_50430801_36_dialog_content = "我要去哪找到另一份能在白天睡覺的工作啊……",
  ui_story_5043_50430801_37_dialog_content = "這一份工作也不能在白天睡覺吧！",
  ui_story_5043_50430801_38_dialog_content = "若是找不到工作，他們就會把我抓回家裡。",
  ui_story_5043_50430801_39_dialog_content = "強迫我繼承家族事業……",
  ui_story_5043_50430801_40_dialog_content = "是啊是啊，家裡那幫老頑固就是這樣。",
  ui_story_5043_50430801_41_dialog_content = "誰有興趣幫他們數白夜幣啊！",
  ui_story_5043_50430801_42_dialog_content = "擅自替你們這些貴族操心還真是多管閒事……",
  ui_story_5043_50430801_43_dialog_content = "聽起來丟掉工作也沒什麼大不了嘛！大家開心點吧！",
  ui_story_5043_50430801_44_dialog_content = "是啊，就算真的失去工作，生活還是得繼續。",
  ui_story_5043_50430801_45_dialog_content = "只不過，沒有薪水的話……就得囤積一些馬鈴薯和蔬菜了。",
  ui_story_5043_50430801_46_dialog_content = "明天開始一天只吃一餐吧。",
  ui_story_5043_50430801_47_dialog_content = "等一下，怎麼事情到你身上突然就沉重起來了！",
  ui_story_5043_50430801_48_dialog_content = "生活在白夜城就是一件很沉重的事情呀。",
  ui_story_5043_50430801_49_dialog_content = "要購買食物，應付維持正常社交的開支，活著的每一天都需要花錢。",
  ui_story_5043_50430801_50_dialog_content = "失去收入來源的話，就必須精打細算。",
  ui_story_5043_50430801_51_dialog_content = "好沉重，生活好沉重啊……",
  ui_story_5043_50430801_52_dialog_content = "還不到放棄的時候。我們還有一天的時間，趁現在想點辦法吧！",
  ui_story_5043_50430801_53_dialog_content = "是的，只要拿出實際行動，說不定案件會有所進展。",
  ui_story_5043_50430801_54_dialog_content = "但目前最大的問題是，我們一條線索也沒有。",
  ui_story_5043_50430801_55_dialog_content = "該往哪個方向努力呢……",
  ui_story_5043_50430801_56_dialog_content = "女士先生們，我有個想法！",
  ui_story_5043_50430801_57_dialog_content = "我仔細思考了一下，之前我們的思維太過侷限。",
  ui_story_5043_50430801_58_dialog_content = "這起「連環斷頭雕像案」並非普通的刑事案件。",
  ui_story_5043_50430801_59_dialog_content = "因為受害者是雕像，我們無法透過社會關係推論兇手的動機。",
  ui_story_5043_50430801_60_dialog_content = "同樣的，也因為受害者是雕像，我們無法追蹤血跡來尋找犯人行蹤。",
  ui_story_5043_50430801_61_dialog_content = "是的，這些都是我們所面臨的阻礙。",
  ui_story_5043_50430801_62_dialog_content = "但是，讓我們跳脫出來思考一下～",
  ui_story_5043_50430801_63_dialog_content = "雕像遭到破壞之所以能成為案件，是因為一個非常關鍵的因素——",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>戀愛</color>！",
  ui_story_5043_50430801_65_dialog_content = "沒錯～是愛情讓戀愛分部不得不受理這起案件。",
  ui_story_5043_50430801_66_dialog_content = "任何事情一旦有了愛情糾葛，便不能用單純的理性視角看待。",
  ui_story_5043_50430801_67_dialog_content = "所以我們如今面對的並非一起案件，而是一場情感糾紛！",
  ui_story_5043_50430801_68_dialog_content = "唔唔……思路彷彿豁然開朗！",
  ui_story_5043_50430801_69_dialog_content = "等一下，我好像沒有跟上……",
  ui_story_5043_50430801_70_dialog_content = "……你們要不要聽聽自己在說些什麼？",
  ui_story_5043_50430801_71_dialog_content = "我們找不到線索，但解決問題也許並不需要線索。",
  ui_story_5043_50430801_72_dialog_content = "我親愛的朋友們～愛情之中，並非每件事都需要追根究柢。",
  ui_story_5043_50430801_73_dialog_content = "重要的是心意。",
  ui_story_5043_50430801_74_dialog_content = "想想那個修女說的話吧。",
  ui_story_5043_50430801_75_dialog_content = "要是你們真的想在開庭前獲得更有用的資訊，而非應付工作流程的話……",
  ui_story_5043_50430801_76_dialog_content = "就該摒除機械性的目的，多方思考原告本人的真實想法。",
  ui_story_5043_50430801_77_dialog_content = "……用心意就可以解決嗎？",
  ui_story_5043_50430801_78_dialog_content = "行動起來吧，朋友們。",
  ui_story_5043_50430801_79_dialog_content = "讓我們為那位原告先生準備一個飽含愛意的答案！",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50430801_81_dialog_content = "喂！別在這裡擋路！",
  ui_story_5043_50430801_82_dialog_content = "快讓我進去！",
  ui_story_5043_50430801_83_dialog_content = "彼瑪隆先生，請您稍候。",
  ui_story_5043_50430801_84_dialog_content = "審判官們正在法庭內處理公務。",
  ui_story_5043_50430801_85_dialog_content = "等到有時間接待您的時候，我們會第一時間讓您通過。",
  ui_story_5043_50430801_86_dialog_content = "處理公務？別胡扯了，我的案子就是他們的公務！",
  ui_story_5043_50430801_87_dialog_content = "想用閉門不出的方式躲著我，好歹編個像樣的理由吧！",
  ui_story_5043_50430801_88_dialog_content = "彼瑪隆先生，審判官們真的是在……",
  ui_story_5043_50430801_89_dialog_content = "我不管他們在做什麼，現在是審判庭的工作時間。",
  ui_story_5043_50430801_90_dialog_content = "等、等一下，先生……",
  ui_story_5043_50430801_91_dialog_content = "讓開！",
  ui_story_5043_50430801_92_dialog_content = "哎呀，這……",
  ui_story_5043_50430801_93_dialog_content = "<size=45>馬太審判官！他進去了！！！</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>啪——！啪——！啪——！</color>",
  ui_story_5043_50430801_95_dialog_content = "彼瑪隆先生，恭喜您！",
  ui_story_5043_50430801_96_dialog_content = "可喜可賀、可喜可賀！",
  ui_story_5043_50430801_97_dialog_content = "恭喜您在原本平凡的今天——重新找回您的愛情！",
  ui_story_5043_50430801_98_dialog_content = "啥？這是……",
  ui_story_5043_50430801_99_dialog_content = "我們花了一天的時間，為您的雕像重新製作了頭部。",
  ui_story_5043_50430801_100_dialog_content = "如果您晚一點進來……我們還能刻畫得更精緻！",
  ui_story_5043_50430801_101_dialog_content = "沒錯～這正是我們重新思考愛情之後想出的解決方法。",
  ui_story_5043_50430801_102_dialog_content = "重要的不是失去過什麼，而是能擁有什麼。",
  ui_story_5043_50430801_103_dialog_content = "難道雕像的頭部被破壞就能阻止您追求愛情嗎？",
  ui_story_5043_50430801_104_dialog_content = "不，您仍然渴望愛情，只是在為它的不完整而感到惋惜。",
  ui_story_5043_50430801_105_dialog_content = "想要化解您內心的悲痛，唯有讓它重新變得完整。",
  ui_story_5043_50430801_106_dialog_content = "呵呵，失而復得的故事總是如此美妙……",
  ui_story_5043_50430801_107_dialog_content = "你、你們……",
  ui_story_5043_50430801_108_dialog_content = "<size=45>看看你們做的好事！</size>",
  ui_story_5043_50430801_109_dialog_content = "加拉泰婭脖子上那顆醜陋的腫瘤是什麼意思？是想侮辱我嗎？！",
  ui_story_5043_50430801_110_dialog_content = "呃，醜陋？",
  ui_story_5043_50430801_111_dialog_content = "看來您不太喜歡呢……",
  ui_story_5043_50430801_112_dialog_content = "嘖嘖，我就說庶民新人的審美觀不可靠。",
  ui_story_5043_50430801_113_dialog_content = "您要是對這個形象不滿意，我們再重新製作一個……",
  ui_story_5043_50430801_114_dialog_content = "別開玩笑了！你們的愚蠢行為是一種對愛情的褻瀆！！！",
  ui_story_5043_50430801_115_dialog_content = "一群小毛頭，你們懂愛情嗎？！",
  ui_story_5043_50430801_116_dialog_content = "愛情就是唯一！是一旦愛上就一生不變的選擇！！！",
  ui_story_5043_50430801_117_dialog_content = "打從加拉泰婭被毀的那一刻，我的愛情就已經死亡了！！！",
  ui_story_5043_50430801_118_dialog_content = "哪怕復原出一模一樣的頭部，它也不再是加拉泰婭！！！",
  ui_story_5043_50430801_119_dialog_content = "不再是我心中唯一的愛人！！！",
  ui_story_5043_50430801_120_dialog_content = "啊，原來是這樣的道理……！",
  ui_story_5043_50430801_121_dialog_content = "呃……所以我昨天想錯了。",
  ui_story_5043_50430801_122_dialog_content = "果然失敗了。看來戀愛法庭還是逃不過……",
  ui_story_5043_50430801_123_dialog_content = "算了，這個先不討論。",
  ui_story_5043_50430801_124_dialog_content = "今天我來找你們是有更重要的事情。",
  ui_story_5043_50430801_125_dialog_content = "此時此刻，我的「<color=#FFB400>妻子</color>」正面臨生命威脅。",
  ui_story_5043_50430801_126_dialog_content = "看在愛情的份上，請你們立刻派人去保護她的安全！",
  ui_story_5043_50430801_127_dialog_content = "等、等一下！您的妻子正面臨生命威脅？",
  ui_story_5043_50430801_128_dialog_content = "她不是在這裡嗎？",
  ui_story_5043_50430801_129_dialog_content = "你們搞錯了，加拉泰婭是我的「<color=#FFB400>愛人</color>」。",
  ui_story_5043_50430801_130_dialog_content = "而現在面臨生命威脅的是我的「<color=#FFB400>妻子</color>」，這兩個不一樣。",
  ui_story_5043_50430801_131_dialog_content = "啥啊？！",
  ui_story_5043_50430801_132_dialog_content = "妻子和愛人是不一樣的？！",
  ui_story_5043_50430801_133_dialog_content = "那當然。我的妻子是另一尊美麗的雕像，名字叫「阿芙洛狄婭」。",
  ui_story_5043_50430801_134_dialog_content = "怎麼這樣，不是說愛情是唯一的嗎！",
  ui_story_5043_50430801_135_dialog_content = "當然是唯一的！",
  ui_story_5043_50430801_136_dialog_content = "那你怎麼能同時愛著兩尊雕像？",
  ui_story_5043_50430801_137_dialog_content = "因為愛情同時也是寬容的。",
  ui_story_5043_50430801_138_dialog_content = "我愛著我的妻子，也愛著我的愛人，這兩份愛都是唯一無二。",
  ui_story_5043_50430801_139_dialog_content = "舉個例子來說，你愛自己母親的同時，就不能愛自己的父親嗎？",
  ui_story_5043_50430801_140_dialog_content = "這麼一說，好像也有點道理……",
  ui_story_5043_50430801_141_dialog_content = "不對！！這根本不是可以拿來相比的關係吧？",
  ui_story_5043_50430801_142_dialog_content = "好了，我沒時間教你們年輕人理解愛情。",
  ui_story_5043_50430801_143_dialog_content = "就在方才，我看見月亮熱氣球在「千星階梯」上方升起。",
  ui_story_5043_50430801_144_dialog_content = "那裡正是我妻子所在之處。",
  ui_story_5043_50430801_145_dialog_content = "你們也知道，月亮熱氣球是沙龍舉辦的標誌，而雕像被毀的事件總發生在沙龍之時。",
  ui_story_5043_50430801_146_dialog_content = "要是這次我的妻子再有什麼閃失……我……我就徹底失去愛情了……",
  ui_story_5043_50430801_147_dialog_content = "保護民眾的愛情是你們該做的事情，對吧？",
  ui_story_5043_50430801_148_dialog_content = "既然接手了這個案子，我們當然會保護您的愛情。",
  ui_story_5043_50430801_149_dialog_content = "嘖，是他「二分之一的愛情」。",
  ui_story_5043_50430801_150_dialog_content = "況且那裡可能發生新的案件，或許能在現場找到線索。",
  ui_story_5043_50430801_151_dialog_content = "為了破獲這起「連環斷頭雕像案」，我們一定要去！",
  ui_story_5043_50430801_152_dialog_content = "那還等什麼呢，快出發吧！",
  ui_story_5043_50430801_153_dialog_content = "月亮熱氣球下的沙龍就快開始了！",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>中庭‧千星階梯附近</color>",
  ui_story_5043_50430801_155_dialog_content = "瞧，前面就是了。",
  ui_story_5043_50430801_156_dialog_content = "彼瑪隆先生說他的妻子就在這裡，那它就是……",
  ui_story_5043_50430801_157_dialog_content = "找到了！應該是這個沒錯！",
  ui_story_5043_50430801_158_dialog_content = "哦！目前還完好！",
  ui_story_5043_50430801_159_dialog_content = "保護好它就可以了吧？",
  ui_story_5043_50430801_160_dialog_content = "是的，犯人可能會在沙龍期間對它出手。",
  ui_story_5043_50430801_161_dialog_content = "不過，參加沙龍的人都去哪裡了呢？",
  ui_story_5043_50430801_162_dialog_content = "我看到了！他們都聚集在階梯底下！",
  ui_story_5043_50430801_163_dialog_content = "真是的，他們不打算上來嗎？",
  ui_story_5043_50430801_164_dialog_content = "哎呀，那樣的話就是我們走好運。",
  ui_story_5043_50430801_165_dialog_content = "若沙龍在階梯下面舉行，想保護上面的雕像豈不是更輕鬆了嗎。",
  ui_story_5043_50430801_166_dialog_content = "太好了，這樣也容易跟彼瑪隆先生交差……",
  ui_story_5043_50430801_167_dialog_content = "噢，這不是幾位審判官大人嗎？",
  ui_story_5043_50430801_168_dialog_content = "修女姐姐！沒想到這麼快又見面了。",
  ui_story_5043_50430801_169_dialog_content = "這裡是月亮熱氣球之下，見到我是理所當然的事啊。",
  ui_story_5043_50430801_170_dialog_content = "既然來了，就一起參加今天的活動吧。",
  ui_story_5043_50430801_171_dialog_content = "是在階梯下面舉辦的沙龍嗎？",
  ui_story_5043_50430801_172_dialog_content = "我們很有興趣，不過今天還有其他……",
  ui_story_5043_50430801_173_dialog_content = "不是哦，今天的活動不是沙龍。",
  ui_story_5043_50430801_174_dialog_content = "咦，那是……？",
  ui_story_5043_50430801_175_dialog_content = "<size=45>大家都準備好了嗎？</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>遊行要開始囉！</size>",
  ui_story_5043_50430901_1_dialog_content = "我們要讚美愛情～♪",
  ui_story_5043_50430901_2_dialog_content = "在神聖的白夜城讚美它～♪",
  ui_story_5043_50430901_3_dialog_content = "在有情人相愛時讚美它～♪",
  ui_story_5043_50430901_4_dialog_content = "因它帶來的絢麗讚美它～♪",
  ui_story_5043_50430901_5_dialog_content = "是的，我們要讚美愛情～♪",
  ui_story_5043_50430901_6_dialog_content = "讚美愛情！",
  ui_story_5043_50430901_7_dialog_content = "遊行隊伍，出發！！！",
  ui_story_5043_50430901_8_dialog_content = "哇！成群結隊的人走上了階梯！",
  ui_story_5043_50430901_9_dialog_content = "這樣不妙吧？",
  ui_story_5043_50430901_10_dialog_content = "是啊，要是這支遊行隊伍經過雕像旁邊……混亂之中很難保護它的安全。",
  ui_story_5043_50430901_11_dialog_content = "若是再讓雕像在眼皮下受損，你們的工作就……",
  ui_story_5043_50430901_12_dialog_content = "不行，得想辦法阻止遊行隊伍。",
  ui_story_5043_50430901_13_dialog_content = "阻止遊行？怎麼了，遊行隊伍出事了嗎？",
  ui_story_5043_50430901_14_dialog_content = "這可是難得的活動，如果審判官們要阻止，希望你們有充足的理由。",
  ui_story_5043_50430901_15_dialog_content = "隊伍前進速度不慢，沒有多少時間。",
  ui_story_5043_50430901_16_dialog_content = "我去試著阻止他們，你們跟修女解釋一下吧！",
  ui_story_5043_50430901_17_dialog_content = "哎，庶民新人就是莽撞……",
  ui_story_5043_50430901_18_dialog_content = "咳，修女小姐，我們也不願意干擾遊行。",
  ui_story_5043_50430901_19_dialog_content = "但是，這一切都是為了愛情啊。",
  ui_story_5043_50430901_20_dialog_content = "愛情？",
  ui_story_5043_50430901_21_dialog_content = "有壞人想趁著這場遊行做惡。",
  ui_story_5043_50430901_22_dialog_content = "身為主辦人，您肯定不希望自己籌辦的活動蒙上「破壞愛情」的惡名吧？",
  ui_story_5043_50430901_23_dialog_content = "讚、美、愛、情！",
  ui_story_5043_50430901_24_dialog_content = "自、由、戀、愛！",
  ui_story_5043_50430901_25_dialog_content = "那個，大家等一下！",
  ui_story_5043_50430901_26_dialog_content = "我們前進的方向好像不太對。",
  ui_story_5043_50430901_27_dialog_content = "聽說遊行目的地是中庭的住宅區才對！",
  ui_story_5043_50430901_28_dialog_content = "我們應該調頭往回走！",
  ui_story_5043_50430901_29_dialog_content = "對！往回走！",
  ui_story_5043_50430901_30_dialog_content = "咦？走錯方向了？",
  ui_story_5043_50430901_31_dialog_content = "不應該這樣啊，不是說好一起登上千星階梯嗎？",
  ui_story_5043_50430901_32_dialog_content = "消息傳錯了吧，大家人多嘴雜。",
  ui_story_5043_50430901_33_dialog_content = "咦，住宅區嗎？",
  ui_story_5043_50430901_34_dialog_content = "我聽說的目的地是中庭的廣場！",
  ui_story_5043_50430901_35_dialog_content = "我們離得有點遠，所以大家盡早調頭，往回走吧！",
  ui_story_5043_50430901_36_dialog_content = "說得對！快點往回走吧！",
  ui_story_5043_50430901_37_dialog_content = "要回頭嗎……可是都走到這裡了……",
  ui_story_5043_50430901_38_dialog_content = "就是說啊！",
  ui_story_5043_50430901_39_dialog_content = "可是原定目的地是住宅區耶。",
  ui_story_5043_50430901_40_dialog_content = "不對不對，是廣場！",
  ui_story_5043_50430901_41_dialog_content = "慢著，我清清楚楚記得今天的遊行是要登上千星階梯。",
  ui_story_5043_50430901_42_dialog_content = "對啊！不然我們為什麼要在階梯底下集合呢？",
  ui_story_5043_50430901_43_dialog_content = "說是住宅區和廣場的人是什麼來頭？",
  ui_story_5043_50430901_44_dialog_content = "那個傢伙紮著一頭白色馬尾，看起來很可靠呢。",
  ui_story_5043_50430901_45_dialog_content = "是一個看起來挺可靠的傢伙，白色頭髮，紮著馬尾。",
  ui_story_5043_50430901_46_dialog_content = "欸，那不是同一個人嗎！你們被耍了啊！",
  ui_story_5043_50430901_47_dialog_content = "咦？！",
  ui_story_5043_50430901_48_dialog_content = "白色頭髮紮著馬尾，就是這傢伙吧！",
  ui_story_5043_50430901_49_dialog_content = "沒有，我只是路過……",
  ui_story_5043_50430901_50_dialog_content = "是他沒錯！",
  ui_story_5043_50430901_51_dialog_content = "就是他跟我說的！",
  ui_story_5043_50430901_52_dialog_content = "哪裡冒出來的陌生面孔，還想破壞我們以愛為名的遊行！",
  ui_story_5043_50430901_53_dialog_content = "把他扭送到戀愛法庭去！",
  ui_story_5043_50430901_54_dialog_content = "這、這就不必了吧，我自己會去……",
  ui_story_5043_50430901_55_dialog_content = "走吧！我們繼續登上千星階梯！",
  ui_story_5043_50430901_56_dialog_content = "多留意，別讓這傢伙跑了！",
  ui_story_5043_50430901_57_dialog_content = "（糟了，臨時想到的辦法不靈光。）",
  ui_story_5043_50430901_58_dialog_content = "（遊行隊伍又開始前進了，該怎麼辦……）",
  ui_story_5043_50430901_59_dialog_content = "哎呀～糟了糟了，牛奶桶跟蜂蜜桶被弄倒了！",
  ui_story_5043_50430901_60_dialog_content = "你看我，真是笨手笨腳。",
  ui_story_5043_50430901_61_dialog_content = "哇？！！大量的牛奶從階梯上流下來？！",
  ui_story_5043_50430901_62_dialog_content = "到底打翻了多少個運送用牛奶桶啊？！",
  ui_story_5043_50430901_63_dialog_content = "而且為什麼還夾雜著蜂蜜啊！！！",
  ui_story_5043_50430901_64_dialog_content = "（這、這是馬太的直球招式？！）",
  ui_story_5043_50430901_65_dialog_content = "（雖然荒謬，好像還挺有效？遊行隊伍停下來了！）",
  ui_story_5043_50430901_66_dialog_content = "真是的，今天太不順利了。",
  ui_story_5043_50430901_67_dialog_content = "不能放棄啊！正如光之神所說，唯有通過考驗，才能前往福地！",
  ui_story_5043_50430901_68_dialog_content = "說得對！越是流淌著奶與蜜的地方，越是代表著正確的方向！",
  ui_story_5043_50430901_69_dialog_content = "大家小心前進吧！留意別滑倒了！",
  ui_story_5043_50430901_70_dialog_content = "（又重新前進了？！）",
  ui_story_5043_50430901_71_dialog_content = "（遊行隊伍的意志力有點駭人啊……）",
  ui_story_5043_50430901_72_dialog_content = "<size=45>哎呀——！！！</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>台階未免太滑了吧！！！</size>",
  ui_story_5043_50430901_74_dialog_content = "怎麼回事？！",
  ui_story_5043_50430901_75_dialog_content = "最上面好像有人滑倒了！",
  ui_story_5043_50430901_76_dialog_content = "嗚嗚嗚……痛，好痛啊……",
  ui_story_5043_50430901_77_dialog_content = "痛得快要在白天的千星階梯上看到星星了……",
  ui_story_5043_50430901_78_dialog_content = "她、她好像傷得很重！",
  ui_story_5043_50430901_79_dialog_content = "滑溜溜的台階確實有點危險……",
  ui_story_5043_50430901_80_dialog_content = "不然，今天先算了吧？",
  ui_story_5043_50430901_81_dialog_content = "是啊，哪裡都能繼續遊行。",
  ui_story_5043_50430901_82_dialog_content = "我們別佔著千星階梯了，趕快找人帶那女孩去看醫生吧。",
  ui_story_5043_50430901_83_dialog_content = "遊行隊伍向後退了！",
  ui_story_5043_50430901_84_dialog_content = "幹得漂亮啊，蒂娜！",
  ui_story_5043_50430901_85_dialog_content = "好逼真的演技！",
  ui_story_5043_50430901_86_dialog_content = "嘿嘿，若被審判庭辭退，要不要去劇院試試看呢～",
  ui_story_5043_50430901_87_dialog_content = "怎麼樣，我這一招妙吧。",
  ui_story_5043_50430901_88_dialog_content = "妙！太厲害了！",
  ui_story_5043_50430901_89_dialog_content = "你們這群孩子，真夠誇張的……",
  ui_story_5043_50430901_90_dialog_content = "算了，既是為了保住活動的名聲，就隨你們去吧。",
  ui_story_5043_50430901_91_dialog_content = "每一份愛情都值得守護，即使是對雕像的愛情也一樣。",
  ui_story_5043_50430901_92_dialog_content = "不愧是沙龍主辦者，感謝您的諒解～修女小姐。",
  ui_story_5043_50430901_93_dialog_content = "我要走了，接下來我會引導隊伍去其他地方遊行。",
  ui_story_5043_50430901_94_dialog_content = "你們也加油吧。",
  ui_story_5043_50430901_95_dialog_content = "糟了！別再往後退了！",
  ui_story_5043_50430901_96_dialog_content = "快回到階梯上！！！",
  ui_story_5043_50430901_97_dialog_content = "怎麼回事？！人群突然騷動起來了！",
  ui_story_5043_50430901_98_dialog_content = "暗鬼！背後怎麼有暗鬼來了！",
  ui_story_5043_50430901_99_dialog_content = "大家快往上跑啊！",
  ui_story_5043_50430901_100_dialog_content = "什麼？！這裡哪來的暗鬼？！",
  ui_story_5043_50430901_101_dialog_content = "噢，我看見牠們了！數量不算多！",
  ui_story_5043_50430901_102_dialog_content = "零恩已經開始跟暗鬼交手了！",
  ui_story_5043_50430901_103_dialog_content = "我們快去幫忙！",
  ui_story_5043_50430901_104_dialog_content = "我提醒你們一下，人潮馬上就會過來，別忘了注意雕像。",
  ui_story_5043_50430901_105_dialog_content = "看樣子只是小暗鬼，一個人去幫忙就夠了。",
  ui_story_5043_50430901_106_dialog_content = "蒂娜去支援零恩吧，其他人留在這裡保護雕像。",
  ui_story_5043_50430901_107_dialog_content = "與暗鬼交戰的時候，我會用感應能力幫忙！",
  ui_story_5043_50430901_108_dialog_content = "好，就這麼辦！",
  ui_story_5043_50430901_109_dialog_content = "那雕像就交給你們了，務必保護好它！",
  ui_story_5043_50431001_1_dialog_content = "那邊是最後一隻！",
  ui_story_5043_50431001_2_dialog_content = "交給我吧！",
  ui_story_5043_50431001_3_dialog_content = "好！這下敵人都消滅完了。",
  ui_story_5043_50431001_4_dialog_content = "不過……遊行的人群好像全湧上階梯了。",
  ui_story_5043_50431001_5_dialog_content = "PlayerName那邊怎麼樣了？",
  ui_story_5043_50431001_6_dialog_content = "喂，大家！請注意這邊！",
  ui_story_5043_50431001_7_dialog_content = "這邊有非常昂貴的雕像！弄壞了要賠錢哦！",
  ui_story_5043_50431001_8_dialog_content = "快跑快跑，有暗鬼啊！！",
  ui_story_5043_50431001_9_dialog_content = "大家不要慌張！暗鬼已經被解決了！",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431001_11_dialog_content = "怎麼回事？！",
  ui_story_5043_50431001_12_dialog_content = "糟糕，有人撞到雕像了！",
  ui_story_5043_50431001_13_dialog_content = "幸好它看起來沒有受損……",
  ui_story_5043_50431001_14_dialog_content = "哇啊啊啊啊啊啊啊啊！",
  ui_story_5043_50431001_15_dialog_content = "又來了！！！",
  ui_story_5043_50431001_16_dialog_content = "馬太，快攔住他們！！！",
  ui_story_5043_50431001_17_dialog_content = "我要怎麼......",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431001_19_dialog_content = "哎唷！",
  ui_story_5043_50431001_20_dialog_content = "你沒事吧？",
  ui_story_5043_50431001_21_dialog_content = "與其說廢話，不如過來扶我一下？",
  ui_story_5043_50431001_22_dialog_content = "糟了！有暗鬼混進人群裡了！",
  ui_story_5043_50431001_23_dialog_content = "暗鬼？！",
  ui_story_5043_50431001_24_dialog_content = "真的耶！有幾隻暗鬼混進了人群！",
  ui_story_5043_50431001_25_dialog_content = "哪裡來的？",
  ui_story_5043_50431001_26_dialog_content = "別慌，看我用鞋子砸死牠！",
  ui_story_5043_50431001_27_dialog_content = "鞋子能砸死暗鬼嗎？！",
  ui_story_5043_50431001_28_dialog_content = "等等，你的鞋子怎麼朝雕像飛過來了！",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431001_30_dialog_content = "希望彼瑪隆先生不介意雕像身上多一個鞋印……",
  ui_story_5043_50431001_31_dialog_content = "我也來砸牠！看我的！",
  ui_story_5043_50431001_32_dialog_content = "果然又來啦！！！",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431001_34_dialog_content = "喂，雕像沒事吧？",
  ui_story_5043_50431001_35_dialog_content = "目前還算沒事，但是再這樣下去就難說了……",
  ui_story_5043_50431001_36_dialog_content = "別再扔鞋了！你們自己看，扔鞋連石膏像都砸不壞！",
  ui_story_5043_50431001_37_dialog_content = "更不可能傷得了暗鬼啊！",
  ui_story_5043_50431001_38_dialog_content = "說得對啊，有沒有更厲害的武器？",
  ui_story_5043_50431001_39_dialog_content = "我這裡有！我帶了硬質乳酪，像石頭一樣紮實！",
  ui_story_5043_50431001_40_dialog_content = "怎麼會有人隨身攜帶乳酪啊！！！",
  ui_story_5043_50431001_41_dialog_content = "完了完了，要是乳酪扔過來，雕像說不定真的會……",
  ui_story_5043_50431001_42_dialog_content = "各位，冷靜——冷靜下來！別再往這邊扔了！",
  ui_story_5043_50431001_43_dialog_content = "不要再往這邊扔東西了！",
  ui_story_5043_50431001_44_dialog_content = "主辦大人！",
  ui_story_5043_50431001_45_dialog_content = "快停手吧，別亂扔了。千萬不能傷到主辦大人。",
  ui_story_5043_50431001_46_dialog_content = "呼……逃過一劫了呢。",
  ui_story_5043_50431001_47_dialog_content = "謝謝妳啊，修女小姐！",
  ui_story_5043_50431001_48_dialog_content = "沒什麼，這是我該做的。",
  ui_story_5043_50431001_49_dialog_content = "冠月節風潮的活動，絕不能背負破壞愛情的污名！",
  ui_story_5043_50431001_50_dialog_content = "（從她保護雕像的樣子，「連環斷頭雕像案」應該與她無關。）",
  ui_story_5043_50431001_51_dialog_content = "人群逐漸遠去了。",
  ui_story_5043_50431001_52_dialog_content = "看樣子，我們好像可以喘口氣啦。",
  ui_story_5043_50431001_53_dialog_content = "是啊。",
  ui_story_5043_50431001_54_dialog_content = "真沒想到慌亂擁擠的人群比暗鬼還可怕。",
  ui_story_5043_50431001_55_dialog_content = "是啊，早知道就去幫忙收拾暗鬼了。",
  ui_story_5043_50431001_56_dialog_content = "喂！！！你們怎麼在發呆！！！",
  ui_story_5043_50431001_57_dialog_content = "零恩！你回來了……",
  ui_story_5043_50431001_58_dialog_content = "你們的背後！",
  ui_story_5043_50431001_59_dialog_content = "你們背後還有暗鬼啊！！！",
  ui_story_5043_50431002_1_dialog_content = "這幫怪物，最會出其不意嚇唬人。",
  ui_story_5043_50431002_2_dialog_content = "真的打起來還真是不堪一擊啊！",
  ui_story_5043_50431002_3_dialog_content = "別鬆懈，還有幾隻暗鬼還沒解決。",
  ui_story_5043_50431002_4_dialog_content = "我們一起將牠們收拾乾淨！",
  ui_story_5043_50431002_5_dialog_content = "等一下！",
  ui_story_5043_50431002_6_dialog_content = "PlayerName，你旁邊的是……",
  ui_story_5043_50431002_7_dialog_content = "我旁邊？！",
  ui_story_5043_50431002_8_dialog_content = "有一隻手在……",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5043_50431002_10_dialog_content = "糟了，雕像它……",
  ui_story_5043_50431002_11_dialog_content = "是誰幹的？！",
  ui_story_5043_50431002_12_dialog_content = "我抓住犯人的手了！",
  ui_story_5043_50431002_13_dialog_content = "他混在暗鬼群裡面，把他揪出來！",
  ui_story_5043_50431002_14_dialog_content = "礙事的傢伙們，讓開讓開！",
  ui_story_5043_50431002_15_dialog_content = "咦？沒有人啊？",
  ui_story_5043_50431002_16_dialog_content = "對不起，讓那傢伙逃掉了。",
  ui_story_5043_50431002_17_dialog_content = "他脫掉手套好從我手裡掙脫，好一招斷尾求生……",
  ui_story_5043_50431002_18_dialog_content = "可惡啊，竟然讓犯人在我們眼皮下毀掉了雕像！",
  ui_story_5043_50431002_19_dialog_content = "回去該怎麼交差啊！",
  ui_story_5043_50431002_20_dialog_content = "至少……我們拿到了犯人的手套，對吧？",
  ui_story_5043_50431002_21_dialog_content = "這應該算關鍵線索吧！",
  ui_story_5043_50431002_22_dialog_content = "調查上而言，算是有所突破。",
  ui_story_5043_50431002_23_dialog_content = "只怕……彼瑪隆先生無法接受啊……",
  ui_story_5043_50431002_24_dialog_content = "對了，蒂娜去哪了？",
  ui_story_5043_50431002_25_dialog_content = "她不是跟零恩在一起嗎？",
  ui_story_5043_50431002_26_dialog_content = "剛才我急著回來，也許她落後了。",
  ui_story_5043_50431002_27_dialog_content = "喂！大家沒事吧！",
  ui_story_5043_50431002_28_dialog_content = "對不起啊，爬階梯途中被暗鬼纏住了。",
  ui_story_5043_50431002_29_dialog_content = "雕像的頭……又沒了？！！！",
  ui_story_5043_50431002_30_dialog_content = "唉……",
  ui_story_5043_50431002_31_dialog_content = "不管怎麼說，先回去覆命吧。",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>高庭‧審判庭</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>妻子！我的妻子！！！</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>我的阿芙洛狄婭啊——！！！</size>",
  ui_story_5043_50431002_35_dialog_content = "……",
  ui_story_5043_50431002_36_dialog_content = "啊，完蛋了。",
  ui_story_5043_50431002_37_dialog_content = "為什麼，怎麼會發生這種事情。",
  ui_story_5043_50431002_38_dialog_content = "明明我的愛意那麼殷切，明明我提前做了準備。",
  ui_story_5043_50431002_39_dialog_content = "可是……愛情還是接連離我而去……",
  ui_story_5043_50431002_40_dialog_content = "我救不回我愛的雕像，一尊也沒救到……",
  ui_story_5043_50431002_41_dialog_content = "事情我都明白了，彼瑪隆先生。",
  ui_story_5043_50431002_42_dialog_content = "你如何明白？",
  ui_story_5043_50431002_43_dialog_content = "事情根本已經結束了！",
  ui_story_5043_50431002_44_dialog_content = "世上已經沒有值得我愛的東西了！",
  ui_story_5043_50431002_45_dialog_content = "光之神啊，為何如此懲罰我……",
  ui_story_5043_50431002_46_dialog_content = "您先別激動。",
  ui_story_5043_50431002_47_dialog_content = "事情已經發生，這一點無法改變。",
  ui_story_5043_50431002_48_dialog_content = "但審判庭會為您討回公道。",
  ui_story_5043_50431002_49_dialog_content = "審判庭？哼！",
  ui_story_5043_50431002_50_dialog_content = "要不是因為你們的無能，我的妻子會遭受這種飛來橫禍嗎？",
  ui_story_5043_50431002_51_dialog_content = "三位審判官加在一起，找不到真兇就算了，竟然連保護雕像都做不到！",
  ui_story_5043_50431002_52_dialog_content = "等著吧，伊倫汀審判長很快就會知道你們的「輝煌事蹟」！",
  ui_story_5043_50431002_53_dialog_content = "我相信她不會放任如此無能的部門，敗壞整個審判庭的名聲！",
  ui_story_5043_50431002_54_dialog_content = "對不起，彼瑪隆先生，讓您失望了。",
  ui_story_5043_50431002_55_dialog_content = "我們沒能阻止犯人破壞雕像，也沒能當場抓住犯人。",
  ui_story_5043_50431002_56_dialog_content = "不過至少……我們拿到了犯人作案時佩戴的手套。",
  ui_story_5043_50431002_57_dialog_content = "天哪，我妻子絕美的頭顱，竟然只換來一隻手套！",
  ui_story_5043_50431002_58_dialog_content = "你們該不會以為這是多大的收穫吧？",
  ui_story_5043_50431002_59_dialog_content = "白夜城有多少居民？又有多少雙手套？",
  ui_story_5043_50431002_60_dialog_content = "憑你們戀愛法庭低落的辦事能力，還能用它變出什麼把戲呢？！",
  ui_story_5043_50431002_61_dialog_content = "彼瑪隆先生，請別藉口個人的問題遷怒整個戀愛分部。",
  ui_story_5043_50431002_62_dialog_content = "雖然審判官辦事不力，身為審判長的我一定會讓每一起案件得到公正的判決。",
  ui_story_5043_50431002_63_dialog_content = "公正的判決？你的漂亮話留著去跟伊倫汀大人說吧！",
  ui_story_5043_50431002_64_dialog_content = "現在我的愛人、我的妻子相繼遇害，犯人卻逍遙法外。",
  ui_story_5043_50431002_65_dialog_content = "這叫什麼公正？！",
  ui_story_5043_50431002_66_dialog_content = "所以我說～您太著急了，彼瑪隆先生。",
  ui_story_5043_50431002_67_dialog_content = "法槌還未落下，怎能斷定犯人逍遙法外呢？",
  ui_story_5043_50431002_68_dialog_content = "難道你能在休庭前抓住犯人？",
  ui_story_5043_50431002_69_dialog_content = "零恩審判官，將那隻手套提交當證物。",
  ui_story_5043_50431002_70_dialog_content = "是。",
  ui_story_5043_50431002_71_dialog_content = "這是在犯罪現場從犯人手上扯下來的手套，沒錯吧？",
  ui_story_5043_50431002_72_dialog_content = "是的。我差一點就逮到犯人，可惜他捨棄手套掙脫了。",
  ui_story_5043_50431002_73_dialog_content = "那麼～這條線索非常簡單，手套的主人就是雕像案的真兇。",
  ui_story_5043_50431002_74_dialog_content = "正好，我的手下替我找到<color=#FFB400>另一隻手套</color>。",
  ui_story_5043_50431002_75_dialog_content = "你們看，這兩隻手套是不是成對的？",
  ui_story_5043_50431002_76_dialog_content = "另一隻手套？",
  ui_story_5043_50431002_77_dialog_content = "？！",
  ui_story_5043_50431002_78_dialog_content = "真的是耶！",
  ui_story_5043_50431002_79_dialog_content = "你在哪裡找到的？這是誰的手套？",
  ui_story_5043_50431002_80_dialog_content = "既然如此，這起案件的結論就非常明朗了。",
  ui_story_5043_50431002_81_dialog_content = "衛兵們，聽我命令！",
  ui_story_5043_50431002_82_dialog_content = "逮捕蒂娜‧坎貝爾！",
  ui_story_5043_50431002_83_dialog_content = "什麼？逮捕蒂娜？！",
  ui_story_5043_50431002_84_dialog_content = "是！",
  ui_story_5043_50431101_1_dialog_content = "等一下！搞錯了吧？",
  ui_story_5043_50431101_2_dialog_content = "怎麼會是蒂娜？！",
  ui_story_5043_50431101_3_dialog_content = "就是說啊！不可能是蒂娜！",
  ui_story_5043_50431101_4_dialog_content = "史瓦審判長，你是笨蛋嗎？",
  ui_story_5043_50431101_5_dialog_content = "無能的審判官們……我的推斷依據已經闡述得非常明確了。",
  ui_story_5043_50431101_6_dialog_content = "零恩審判官取得的手套是決定性證據，它的所有者即是真兇。",
  ui_story_5043_50431101_7_dialog_content = "我的手下在案發之後，迅速找到了與現場手套特徵相符的另一隻手套。",
  ui_story_5043_50431101_8_dialog_content = "而那隻手套當時是被藏在蒂娜審判官的辦公桌抽屜裡。",
  ui_story_5043_50431101_9_dialog_content = "什麼？！",
  ui_story_5043_50431101_10_dialog_content = "蒂娜，這雙手套真是妳的？",
  ui_story_5043_50431101_11_dialog_content = "我……我確實說過我有一雙這樣的手套。",
  ui_story_5043_50431101_12_dialog_content = "可是它怎麼會出現在案發現場呢……",
  ui_story_5043_50431101_13_dialog_content = "蒂娜審判官，妳還搞不清楚現在的狀況嗎？",
  ui_story_5043_50431101_14_dialog_content = "作為第一嫌疑人，這個問題該由妳來回答我們。",
  ui_story_5043_50431101_15_dialog_content = "沒想到，像妳這樣美麗的小百合花竟會做出如此醜陋的事情。令人痛心。",
  ui_story_5043_50431101_16_dialog_content = "令人痛心啊。",
  ui_story_5043_50431101_17_dialog_content = "不對，你少在這裡誣陷好人！",
  ui_story_5043_50431101_18_dialog_content = "案發時蒂娜與我們一起在對抗暗鬼。",
  ui_story_5043_50431101_19_dialog_content = "我們都能作證，她絕對不是犯人！",
  ui_story_5043_50431101_20_dialog_content = "零恩，你身為審判官可要為自己說過的話負責。",
  ui_story_5043_50431101_21_dialog_content = "提供偽證的後果，不需要我告訴你吧？",
  ui_story_5043_50431101_22_dialog_content = "她說的千真萬確，我也能作證！",
  ui_story_5043_50431101_23_dialog_content = "是嗎？你們可得想清楚哦。",
  ui_story_5043_50431101_24_dialog_content = "事件發生的那一瞬間，蒂娜審判官真的在你們身邊與暗鬼作戰嗎？",
  ui_story_5043_50431101_25_dialog_content = "她……",
  ui_story_5043_50431101_26_dialog_content = "話說，蒂娜去哪裡了？",
  ui_story_5043_50431101_27_dialog_content = "她不是跟零恩在一起嗎？",
  ui_story_5043_50431101_28_dialog_content = "剛才我急著回來，也許她落後了。",
  ui_story_5043_50431101_29_dialog_content = "喂！大家沒事吧！",
  ui_story_5043_50431101_30_dialog_content = "（糟糕，蒂娜當時真的不在我們身邊！）",
  ui_story_5043_50431101_31_dialog_content = "看來你是想通了。",
  ui_story_5043_50431101_32_dialog_content = "闡述證詞的時候，每一個字都要考慮清楚。",
  ui_story_5043_50431101_33_dialog_content = "學不會這一點，恐怕難以成為合格的審判官。",
  ui_story_5043_50431101_34_dialog_content = "……",
  ui_story_5043_50431101_35_dialog_content = "好了，犯人順利落網，鬧劇就此收場吧。",
  ui_story_5043_50431101_36_dialog_content = "彼瑪隆先生，您對這個結果滿意嗎？",
  ui_story_5043_50431101_37_dialog_content = "真沒想到，犯人竟然出在這幾個審判官裡面！",
  ui_story_5043_50431101_38_dialog_content = "怪不得他們事情都辦不好！",
  ui_story_5043_50431101_39_dialog_content = "彼瑪隆先生，事情不是這樣……",
  ui_story_5043_50431101_40_dialog_content = "虧我還把希望放在你們身上。",
  ui_story_5043_50431101_41_dialog_content = "結果呢？嘴上說保護愛情，手裡做著破壞愛情的勾當！",
  ui_story_5043_50431101_42_dialog_content = "審判長，如此惡質的犯人應當嚴懲！",
  ui_story_5043_50431101_43_dialog_content = "犯人自當受到裁決，但不是現在。",
  ui_story_5043_50431101_44_dialog_content = "各位應該還記得，明天是「連環斷頭雕像案」的開庭日。",
  ui_story_5043_50431101_45_dialog_content = "屆時，原告可以在法庭上提出你的主張。",
  ui_story_5043_50431101_46_dialog_content = "我明白了。",
  ui_story_5043_50431101_47_dialog_content = "我的愛人與我的妻子在這起案件中遭受的對待過於殘酷。",
  ui_story_5043_50431101_48_dialog_content = "審判長大人，務必請您為我主持公道！",
  ui_story_5043_50431101_49_dialog_content = "那是當然～戀愛法庭會為所有無罪的愛情主持公道。",
  ui_story_5043_50431101_50_dialog_content = "衛兵，把嫌犯帶下去吧。",
  ui_story_5043_50431101_51_dialog_content = "請等一下！",
  ui_story_5043_50431101_52_dialog_content = "史瓦審判長，我想再次檢查證物的手套。",
  ui_story_5043_50431101_53_dialog_content = "蒂娜絕對不是犯人，證物的歸屬可能有哪裡弄錯了。",
  ui_story_5043_50431101_54_dialog_content = "不能就這樣草率逮捕她！",
  ui_story_5043_50431101_55_dialog_content = "就是啊！憑什麼一樣款式就視為同一副手套！",
  ui_story_5043_50431101_56_dialog_content = "同色同款的手套，光是我自己就能買七副！",
  ui_story_5043_50431101_57_dialog_content = "各位……",
  ui_story_5043_50431101_58_dialog_content = "審判官們，今天的鬧劇夠多了，我沒興趣繼續下去。",
  ui_story_5043_50431101_59_dialog_content = "有什麼想說想做的，都留到開庭日去吧。",
  ui_story_5043_50431101_60_dialog_content = "為什麼？不過是檢查一下……",
  ui_story_5043_50431101_61_dialog_content = "我說，今天，已經，夠了。",
  ui_story_5043_50431101_62_dialog_content = "嫌犯等下會被帶去禁閉室。直到開庭日前，不准任何人會面。",
  ui_story_5043_50431101_63_dialog_content = "禁閉室？！你瘋了嗎？！",
  ui_story_5043_50431101_64_dialog_content = "判決前單獨監禁嫌犯是違法的，你沒有權力這樣做！",
  ui_story_5043_50431101_65_dialog_content = "在戀愛分部的審判庭上，敲下「有罪」的法槌就是我的權力。",
  ui_story_5043_50431101_66_dialog_content = "把嫌犯送去禁閉室是必要的步驟，你們想質疑審判庭的法律？",
  ui_story_5043_50431101_67_dialog_content = "你……",
  ui_story_5043_50431101_68_dialog_content = "各位、各位都先別衝動！",
  ui_story_5043_50431101_69_dialog_content = "我先聽從史瓦審判長的安排，開庭時再做辯駁就好。",
  ui_story_5043_50431101_70_dialog_content = "蒂娜……",
  ui_story_5043_50431101_71_dialog_content = "我是審判官，所以我相信白夜城的司法系統不會冤枉無辜之人。",
  ui_story_5043_50431101_72_dialog_content = "等到明天開庭，真相必定水落石出。",
  ui_story_5043_50431101_73_dialog_content = "我相信戀愛法庭。",
  ui_story_5043_50431101_74_dialog_content = "我也相信你們。",
  ui_story_5043_50431101_75_dialog_content = "……",
  ui_story_5043_50431101_76_dialog_content = "……",
  ui_story_5043_50431101_77_dialog_content = "衛兵，把嫌犯帶走。",
  ui_story_5043_50431101_78_dialog_content = "是！",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>高庭‧審判庭外</color>",
  ui_story_5043_50431101_80_dialog_content = "怎麼辦，蒂娜被關起來了。",
  ui_story_5043_50431101_81_dialog_content = "明天她在庭上會不會被判有罪？",
  ui_story_5043_50431101_82_dialog_content = "就目前的局面開庭的話……會。",
  ui_story_5043_50431101_83_dialog_content = "那、那怎麼行呢！她肯定是無罪的！",
  ui_story_5043_50431101_84_dialog_content = "你們有沒有覺得，史瓦那傢伙有點古怪？",
  ui_story_5043_50431101_85_dialog_content = "欸？",
  ui_story_5043_50431101_86_dialog_content = "我是向來覺得他古怪啦，不過經你這麼一說……",
  ui_story_5043_50431101_87_dialog_content = "感覺他今天在法庭上的態度有點偏激。",
  ui_story_5043_50431101_88_dialog_content = "我感覺到那傢伙對我們有敵意。",
  ui_story_5043_50431101_89_dialog_content = "他放大了對蒂娜不利的資訊，又忽視所有反駁的聲音。",
  ui_story_5043_50431101_90_dialog_content = "是的，一切因素出現得太巧合。",
  ui_story_5043_50431101_91_dialog_content = "案件剛發生，他就能派人找到跟證物一樣的另一隻手套。",
  ui_story_5043_50431101_92_dialog_content = "彷彿他提前知道另一隻手套在哪裡……",
  ui_story_5043_50431101_93_dialog_content = "還有，他好像很了解事發現場的狀況。",
  ui_story_5043_50431101_94_dialog_content = "記得他剛才那張自信的臭臉嗎？",
  ui_story_5043_50431101_95_dialog_content = "是嗎？你們可得想清楚哦。",
  ui_story_5043_50431101_96_dialog_content = "事件發生的那一瞬間，蒂娜審判官真的在你們身邊與暗鬼作戰嗎？",
  ui_story_5043_50431101_97_dialog_content = "他明明沒去過現場，憑什麼敢這樣問？",
  ui_story_5043_50431101_98_dialog_content = "對耶！",
  ui_story_5043_50431101_99_dialog_content = "這樣想來，剛才法庭上對蒂娜的審判太果斷又迅速了。",
  ui_story_5043_50431101_100_dialog_content = "一切都朝著蒂娜有罪的方向快速發展……",
  ui_story_5043_50431101_101_dialog_content = "不過，最奇怪的還不是剛才那些猜測。",
  ui_story_5043_50431101_102_dialog_content = "而是他最後採取的做法。",
  ui_story_5043_50431101_103_dialog_content = "說得沒錯。",
  ui_story_5043_50431101_104_dialog_content = "找到手套、瞭解現場可以用很多理由解釋，比如說運氣好、眼線眾多。",
  ui_story_5043_50431101_105_dialog_content = "他舉證的流程符合規矩，都不算有破綻。",
  ui_story_5043_50431101_106_dialog_content = "沒錯，但最後他沉不住氣了。",
  ui_story_5043_50431101_107_dialog_content = "不允許我們查看證物，並且動用強制權監禁了蒂娜。",
  ui_story_5043_50431101_108_dialog_content = "這表示有某種他不希望被別人看到的東西。",
  ui_story_5043_50431101_109_dialog_content = "尤其是被我們看到。",
  ui_story_5043_50431101_110_dialog_content = "是的，就是他不惜打破規則也要掩蓋的線索。",
  ui_story_5043_50431101_111_dialog_content = "致使蒂娜被定罪的真相，一定就那些因素背後。",
  ui_story_5043_50431101_112_dialog_content = "好厲害啊！精彩的推理！",
  ui_story_5043_50431101_113_dialog_content = "注意發言。",
  ui_story_5043_50431101_114_dialog_content = "這裡是審判庭門口。",
  ui_story_5043_50431101_115_dialog_content = "哦對，我們小聲一點。",
  ui_story_5043_50431101_116_dialog_content = "如果我們能找到史瓦想掩蓋的線索，是不是就能幫蒂娜脫罪了？",
  ui_story_5043_50431101_117_dialog_content = "這樣說是沒錯，但我們恐怕沒辦法找到。",
  ui_story_5043_50431101_118_dialog_content = "欸？",
  ui_story_5043_50431101_119_dialog_content = "史瓦恐怕會搶在開庭前，排除所有破綻。",
  ui_story_5043_50431101_120_dialog_content = "他知道破綻是什麼，而我們不知道。",
  ui_story_5043_50431101_121_dialog_content = "況且，他能操弄的手腕也比我們更多。",
  ui_story_5043_50431101_122_dialog_content = "這是我們難以扳回的劣勢。",
  ui_story_5043_50431101_123_dialog_content = "那、那該怎麼辦？只能枯等開庭日到來嗎？",
  ui_story_5043_50431101_124_dialog_content = "只憑現有的資訊，蒂娜一定會被定罪。",
  ui_story_5043_50431101_125_dialog_content = "開庭之前，我們必須去蒐集線索。",
  ui_story_5043_50431101_126_dialog_content = "避開史瓦想掩蓋的那個核心，在周遭尋找蛛絲馬跡。",
  ui_story_5043_50431101_127_dialog_content = "哈哈，聽起來有點意思！",
  ui_story_5043_50431101_128_dialog_content = "看來你已經有想法了？",
  ui_story_5043_50431101_129_dialog_content = "喂，你們該不會是要去做蠢事吧。",
  ui_story_5043_50431101_130_dialog_content = "洛維，你別那麼死腦筋。",
  ui_story_5043_50431101_131_dialog_content = "我等會還有其他的調查工作，就不奉陪了。",
  ui_story_5043_50431101_132_dialog_content = "至於你們要做的蠢事，我既沒有聽到也沒有參與。",
  ui_story_5043_50431101_133_dialog_content = "你……",
  ui_story_5043_50431101_134_dialog_content = "這樣最好，人多反而麻煩。",
  ui_story_5043_50431101_135_dialog_content = "好了，你們兩個離我近一點。",
  ui_story_5043_50431101_136_dialog_content = "嗯，你說。",
  ui_story_5043_50431101_137_dialog_content = "史瓦為掩蓋祕密打破規則。",
  ui_story_5043_50431101_138_dialog_content = "我們想戰勝他，也得打破規則。",
  ui_story_5043_50431101_139_dialog_content = "那我們要怎麼做？",
  ui_story_5043_50431101_140_dialog_content = "我們潛入史瓦家裡。",
  ui_story_5043_50431101_141_dialog_content = "什麼？！",
  ui_story_5043_50431101_142_dialog_content = "接觸不到證物和嫌犯，就只能從史瓦本人身上下手了。",
  ui_story_5043_50431101_143_dialog_content = "家是最私密和安全的地方。",
  ui_story_5043_50431101_144_dialog_content = "如果史瓦隱瞞了不可告人的祕密，那裡最有可能找到線索。",
  ui_story_5043_50431101_145_dialog_content = "可是……這樣的行為是違法的吧？",
  ui_story_5043_50431101_146_dialog_content = "有意思！太有意思了！",
  ui_story_5043_50431101_147_dialog_content = "對，就要這麼做！到他那個莊園裡去看看！",
  ui_story_5043_50431101_148_dialog_content = "好吧，看來這裡最在乎法律的人是我……",
  ui_story_5043_50431101_149_dialog_content = "你也看到了，是對方違法在先，把我們逼到這一步。",
  ui_story_5043_50431101_150_dialog_content = "等一切結束之後，我會主動承擔非法闖入的代價。",
  ui_story_5043_50431101_151_dialog_content = "但現在最重要的是不能讓蒂娜平白無故被冤枉。",
  ui_story_5043_50431101_152_dialog_content = "還要主動承擔代價？",
  ui_story_5043_50431101_153_dialog_content = "唉，像你這樣的老實人以後只會吃虧呀。",
  ui_story_5043_50431101_154_dialog_content = "嗯……最重要的還是為蒂娜脫罪！",
  ui_story_5043_50431101_155_dialog_content = "那我們現在就出發？",
  ui_story_5043_50431101_156_dialog_content = "出發前還有件小事要做。",
  ui_story_5043_50431101_157_dialog_content = "不知道你們有沒有發現，身後有幾個衛兵一直跟著我們。",
  ui_story_5043_50431101_158_dialog_content = "想必也是史瓦授意的，他不會容許我們隨意行動。",
  ui_story_5043_50431101_159_dialog_content = "看來需要先甩掉他們？",
  ui_story_5043_50431101_160_dialog_content = "是的，我正在想辦法。",
  ui_story_5043_50431101_161_dialog_content = "這還不簡單，我最擅長逃跑了。",
  ui_story_5043_50431101_162_dialog_content = "別忘了，我比他們多一雙「眼睛」。",
  ui_story_5043_50431101_163_dialog_content = "哦對！空裔的感應能力可以發揮作用！",
  ui_story_5043_50431101_164_dialog_content = "那太好了。逃跑專家，我們第一步該怎麼做？",
  ui_story_5043_50431101_165_dialog_content = "說起來其實非常簡單。",
  ui_story_5043_50431101_166_dialog_content = "逃跑計畫的第一步當然就是——",
  ui_story_5043_50431101_167_dialog_content = "先跑起來再說啊！！！",
  ui_story_5043_50431102_1_dialog_content = "前面右轉！",
  ui_story_5043_50431102_2_dialog_content = "唉唷，累死我了。",
  ui_story_5043_50431102_3_dialog_content = "如何？後面還有幾個衛兵？",
  ui_story_5043_50431102_4_dialog_content = "衛兵？一個都沒有啦。",
  ui_story_5043_50431102_5_dialog_content = "那我們在跑什麼啊！",
  ui_story_5043_50431102_6_dialog_content = "哦，想說不是要去史瓦家嗎。",
  ui_story_5043_50431102_7_dialog_content = "現在正在往那個方向跑。",
  ui_story_5043_50431102_8_dialog_content = "又沒人在追我們，走著去也無妨吧！",
  ui_story_5043_50431102_9_dialog_content = "而且你怎麼知道史瓦家在哪裡？",
  ui_story_5043_50431102_10_dialog_content = "我剛才跟他說的。",
  ui_story_5043_50431102_11_dialog_content = "時間緊迫，跑著去也比較快。",
  ui_story_5043_50431102_12_dialog_content = "好歹告訴我已經甩掉追兵了嘛！提心吊膽可是很累人的！",
  ui_story_5043_50431102_13_dialog_content = "好了好了，前面就快到了。說話小聲一點。",
  ui_story_5043_50431102_14_dialog_content = "你這傢伙……",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>高庭‧薩拉爾莊園外</color>",
  ui_story_5043_50431102_16_dialog_content = "看起來門口有不少護衛和僕人。",
  ui_story_5043_50431102_17_dialog_content = "要躲開他們，還要找到線索……",
  ui_story_5043_50431102_18_dialog_content = "沒錯，這是個危險的計畫。",
  ui_story_5043_50431102_19_dialog_content = "要是被發現，我們明天開庭時就要站在被告席了。",
  ui_story_5043_50431102_20_dialog_content = "你們做好準備了嗎？",
  ui_story_5043_50431102_21_dialog_content = "想為蒂娜脫罪，這是唯一的選擇……",
  ui_story_5043_50431102_22_dialog_content = "就算危險也只能上了！",
  ui_story_5043_50431102_23_dialog_content = "好消息是這個莊園真的夠大，有很多地方可以供我們躲藏。",
  ui_story_5043_50431102_24_dialog_content = "再加上PlayerName的感應能力能幫我們規避掉很多麻煩。",
  ui_story_5043_50431102_25_dialog_content = "嗯！我會打起十二分精神注意周圍！",
  ui_story_5043_50431102_26_dialog_content = "不過，我們該怎麼進去呢？",
  ui_story_5043_50431102_27_dialog_content = "不曉得能不能等到這幾個護衛換班……",
  ui_story_5043_50431102_28_dialog_content = "沒關係，我們不從正門進去。",
  ui_story_5043_50431102_29_dialog_content = "嗯？難道這座莊園還有其他的門？",
  ui_story_5043_50431102_30_dialog_content = "你看那邊的花園，當中有很多灌木可以藏身。",
  ui_story_5043_50431102_31_dialog_content = "我們從花園旁邊翻牆進去。",
  ui_story_5043_50431102_32_dialog_content = "翻牆？！",
  ui_story_5043_50431102_33_dialog_content = "哦！那個位置確實不錯，牆壁也不算高！",
  ui_story_5043_50431102_34_dialog_content = "走，我們現在就去。",
  ui_story_5043_50431102_35_dialog_content = "好的！",
  ui_story_5043_50431102_36_dialog_content = "等等，翻牆未免太不體面了吧？",
  ui_story_5043_50431102_37_dialog_content = "我可是堂堂薩耶家族的少……",
  ui_story_5043_50431102_38_dialog_content = "唉，算了。真不知道怎麼說你們這些庶民。",
  ui_story_5043_50431201_1_dialog_content = "啊……為什麼我非得做這種蠢事啊……",
  ui_story_5043_50431201_2_dialog_content = "都是為了幫蒂娜脫罪，忍耐一下吧。",
  ui_story_5043_50431201_3_dialog_content = "你看，至少我們順利進入莊園了。",
  ui_story_5043_50431201_4_dialog_content = "仔細一看……這裡還挺漂亮呢。",
  ui_story_5043_50431201_5_dialog_content = "這就是史瓦的家？",
  ui_story_5043_50431201_6_dialog_content = "是啊，真令人羨慕。",
  ui_story_5043_50431201_7_dialog_content = "薩拉爾家族在白夜城的影響力並不小。",
  ui_story_5043_50431201_8_dialog_content = "這樣一座莊園也不過是他們家族財產的冰山一角。",
  ui_story_5043_50431201_9_dialog_content = "噓，別碎嘴了，前面有人。",
  ui_story_5043_50431201_10_dialog_content = "我們過去看看。",
  ui_story_5043_50431201_11_dialog_content = "哦！我也看到了！",
  ui_story_5043_50431201_12_dialog_content = "那好像是……史瓦？",
  ui_story_5043_50431201_13_dialog_content = "對不起，史瓦大人，我們跟丟了。",
  ui_story_5043_50431201_14_dialog_content = "那兩位審判官和空裔跑得很快，路線又七彎八拐的，根本追不上。",
  ui_story_5043_50431201_15_dialog_content = "我派了那麼多衛兵，竟然還能跟丟？",
  ui_story_5043_50431201_16_dialog_content = "真是沒用！",
  ui_story_5043_50431201_17_dialog_content = "非常抱歉！",
  ui_story_5043_50431201_18_dialog_content = "算了，就這樣吧。",
  ui_story_5043_50431201_19_dialog_content = "他們著急起來就會出錯，這樣說不定還不算壞。",
  ui_story_5043_50431201_20_dialog_content = "你們先回去吧。",
  ui_story_5043_50431201_21_dialog_content = "是！史瓦大人！",
  ui_story_5043_50431201_22_dialog_content = "派衛兵盯著我們？哼，怎麼可能輕易如你的願！",
  ui_story_5043_50431201_23_dialog_content = "太好了，沒想到一進來就能找到史瓦。",
  ui_story_5043_50431201_24_dialog_content = "我們跟緊他，看他搞什麼名堂。",
  ui_story_5043_50431201_25_dialog_content = "任何反常的行為都能成為重要線索。",
  ui_story_5043_50431201_26_dialog_content = "明白了！",
  ui_story_5043_50431201_27_dialog_content = "小心一點，別忘了史瓦很難以捉摸。",
  ui_story_5043_50431201_28_dialog_content = "一個敢在法庭破壞規則的人，天曉得在家裡會做出什麼可怕的事情。",
  ui_story_5043_50431201_29_dialog_content = "你、你說得讓我開始害怕了。",
  ui_story_5043_50431201_30_dialog_content = "恐懼能讓你做好心理準備。",
  ui_story_5043_50431201_31_dialog_content = "走，我們跟上去看看。",
  ui_story_5043_50431201_32_dialog_content = "史瓦大人，您的茶沏好了。",
  ui_story_5043_50431201_33_dialog_content = "嗯，給我吧。",
  ui_story_5043_50431201_34_dialog_content = "廚房正在製作點心，我再拿一些過來給您。",
  ui_story_5043_50431201_35_dialog_content = "不用了，我還有其他事情要忙。",
  ui_story_5043_50431201_36_dialog_content = "這段時間不要來煩我。",
  ui_story_5043_50431201_37_dialog_content = "是、是的，史瓦大人！",
  ui_story_5043_50431201_38_dialog_content = "他把傭人趕走了。",
  ui_story_5043_50431201_39_dialog_content = "哼……接下來要做的事情，連自己人都得支開嗎？",
  ui_story_5043_50431201_40_dialog_content = "呃，會不會只是想清靜一下？",
  ui_story_5043_50431201_41_dialog_content = "你太鬆懈了，PlayerName。",
  ui_story_5043_50431201_42_dialog_content = "忘了我剛剛才說過嗎？史瓦可是個難以捉摸的人。",
  ui_story_5043_50431201_43_dialog_content = "我知道我知道。",
  ui_story_5043_50431201_44_dialog_content = "可是，再怎麼難以捉摸的人，在自家花園又能做出什麼特殊的事？",
  ui_story_5043_50431201_45_dialog_content = "你們看！他把手舉起來了！",
  ui_story_5043_50431201_46_dialog_content = "手上有什麼東西嗎？",
  ui_story_5043_50431201_47_dialog_content = "是針！他手上拿著一根針！",
  ui_story_5043_50431201_48_dialog_content = "針？！",
  ui_story_5043_50431201_49_dialog_content = "他想幹什麼？往自己手上刺嗎！",
  ui_story_5043_50431201_50_dialog_content = "不對，他要刺的是……",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5043_50431201_52_dialog_content = "他要刺的是手上那個玩偶……",
  ui_story_5043_50431201_53_dialog_content = "為、為什麼要對玩偶做這種事情？",
  ui_story_5043_50431201_54_dialog_content = "……你們有沒有聽說過一種透過玩偶施加詛咒的方法？",
  ui_story_5043_50431201_55_dialog_content = "詛咒？",
  ui_story_5043_50431201_56_dialog_content = "將他人身體的一部分——通常是血液或毛髮——放入玩偶體內。",
  ui_story_5043_50431201_57_dialog_content = "玩偶便會與那人的身體相連。",
  ui_story_5043_50431201_58_dialog_content = "接下來只要用針刺玩偶，相連的本人就會感到刺痛，甚至出現傷口。",
  ui_story_5043_50431201_59_dialog_content = "最後的結局，往往是疼痛而死。",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5043_50431201_61_dialog_content = "嘖，又刺進去一根了！",
  ui_story_5043_50431201_62_dialog_content = "我聽說過這種詛咒方法，但萬萬想不到這傢伙有如此陰暗的一面……",
  ui_story_5043_50431201_63_dialog_content = "這也不奇怪，他的深情溫柔好男人形象本來就有很多的表演成分。",
  ui_story_5043_50431201_64_dialog_content = "但說到底也只是用來嚇唬人的坊間傳說吧？",
  ui_story_5043_50431201_65_dialog_content = "而且，按照白夜城的教義，這種行為恐怕……",
  ui_story_5043_50431201_66_dialog_content = "我明白了，重要的不是詛咒是否真實存在而是人們是否相信。",
  ui_story_5043_50431201_67_dialog_content = "顯然史瓦相信了這個詛咒。",
  ui_story_5043_50431201_68_dialog_content = "此時此刻，世上有一個人被他憎恨著，憎恨到想要殺死的程度……",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5043_50431201_70_dialog_content = "這傢伙……是想殺人嗎？！",
  ui_story_5043_50431201_71_dialog_content = "到底是什麼人會得罪到他，令他恨得想殺死？",
  ui_story_5043_50431201_72_dialog_content = "嗯……確實是個值得思考的問題。",
  ui_story_5043_50431201_73_dialog_content = "史瓦的人生看起來光鮮亮麗，沒有人能阻礙他。",
  ui_story_5043_50431201_74_dialog_content = "那麼……仇恨也許來自於大眾看不到的地方。",
  ui_story_5043_50431201_75_dialog_content = "哎呀，你這樣說我就明白了。",
  ui_story_5043_50431201_76_dialog_content = "一定是因為一段不為人知的，刻骨銘心的<color=#FFB400>愛情</color>。",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5043_50431201_78_dialog_content = "果真如此的話，我們必須想辦法，這可是關乎人命的重要案件！",
  ui_story_5043_50431201_79_dialog_content = "別衝動，再怎樣也要等他做出實際的犯罪行為，我們才能出手。",
  ui_story_5043_50431201_80_dialog_content = "現在我們能做什麼？阻止他繼續刺娃娃嗎？",
  ui_story_5043_50431201_81_dialog_content = "你們覺得……傳說會不會是真的？",
  ui_story_5043_50431201_82_dialog_content = "你是說，用玩偶詛咒別人？",
  ui_story_5043_50431201_83_dialog_content = "嗯……",
  ui_story_5043_50431201_84_dialog_content = "如果真是那樣的話，我們可能……",
  ui_story_5043_50431201_85_dialog_content = "正在目睹一起「兇殺案」的現場……",
  ui_story_5043_50431201_86_dialog_content = "接下來是最後一根。",
  ui_story_5043_50431201_87_dialog_content = "看吧，一條生命即將……",
  ui_story_5043_50431201_88_dialog_content = "阻止他！快！",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>哧——</color>",
  ui_story_5043_50431201_90_dialog_content = "誕生了！！！",
  ui_story_5043_50431201_91_dialog_content = "小傢伙長得真可愛啊。",
  ui_story_5043_50431201_92_dialog_content = "得幫你取個名字……就叫「小栗子」吧！",
  ui_story_5043_50431201_93_dialog_content = "那是個……刺蝟玩偶？",
  ui_story_5043_50431201_94_dialog_content = "嗯，看樣子是刺蝟沒錯。",
  ui_story_5043_50431201_95_dialog_content = "確實很像一顆沒剝開的栗子。史瓦這傢伙還挺會取名字嘛。",
  ui_story_5043_50431201_96_dialog_content = "<size=45>所以我們是在緊張個什麼勁啊！！！</size>",
  ui_story_5043_50431201_97_dialog_content = "噓，PlayerName，小聲點。",
  ui_story_5043_50431201_98_dialog_content = "呼，真是太傻了……我們竟然還認真討論他會不會殺人。",
  ui_story_5043_50431201_99_dialog_content = "咳咳，探案總是得經歷一些試錯階段。",
  ui_story_5043_50431201_100_dialog_content = "謹慎面對每一種可能性，我們才能在真相來臨前做好準備。",
  ui_story_5043_50431201_101_dialog_content = "竟然能用這麼正經的理由說服自己……",
  ui_story_5043_50431201_102_dialog_content = "好了，忘掉剛才的事情，想想蒂娜吧。",
  ui_story_5043_50431201_103_dialog_content = "史瓦要進屋了，說不定會為明天的開庭做準備。",
  ui_story_5043_50431201_104_dialog_content = "我們快跟上去。",
  ui_story_5043_50431201_105_dialog_content = "哎，實驗還沒有完成。希望今天能有所進展……",
  ui_story_5043_50431201_106_dialog_content = "你們聽到了嗎，「實驗」？",
  ui_story_5043_50431201_107_dialog_content = "嗯，不知道他在研究什麼領域。",
  ui_story_5043_50431201_108_dialog_content = "呵，總覺得不是什麼好事，史瓦可是個難以捉摸的人。",
  ui_story_5043_50431201_109_dialog_content = "又來了，「難以捉摸的人」。",
  ui_story_5043_50431201_110_dialog_content = "有了剛才的前車之鑑，這次還是拋開先入為主的想法吧。",
  ui_story_5043_50431201_111_dialog_content = "不過是做實驗，說不定是某種業餘愛好……",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5043_50431201_113_dialog_content = "嗚哇！",
  ui_story_5043_50431201_114_dialog_content = "爆炸？他到底在搞什麼鬼？！",
  ui_story_5043_50431201_115_dialog_content = "不、不知道啊，我們靠近點看看？",
  ui_story_5043_50431201_116_dialog_content = "不行！室內沒有可以藏身的地方。",
  ui_story_5043_50431201_117_dialog_content = "再往近處走的話，我們的行蹤就會暴露……",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5043_50431201_119_dialog_content = "又爆炸了！這傢伙，搞不好在研製炸藥！",
  ui_story_5043_50431201_120_dialog_content = "炸藥？！不會那麼離譜吧……",
  ui_story_5043_50431201_121_dialog_content = "這也算是薩拉爾家族的本業了！",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5043_50431201_123_dialog_content = "可是他研製炸藥能幹嘛？",
  ui_story_5043_50431201_124_dialog_content = "越是像白夜城如此精雕細琢的地方，越經不起炸藥的摧殘。",
  ui_story_5043_50431201_125_dialog_content = "你想想，都有人為了一尊雕像的毀壞而鬧上法庭了。",
  ui_story_5043_50431201_126_dialog_content = "要是毀壞一座鐘塔、一棟教堂，後果更是不堪設想。",
  ui_story_5043_50431201_127_dialog_content = "萬一炸藥被有心人掌握，他們就可以將人們對破壞的恐懼化為自己的籌碼。",
  ui_story_5043_50431201_128_dialog_content = "那麼一點炸藥需要講成這樣嗎？你看他連自己家都沒炸壞。",
  ui_story_5043_50431201_129_dialog_content = "所以說現在只是「實驗」嘛。",
  ui_story_5043_50431201_130_dialog_content = "等他弄懂原理，就有可能藉助光能術將爆炸放大幾十甚至幾百倍。",
  ui_story_5043_50431201_131_dialog_content = "憑藉這個研究，史瓦可以徹底改變白夜城如今的社會格局。",
  ui_story_5043_50431201_132_dialog_content = "甚至於顛覆白夜城的統治都不為過……",
  ui_story_5043_50431201_133_dialog_content = "這、這麼嚴重？！",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>砰——！</color>",
  ui_story_5043_50431201_135_dialog_content = "咳、咳咳……",
  ui_story_5043_50431201_136_dialog_content = "看來還是不行啊。",
  ui_story_5043_50431201_137_dialog_content = "真沒想到，做個「<color=#FFB400>焦糖布丁</color>」竟然如此困難。",
  ui_story_5043_50431201_138_dialog_content = "……",
  ui_story_5043_50431201_139_dialog_content = "顛覆、白夜、統治——靠一個焦糖布丁？",
  ui_story_5043_50431201_140_dialog_content = "他、他是笨蛋嗎？！做甜點怎麼有辦法發出這麼大的爆炸聲啊？！",
  ui_story_5043_50431201_141_dialog_content = "你們對他的猜測也一樣離譜啊！",
  ui_story_5043_50431201_142_dialog_content = "噓，他要出來了，我們快躲起來。",
  ui_story_5043_50431201_143_dialog_content = "唉，又為沒意義的事情浪費了時間。",
  ui_story_5043_50431201_144_dialog_content = "還是做點正事吧，我的地下室鑰匙……哦，在這。",
  ui_story_5043_50431201_145_dialog_content = "開庭前再去那邊檢查一下……",
  ui_story_5043_50431201_146_dialog_content = "史瓦大人，晚飯時間到了，請來用餐。",
  ui_story_5043_50431201_147_dialog_content = "……我分明告訴過你們這段時間不要來煩我。",
  ui_story_5043_50431201_148_dialog_content = "對不起大人！可是……晚飯已經做好了……",
  ui_story_5043_50431201_149_dialog_content = "好吧，先吃晚飯，帶我去餐廳。",
  ui_story_5043_50431201_150_dialog_content = "史瓦去吃晚飯了。那邊傭人也多，看來跟蹤計畫只得暫緩。",
  ui_story_5043_50431201_151_dialog_content = "喂，有聽到他走之前說了什麼嗎？",
  ui_story_5043_50431201_152_dialog_content = "你該不會又要說他是難以捉摸的人吧？",
  ui_story_5043_50431201_153_dialog_content = "那個先不說，我是要說他剛才提到地下室。",
  ui_story_5043_50431201_154_dialog_content = "回想一下剛才發生的事情——他拿出鑰匙打算進去，結果被傭人叫走。",
  ui_story_5043_50431201_155_dialog_content = "你們看，那邊門上還插著鑰匙呢。",
  ui_story_5043_50431201_156_dialog_content = "想不想進去看看？那裡面肯定隱藏了不少祕密！",
  ui_story_5043_50431201_157_dialog_content = "這麼說來確實是難得的機會，不過……",
  ui_story_5043_50431201_158_dialog_content = "目前還沒看到與蒂娜有關的線索，擅闖地下室會不會有悖我們的初衷？",
  ui_story_5043_50431201_159_dialog_content = "如果你相信蒂娜無罪，那麼問題就一定出在史瓦身上。",
  ui_story_5043_50431201_160_dialog_content = "即便是受人利用，他身邊也該有蛛絲馬跡可循。",
  ui_story_5043_50431201_161_dialog_content = "沒有找到只代表我們挖得還不夠深。",
  ui_story_5043_50431201_162_dialog_content = "……也對，我們沒有退路了。走吧，一起去地下室看看。",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>吱——</color>",
  ui_story_5043_50431201_164_dialog_content = "哇！好黑！伸手不見五指啊！",
  ui_story_5043_50431201_165_dialog_content = "前面好像是一條向下的樓梯，勉強可以摸索著前進……",
  ui_story_5043_50431201_166_dialog_content = "蒂娜！蒂娜？妳在嗎？",
  ui_story_5043_50431201_167_dialog_content = "對了，PlayerName不是有感應能力嗎？",
  ui_story_5043_50431201_168_dialog_content = "先用你的那個能力查探裡面的狀況吧。",
  ui_story_5043_50431201_169_dialog_content = "好，我來試試。",
  ui_story_5043_50431201_170_option_content = "強制感應",
  ui_story_5043_50431201_171_dialog_content = "有個空裔在身邊還真方便啊。",
  ui_story_5043_50431201_172_dialog_content = "怎麼樣，有看到東西嗎？",
  ui_story_5043_50431201_173_dialog_content = "可以先找牆壁上有沒有蠟燭之類的照明物可以點亮。",
  ui_story_5043_50431201_174_dialog_content = "這個地下室好像很深……",
  ui_story_5043_50431201_175_dialog_content = "嗯？有東西朝我們過來了。",
  ui_story_5043_50431201_176_dialog_content = "這是……",
  ui_story_5043_50431201_177_dialog_content = "嘎——",
  ui_story_5043_50431201_178_dialog_content = "嗚哇哇哇哇哇！！！",
  ui_story_5043_50431201_179_dialog_content = "怎麼了？你看到什麼？",
  ui_story_5043_50431201_180_dialog_content = "快、快跑！快往回跑！",
  ui_story_5043_50431201_181_dialog_content = "有一票暗鬼爬過來了！！！",
  ui_story_5043_50431202_1_dialog_content = "嘎……",
  ui_story_5043_50431202_2_dialog_content = "怎麼會有暗鬼？好噁心啊！",
  ui_story_5043_50431202_3_dialog_content = "原來貴族家裡不只裝飾多，連暗鬼都這麼多？",
  ui_story_5043_50431202_4_dialog_content = "別誣衊貴族！我家裡可沒有這些噁心的怪物！",
  ui_story_5043_50431202_5_dialog_content = "快跑吧，牠們又要撲過來了！",
  ui_story_5043_50431202_6_dialog_content = "你們快往房外跑，我來攔住暗鬼！",
  ui_story_5043_50431202_7_dialog_content = "你、你沒問題嗎？",
  ui_story_5043_50431202_8_dialog_content = "別小看白夜城的審判官啊。",
  ui_story_5043_50431202_9_dialog_content = "暗鬼們，看招……",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5043_50431202_11_dialog_content = "哎呀！房間裡的吊燈被打碎了！",
  ui_story_5043_50431202_12_dialog_content = "好像是用北境的水晶礦做的吧？看起來很昂貴啊。",
  ui_story_5043_50431202_13_dialog_content = "應該不會叫我賠償吧……",
  ui_story_5043_50431202_14_dialog_content = "別管賠不賠償了！小心敵人！",
  ui_story_5043_50431202_15_dialog_content = "怎麼還有……",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>啪——！</color>",
  ui_story_5043_50431202_17_dialog_content = "漂亮！這次是茶几裂了！",
  ui_story_5043_50431202_18_dialog_content = "如此精美的做工，嘖嘖，史瓦會有多心疼啊。",
  ui_story_5043_50431202_19_dialog_content = "實在非常抱歉，但若要論賠償，我自認在這起案件中不負主要責任……",
  ui_story_5043_50431202_20_dialog_content = "好了啦！少說幾句！前面就是房門了！",
  ui_story_5043_50431202_21_dialog_content = "我們快逃出去吧！",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>十分鐘後</color>",
  ui_story_5043_50431202_23_dialog_content = "史瓦大人，宅內四處找過了，沒有外人的蹤影。",
  ui_story_5043_50431202_24_dialog_content = "就不曉得這一片狼藉……究竟是怎麼回事……",
  ui_story_5043_50431202_25_dialog_content = "……你確定沒有闖入者？",
  ui_story_5043_50431202_26_dialog_content = "嗯，目前來看是這樣。",
  ui_story_5043_50431202_27_dialog_content = "當然也有可能是對方手段高超，讓我們找不出端倪。",
  ui_story_5043_50431202_28_dialog_content = "不然……報案請審判庭派人來查吧？",
  ui_story_5043_50431202_29_dialog_content = "以您在審判庭的地位，這起案件一定會被重視！",
  ui_story_5043_50431202_30_dialog_content = "報案……",
  ui_story_5043_50431202_31_dialog_content = "算了吧，沒那個必要。",
  ui_story_5043_50431202_32_dialog_content = "不過是損失了一些可有可無的家具，再買新的就好。",
  ui_story_5043_50431202_33_dialog_content = "安排人把這裡打掃乾淨吧。",
  ui_story_5043_50431202_34_dialog_content = "是！史瓦大人！",
  ui_story_5043_50431202_35_dialog_content = "（地下室的門開著……）",
  ui_story_5043_50431202_36_dialog_content = "（吃飯之前，我有打開它了嗎？）",
  ui_story_5043_50431202_37_dialog_content = "（真是離譜，我竟然會犯下這種低級失誤。）",
  ui_story_5043_50431202_38_dialog_content = "（今天早點睡吧，開庭日得保持頭腦清醒。）",
  ui_story_5043_50431202_39_dialog_content = "哎呀，怎麼會弄成這樣。",
  ui_story_5043_50431202_40_dialog_content = "家裡名貴的吊燈和茶几都碎了。",
  ui_story_5043_50431202_41_dialog_content = "這一地碎片……也值不少錢吧。",
  ui_story_5043_50431202_42_dialog_content = "呼……呼……",
  ui_story_5043_50431202_43_dialog_content = "（總算……逃出來了！）",
  ui_story_5043_50431202_44_dialog_content = "怎麼樣，沒有人追上來吧？",
  ui_story_5043_50431202_45_dialog_content = "沒有，確定安全了。",
  ui_story_5043_50431202_46_dialog_content = "嘖，有夠狼狽。今天幹了真多蠢事。",
  ui_story_5043_50431202_47_dialog_content = "更糟糕的是，別說蒂娜本人，我們連一點有用的線索都沒找到。",
  ui_story_5043_50431202_48_dialog_content = "明天開庭時如何能為蒂娜脫罪……",
  ui_story_5043_50431202_49_dialog_content = "該做的我們已經做了，剩下的就是徹底履行身為審判官的職責。",
  ui_story_5043_50431202_50_dialog_content = "開庭前的這段時間，我們一起回想拼湊今天發生的所有細節吧。",
  ui_story_5043_50431202_51_dialog_content = "能夠形成逆轉的線索，必定隱藏在細微末節之中。",
  ui_story_5043_50431202_52_dialog_content = "這些是我們份內事，當然會做，只不過……",
  ui_story_5043_50431202_53_dialog_content = "缺少決定性線索，就像手裡沒有王牌。",
  ui_story_5043_50431202_54_dialog_content = "而史瓦手裡的底牌，我們又毫無頭緒。",
  ui_story_5043_50431202_55_dialog_content = "要這樣直接上法庭跟史瓦對決，實在讓人不安。",
  ui_story_5043_50431202_56_dialog_content = "牌局上並不一定是牌大的一方獲勝。",
  ui_story_5043_50431202_57_dialog_content = "沒有王牌，我們可以用牌技彌補。",
  ui_story_5043_50431202_58_dialog_content = "哼哼，你在關鍵時刻還是挺有自信的嘛？",
  ui_story_5043_50431202_59_dialog_content = "我是對真相有信心。",
  ui_story_5043_50431202_60_dialog_content = "一邊是掩蓋事實，一邊是挖掘真相，從根源上應該是我們佔優勢。",
  ui_story_5043_50431202_61_dialog_content = "況且今天潛入史瓦家，也並非毫無收穫……",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50431301_2_dialog_content = "（終於要開始了——）",
  ui_story_5043_50431301_3_dialog_content = "（「連環斷頭雕像案」的開庭時刻。）",
  ui_story_5043_50431301_4_dialog_content = "（零恩、馬太還有蒂娜，大家能在法庭上揭露真相嗎……）",
  ui_story_5043_50431301_5_dialog_content = "PlayerName！",
  ui_story_5043_50431301_6_dialog_content = "喔！卡蓮！還有洛維！",
  ui_story_5043_50431301_7_dialog_content = "你們回來了！",
  ui_story_5043_50431301_8_dialog_content = "嗯，跟大家說好了要在開庭日趕回來嘛。",
  ui_story_5043_50431301_9_dialog_content = "但是我怎麼聽說……",
  ui_story_5043_50431301_10_dialog_content = "蒂娜成了被告？",
  ui_story_5043_50431301_11_dialog_content = "馬太，你真的是太厲害了。",
  ui_story_5043_50431301_12_dialog_content = "喂，你再說一遍！",
  ui_story_5043_50431301_13_dialog_content = "確、確實是這樣。",
  ui_story_5043_50431301_14_dialog_content = "因為幾個古怪的證據，蒂娜被冤枉成嫌疑犯。",
  ui_story_5043_50431301_15_dialog_content = "不過，我相信法庭上會出現轉機！",
  ui_story_5043_50431301_16_dialog_content = "這兩天到底發生了什麼事？",
  ui_story_5043_50431301_17_dialog_content = "具體的來龍去脈，進去再慢慢說給妳聽吧。",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>高庭‧審判庭戀愛分部</color>",
  ui_story_5043_50431301_19_dialog_content = "肅靜、肅靜。",
  ui_story_5043_50431301_20_dialog_content = "諸位，我相信你們都厭倦了為這起案件三番五次來到法庭。",
  ui_story_5043_50431301_21_dialog_content = "遺憾的是，我們沒能阻止犯人屢次的惡行。",
  ui_story_5043_50431301_22_dialog_content = "但我們也很幸運，今天終於能為罪惡畫下句點。",
  ui_story_5043_50431301_23_dialog_content = "那麼，請允許我宣布——",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50431301_25_dialog_content = "「連環斷頭雕像案」，開庭！",
  ui_story_5043_50431301_26_dialog_content = "……",
  ui_story_5043_50431301_27_dialog_content = "……",
  ui_story_5043_50431301_28_dialog_content = "<size=30>大家……</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>相信他們吧，這是我們唯一能做的。</size>",
  ui_story_5043_50431301_30_dialog_content = "首先核對當事人和其他訴訟參加人的基本資料！",
  ui_story_5043_50431301_31_dialog_content = "原告，彼瑪隆先生。",
  ui_story_5043_50431301_32_dialog_content = "被告，蒂娜‧坎貝爾。",
  ui_story_5043_50431301_33_dialog_content = "是的，我們非常遺憾，戀愛法庭的一位審判官不得不坐在被告席上。",
  ui_story_5043_50431301_34_dialog_content = "這傢伙……",
  ui_story_5043_50431301_35_dialog_content = "本次訴訟由本人史瓦‧薩拉爾擔任審判長。",
  ui_story_5043_50431301_36_dialog_content = "由審判官馬太‧薩耶和零恩，以及尊敬的陪審團成員，共同組成合議庭。",
  ui_story_5043_50431301_37_dialog_content = "年輕人終於學會尊重了啊。",
  ui_story_5043_50431301_38_dialog_content = "我們這些經驗豐富的陪審團成員可是審查案件的重要助力。",
  ui_story_5043_50431301_39_dialog_content = "諸位同僚對這起案件有什麼看法？",
  ui_story_5043_50431301_40_dialog_content = "……",
  ui_story_5043_50431301_41_dialog_content = "……",
  ui_story_5043_50431301_42_dialog_content = "哦對，現在應該保持安靜。",
  ui_story_5043_50431301_43_dialog_content = "案件的基本情況都寫在各位面前的文件當中，可以隨時查看。",
  ui_story_5043_50431301_44_dialog_content = "由於調查進行得非常充分，已徹底理清事件的脈絡。",
  ui_story_5043_50431301_45_dialog_content = "接下來由我對「連環斷頭雕像案」的調查結果進行簡單陳述。",
  ui_story_5043_50431301_46_dialog_content = "被告蒂娜，出於對戀愛風潮的抵觸心理，選擇以破壞雕像的方式發洩其不滿。",
  ui_story_5043_50431301_47_dialog_content = "前兩次作案，她借助審判官的身分幫自己消除證據，沒有留下痕跡。",
  ui_story_5043_50431301_48_dialog_content = "但是第三次作案，由於彼瑪隆先生及時報案，零恩審判官提前做好了準備。",
  ui_story_5043_50431301_49_dialog_content = "在案發現場，他從犯人手上取得了至關重要的證物——",
  ui_story_5043_50431301_50_dialog_content = "就是這隻手套。",
  ui_story_5043_50431301_51_dialog_content = "幹得漂亮！這豈不是直接指向犯人的線索嗎！",
  ui_story_5043_50431301_52_dialog_content = "沒錯。我立刻派手下去調查，並在蒂娜審判官的辦公桌抽屜裡發現了另一隻手套。",
  ui_story_5043_50431301_53_dialog_content = "完全就是成對的啊！",
  ui_story_5043_50431301_54_dialog_content = "經過比對，這兩隻手套完全符合，屬於同一位主人。",
  ui_story_5043_50431301_55_dialog_content = "也就是現在坐在被告席上的蒂娜‧坎貝爾女士。",
  ui_story_5043_50431301_56_dialog_content = "不是……",
  ui_story_5043_50431301_X56_dialog_content = "厲害啊，史瓦審判長！果然是英雄出少年！",
  ui_story_5043_50431301_57_dialog_content = "基於這些不容辯駁的證據，本庭擬以「損壞公物、妨礙戀情」的罪名將被告法辦。",
  ui_story_5043_50431301_58_dialog_content = "當然，接下來被告也可以為自己進行辯解。",
  ui_story_5043_50431301_59_dialog_content = "然後祈禱你聲淚俱下的表演可以感動陪審席，讓他們為你投下顛倒黑白的一票。",
  ui_story_5043_50431301_60_dialog_content = "你……",
  ui_story_5043_50431301_61_dialog_content = "那是不可能的！",
  ui_story_5043_50431301_62_dialog_content = "坐在這個席位上都要遵循一個最重要的原則——公正！",
  ui_story_5043_50431301_63_dialog_content = "我說得沒錯吧，各位陪審團同僚？",
  ui_story_5043_50431301_64_dialog_content = "……",
  ui_story_5043_50431301_65_dialog_content = "……",
  ui_story_5043_50431301_66_dialog_content = "關於證物的手套，我不知道如何解釋……",
  ui_story_5043_50431301_67_dialog_content = "那確實是我的手套，但並不是我帶去案發現場的。",
  ui_story_5043_50431301_68_dialog_content = "我本來在跟暗鬼作戰，根本沒有空閒接近雕像。",
  ui_story_5043_50431301_69_dialog_content = "等我看到雕像的時候，它已經被真凶給破壞了……",
  ui_story_5043_50431301_70_dialog_content = "有人能幫妳作證嗎？",
  ui_story_5043_50431301_71_dialog_content = "我……",
  ui_story_5043_50431301_72_dialog_content = "對不起，我一度與大家走失，沒人能為我作證……",
  ui_story_5043_50431301_73_dialog_content = "既然如此，妳的辯駁並不足以推翻目前的定論。",
  ui_story_5043_50431301_74_dialog_content = "如果沒法提出更有力的證據，我們將會以「損壞公物、妨礙戀情」的罪名將妳……",
  ui_story_5043_50431301_75_dialog_content = "<size=45>等一下！！！</size>",
  ui_story_5043_50431301_76_dialog_content = "……馬太審判官？",
  ui_story_5043_50431301_77_dialog_content = "我要對史瓦審判長的裁決提出異議！",
  ui_story_5043_50431301_78_dialog_content = "蒂娜不可能是「連環斷頭雕像案」的犯人，她有不在場證明！",
  ui_story_5043_50431301_79_dialog_content = "呵，不在場證明？",
  ui_story_5043_50431301_80_dialog_content = "馬太審判官，請你仔細說明。",
  ui_story_5043_50431301_81_dialog_content = "最好能說得夠客觀、理性。",
  ui_story_5043_50431301_82_dialog_content = "不然的話，我會開始懷疑這個案子有共犯的可能性。",
  ui_story_5043_50431301_83_dialog_content = "咳咳，讓我們回到案件的最初。",
  ui_story_5043_50431301_84_dialog_content = "第一起「斷頭雕像案」發生的時候。",
  ui_story_5043_50431301_85_dialog_content = "我調查過犯人在那一天的動向。",
  ui_story_5043_50431301_86_dialog_content = "很遺憾，她並沒有不在場證明。",
  ui_story_5043_50431301_87_dialog_content = "重要的不是案發當時，而是案發之後！",
  ui_story_5043_50431301_88_dialog_content = "當天下午，蒂娜在審判庭與我一起工作了四個小時。",
  ui_story_5043_50431301_89_dialog_content = "我可以替她作證，其他工作人員也可以幫她證明。",
  ui_story_5043_50431301_90_dialog_content = "好，你們工作了四個小時，然後呢？",
  ui_story_5043_50431301_91_dialog_content = "她可以作案後再回到審判庭與你一同工作啊。",
  ui_story_5043_50431301_92_dialog_content = "錯！這四個小時就是最佳的不在場證明！",
  ui_story_5043_50431301_93_dialog_content = "蒂娜患有「強睡症」，白夜城各大醫院都可以證明這一點。",
  ui_story_5043_50431301_94_dialog_content = "就她的情況，一天之中清醒的時間只有四個小時！",
  ui_story_5043_50431301_95_dialog_content = "……",
  ui_story_5043_50431301_96_dialog_content = "也就是說，除了可以被證明的工作時間外，蒂娜其他時候應該都在睡覺！",
  ui_story_5043_50431301_97_dialog_content = "她不可能破壞第一尊雕像！",
  ui_story_5043_50431301_98_dialog_content = "她竟然在工作時間睡覺？！",
  ui_story_5043_50431301_99_dialog_content = "不知廉恥，現在薪水這麼好混嗎？",
  ui_story_5043_50431301_100_dialog_content = "啊對！我當時是在睡覺！",
  ui_story_5043_50431301_101_dialog_content = "睡醒之後才聽說了「斷頭雕像案」的事情。",
  ui_story_5043_50431301_102_dialog_content = "怎麼樣！她真的有不在場證明吧！",
  ui_story_5043_50431301_103_dialog_content = "你的論調太不嚴謹了！",
  ui_story_5043_50431301_104_dialog_content = "竟然用「推測」的方式為嫌犯製造不在場證明，審判官可以靠「推測」斷案嗎！",
  ui_story_5043_50431301_105_dialog_content = "案發當時的人證、物證，你可以拿出來哪一樣……",
  ui_story_5043_50431301_106_dialog_content = "我明白！審判長大人想要證據。",
  ui_story_5043_50431301_107_dialog_content = "好，接著讓我們看看第二起「斷頭雕像案」。",
  ui_story_5043_50431301_108_dialog_content = "這起案件中，蒂娜同樣擁有不在場證明。",
  ui_story_5043_50431301_109_dialog_content = "我和零恩都可以當證人。",
  ui_story_5043_50431301_110_dialog_content = "呵，是證人還是共犯，還不能肯定吧？",
  ui_story_5043_50431301_111_dialog_content = "哎呀，看來審判長大人很不信任同一部門的審判官呢。",
  ui_story_5043_50431301_112_dialog_content = "沒關係，還有其他證人來到法庭上。",
  ui_story_5043_50431301_113_dialog_content = "而且我相信，她們的身分都有足夠的公信力。",
  ui_story_5043_50431301_114_dialog_content = "史瓦審判長，你該不會也想把白夜城的公主殿下當成共犯吧？",
  ui_story_5043_50431301_115_dialog_content = "……",
  ui_story_5043_50431301_116_dialog_content = "……是她？",
  ui_story_5043_50431301_117_dialog_content = "案發當時，我們正在中庭的草地廣場經歷一場動亂。",
  ui_story_5043_50431301_118_dialog_content = "……我明白你的意思，但先平息混亂要緊！",
  ui_story_5043_50431301_119_dialog_content = "各位，請不要驚慌！跟著我從這邊走！",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>啪——</color>",
  ui_story_5043_50431301_121_dialog_content = "（什麼聲音？！）",
  ui_story_5043_50431301_122_dialog_content = "當時是我第一個聽到雕像被打碎的聲音，然後就與蒂娜審判官前往調查。",
  ui_story_5043_50431301_123_dialog_content = "我們兩個一起在案發現場發現斷了頭的雕像。",
  ui_story_5043_50431301_124_dialog_content = "過程中蒂娜審判官從未離開我的視線，擁有完美的不在場證明。",
  ui_story_5043_50431301_125_dialog_content = "這一點，相信卡蓮殿下和修女大人都可以為我們作證。",
  ui_story_5043_50431301_126_dialog_content = "是的，案發前蒂娜一直與我們在一起。",
  ui_story_5043_50431301_127_dialog_content = "她不具備犯案的條件。",
  ui_story_5043_50431301_128_dialog_content = "嗯，我也可以為蒂娜審判官作證。",
  ui_story_5043_50431301_129_dialog_content = "怎麼樣？史瓦審判長。",
  ui_story_5043_50431301_130_dialog_content = "這人證符合你的需求嗎？",
  ui_story_5043_50431301_131_dialog_content = "好，好。",
  ui_story_5043_50431301_132_dialog_content = "公主殿下的證言，本庭當然尊重。",
  ui_story_5043_50431301_133_dialog_content = "哦，不只公主殿下，馬太審判官的激昂演說也觸動了我。",
  ui_story_5043_50431301_134_dialog_content = "讓我認識到，我犯了一個小小的錯誤，冤枉了蒂娜‧坎貝爾女士。",
  ui_story_5043_50431301_135_dialog_content = "（成、成功了嗎？）",
  ui_story_5043_50431301_136_dialog_content = "本庭收回先前的誤判，蒂娜‧坎貝爾不是「連環斷頭雕像案」的犯人。",
  ui_story_5043_50431301_137_dialog_content = "她只是<color=#FFB400>第‧三‧起</color>「斷頭雕像案」的犯人。",
  ui_story_5043_50431301_138_dialog_content = "啥……",
  ui_story_5043_50431301_139_dialog_content = "嘖。",
  ui_story_5043_50431301_140_dialog_content = "馬太審判官的努力卓有成效！我相信被告需受的處罰將因此大大減輕。",
  ui_story_5043_50431301_141_dialog_content = "但是！最核心的證物沒有被推翻，目前她仍然是第三起案件的犯人！",
  ui_story_5043_50431301_142_dialog_content = "蒂娜‧坎貝爾仍將會被本庭以「損壞公物、妨礙戀情」的罪名法辦。",
  ui_story_5043_50431301_143_dialog_content = "這一點，相信馬太審判官也認同吧？",
  ui_story_5043_50431301_144_dialog_content = "認同個屁啊……",
  ui_story_5043_50431301_145_dialog_content = "還是說，你想要繼續對本案的核心證物提出質疑？",
  ui_story_5043_50431301_146_dialog_content = "……",
  ui_story_5043_50431301_147_dialog_content = "<size=30>馬太……加油啊……</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>但是現在這樣還不足以……</size>",
  ui_story_5043_50431301_149_dialog_content = "沒有了，我想說的就這些。",
  ui_story_5043_50431301_150_dialog_content = "什麼……",
  ui_story_5043_50431301_151_dialog_content = "呵呵，就這樣嗎？",
  ui_story_5043_50431301_152_dialog_content = "嗯。",
  ui_story_5043_50431301_153_dialog_content = "既然如此，本庭……",
  ui_story_5043_50431301_154_dialog_content = "零恩，該換班了。",
  ui_story_5043_50431301_155_dialog_content = "！！！",
  ui_story_5043_50431301_156_dialog_content = "零恩？",
  ui_story_5043_50431301_157_dialog_content = "新人，要抓住機會好好表現哦。",
  ui_story_5043_50431301_158_dialog_content = "嗯。",
  ui_story_5043_50431301_159_dialog_content = "史瓦審判長、陪審團，還有旁聽席的各位。",
  ui_story_5043_50431301_160_dialog_content = "希望你們給我幾分鐘的時間。",
  ui_story_5043_50431301_161_dialog_content = "讓我們來做一點<color=#FFB400>推理</color>。",
  ui_story_5043_50431301_162_dialog_content = "嘖嘖，這小子說話有點狂啊。",
  ui_story_5043_50431301_163_dialog_content = "零恩審判官，我以為庶民出身的你會想加倍謹言慎行。",
  ui_story_5043_50431301_164_dialog_content = "要是工作上出了紕漏，你可不像馬太審判官有家族幫忙撐腰。",
  ui_story_5043_50431301_165_dialog_content = "史瓦審判長，我認為庶民出身不一定是壞事。",
  ui_story_5043_50431301_166_dialog_content = "至少我不用擔心自己犯下的錯會連累整個家族。",
  ui_story_5043_50431301_167_dialog_content = "你……",
  ui_story_5043_50431301_168_dialog_content = "我聽史瓦審判長非常在意核心證物和第三起案件。",
  ui_story_5043_50431301_169_dialog_content = "那我們就聚焦於這起案件，做一次詳細的梳理。",
  ui_story_5043_50431301_170_dialog_content = "貼近細節，尋找那些連犯人都忘記的蛛絲馬跡。",
  ui_story_5043_50431301_171_dialog_content = "哦不錯！很有專業性！我最欣賞專業表現！",
  ui_story_5043_50431301_172_dialog_content = "（連犯人都忘記的蛛絲馬跡……）",
  ui_story_5043_50431301_173_dialog_content = "（零恩，總算讓你找到了嗎？）",
  ui_story_5043_50431301_174_dialog_content = "讓我們回到昨天的千星階梯，案件發生之前。",
  ui_story_5043_50431301_175_dialog_content = "為了保護千星階梯上方的雕像，我們一行人試圖阻止遊行隊伍繼續前進。",
  ui_story_5043_50431301_176_dialog_content = "沒有想到的是，遊行隊伍末尾莫名冒出一小團暗鬼。",
  ui_story_5043_50431301_177_dialog_content = "我立刻投入戰鬥。過沒多久，蒂娜也趕了過來……",
  ui_story_5043_50431302_1_dialog_content = "倒數第三隻暗鬼被我一腳踹下台階。",
  ui_story_5043_50431302_2_dialog_content = "倒數第二隻暗鬼被我用轉輪刺穿。",
  ui_story_5043_50431302_3_dialog_content = "而最後一隻暗鬼，被蒂娜一拳轟得粉碎。",
  ui_story_5043_50431302_4_dialog_content = "可以了可以了，沒必要這麼詳細吧？",
  ui_story_5043_50431302_5_dialog_content = "徹底討伐眼前的一小批暗鬼後，我和蒂娜打算回到雕像處與其他人會合。",
  ui_story_5043_50431302_6_dialog_content = "路上需要穿過擁擠的人群，其實頗為艱難。",
  ui_story_5043_50431302_7_dialog_content = "在這個過程中，我與蒂娜走失，直到案發後才再次見到她。",
  ui_story_5043_50431302_8_dialog_content = "嗯，人群中實在太擠了，我被困住無法前進……",
  ui_story_5043_50431302_9_dialog_content = "這一點與我瞭解的相同。",
  ui_story_5043_50431302_10_dialog_content = "顯示蒂娜‧坎貝爾在這起案件中不具備不在場證明。",
  ui_story_5043_50431302_11_dialog_content = "不在場證明我們先放到一邊，接下來看到案發的時刻。",
  ui_story_5043_50431302_12_dialog_content = "等我回到雕像處，又有其他暗鬼襲擊過來。",
  ui_story_5043_50431302_13_dialog_content = "我們圍在雕像附近與暗鬼作戰，給了犯人可乘之機。",
  ui_story_5043_50431302_14_dialog_content = "犯人趁著戰鬥的混亂，伸出魔爪敲碎了雕像的頭部。",
  ui_story_5043_50431302_15_dialog_content = "我抓住了犯人的手，但犯人混在暗鬼群當中，身形樣貌都難以辨認。",
  ui_story_5043_50431302_16_dialog_content = "對方迅速掙脫了我的控制，只留下手套在我手中。",
  ui_story_5043_50431302_17_dialog_content = "嗯，那就成了本案的核心線索。",
  ui_story_5043_50431302_18_dialog_content = "卡蓮殿下和馬太審判官立刻消滅了周圍的暗鬼，但開闊的場地上不見犯人的身影。",
  ui_story_5043_50431302_19_dialog_content = "再之後，蒂娜審判官才跑回來與我們會合。",
  ui_story_5043_50431302_20_dialog_content = "這就是案發前後的完整流程。",
  ui_story_5043_50431302_21_dialog_content = "很好，零恩審判官的發言非常客觀。",
  ui_story_5043_50431302_22_dialog_content = "接下來的推理手法順理成章，沿著手套調查下去，就能找到真正的犯人。",
  ui_story_5043_50431302_23_dialog_content = "我們也正是透過這種方式，取證並逮捕了被告。",
  ui_story_5043_50431302_24_dialog_content = "不，史瓦審判長，你的推理太草率了。",
  ui_story_5043_50431302_25_dialog_content = "嗯？",
  ui_story_5043_50431302_26_dialog_content = "根據案發現場，我們能得到的犯人情報應該是這樣——",
  ui_story_5043_50431302_27_dialog_content = "佩戴著證物所示的手套，並徒手敲碎了雕像。",
  ui_story_5043_50431302_28_dialog_content = "而你所逮捕的被告特徵是——",
  ui_story_5043_50431302_29_dialog_content = "證物手套的合法持有者，年輕女性。",
  ui_story_5043_50431302_30_dialog_content = "若是更嚴謹探究則不難發現，這二者並不完全相等。",
  ui_story_5043_50431302_31_dialog_content = "你太鑽牛角尖了。",
  ui_story_5043_50431302_32_dialog_content = "手套的持有者最有機會在現場佩戴那隻手套，這有什麼問題？",
  ui_story_5043_50431302_33_dialog_content = "這部分沒問題，有問題的地方出在後面。",
  ui_story_5043_50431302_34_dialog_content = "蒂娜審判官能徒手敲碎雕像嗎？",
  ui_story_5043_50431302_35_dialog_content = "哦喲？新的角度。",
  ui_story_5043_50431302_36_dialog_content = "仔細想想也是啊，一個女孩子哪能徒手敲碎雕像呢？",
  ui_story_5043_50431302_37_dialog_content = "零恩審判官，你是不是想太多導致大腦當機了？",
  ui_story_5043_50431302_38_dialog_content = "回憶一下你自己兩分鐘前說的話吧。",
  ui_story_5043_50431302_39_dialog_content = "倒數第三隻暗鬼被我一腳踹下台階。",
  ui_story_5043_50431302_40_dialog_content = "倒數第二隻暗鬼被我用轉輪刺穿。",
  ui_story_5043_50431302_41_dialog_content = "而最後一隻暗鬼，被蒂娜<color=#FFB400>一拳轟得粉碎</color>。",
  ui_story_5043_50431302_42_dialog_content = "你不瞭解自己的同事嗎？她可是繼承了「神之手」的坎貝爾家新貴。",
  ui_story_5043_50431302_43_dialog_content = "搗碎暗鬼都輕而易舉，何況是一尊雕像呢。",
  ui_story_5043_50431302_44_dialog_content = "對耶！她不是普通的年輕女孩！",
  ui_story_5043_50431302_45_dialog_content = "年輕人，推理的過程欠缺考慮啊。",
  ui_story_5043_50431302_46_dialog_content = "（還是太牽強了。）",
  ui_story_5043_50431302_47_dialog_content = "（零恩有沒有更進一步，連敵人都沒發現的細節……）",
  ui_story_5043_50431302_48_dialog_content = "哦，對。蒂娜繼承了「神之手」。",
  ui_story_5043_50431302_49_dialog_content = "所以，她靠「神之手」來敲碎雕像，是這個意思嗎？",
  ui_story_5043_50431302_50_dialog_content = "沒錯，這是唯一的合理推論。",
  ui_story_5043_50431302_51_dialog_content = "零恩審判官，你嚴謹的思考方式值得鼓勵。",
  ui_story_5043_50431302_52_dialog_content = "但是再有這種問題，我建議你私下找我，不要在法庭上浪費大家的時間。",
  ui_story_5043_50431302_53_dialog_content = "不，沒有人的時間被浪費。",
  ui_story_5043_50431302_54_dialog_content = "一切推理都是為了得到你剛剛認可的那個結論。",
  ui_story_5043_50431302_55_dialog_content = "「蒂娜靠神之手敲碎了雕像。」",
  ui_story_5043_50431302_56_dialog_content = "……別故弄玄虛，你想說什麼？",
  ui_story_5043_50431302_57_dialog_content = "有了這條結論，我們再回頭一看就會發現。",
  ui_story_5043_50431302_58_dialog_content = "使蒂娜坐上被告席的手套，反而成了證明她無罪的鐵證！",
  ui_story_5043_50431302_59_dialog_content = "什麼？！",
  ui_story_5043_50431302_60_dialog_content = "請允許我向所有人展示本案的關鍵證物——犯人作案時佩戴的手套。",
  ui_story_5043_50431302_61_dialog_content = "史瓦審判長不允許我們接觸它的這段時間裡，也許有一些痕跡已經被清除掉了。",
  ui_story_5043_50431302_62_dialog_content = "不過沒關係，至少手套並沒有被換掉，這點我們應該可以相信吧？",
  ui_story_5043_50431302_63_dialog_content = "審判庭保護證物不受到任何接觸是最基本的責任，你是在質疑審判庭的基礎職守嗎？！",
  ui_story_5043_50431302_64_dialog_content = "那就好。",
  ui_story_5043_50431302_65_dialog_content = "請大家仔細觀察一下這隻手套。",
  ui_story_5043_50431302_66_dialog_content = "這是……戴在右手上的對吧？",
  ui_story_5043_50431302_67_dialog_content = "別廢話了，說重點！",
  ui_story_5043_50431302_68_dialog_content = "戴在哪隻手上又有……",
  ui_story_5043_50431302_69_dialog_content = "！！！",
  ui_story_5043_50431302_70_dialog_content = "嗯？",
  ui_story_5043_50431302_71_dialog_content = "啊——！",
  ui_story_5043_50431302_72_dialog_content = "右手！！！原來是這樣！",
  ui_story_5043_50431302_73_dialog_content = "怎麼回事？！到底是怎樣？",
  ui_story_5043_50431302_74_dialog_content = "看來你已經想到了，史瓦審判官。",
  ui_story_5043_50431302_75_dialog_content = "這是一個無法被抹除的、致命的失誤。",
  ui_story_5043_50431302_76_dialog_content = "蒂娜能夠敲碎雕像的「神之手」是她的<color=#FFB400>左手</color>。",
  ui_story_5043_50431302_77_dialog_content = "而這隻手套，是<color=#FFB400>右手</color>的手套！",
  ui_story_5043_50431302_78_dialog_content = "哦！！！原來是這樣！！！",
  ui_story_5043_50431302_79_dialog_content = "左手……右手……",
  ui_story_5043_50431302_80_dialog_content = "既然您在法庭上持續強調核心證物的重要性。",
  ui_story_5043_50431302_81_dialog_content = "我想，現在我們也同樣應該尊重證物。",
  ui_story_5043_50431302_82_dialog_content = "就憑這隻與蒂娜「神之手」相違的手套，您會得出什麼樣的結論呢？",
  ui_story_5043_50431302_83_dialog_content = "史瓦審判長，請您宣告给大家聽吧。",
  ui_story_5043_50431302_84_dialog_content = "你……你……",
  ui_story_5043_50431302_85_dialog_content = "竟然靠定罪的同一個證物脫罪，幹得漂亮啊零恩！",
  ui_story_5043_50431302_86_dialog_content = "這下天平重新傾斜向我們這邊了！",
  ui_story_5043_50431302_87_dialog_content = "竟然在這種地方……",
  ui_story_5043_50431302_88_dialog_content = "好吧，好吧。我承認你們的詭辯算有水準。",
  ui_story_5043_50431302_89_dialog_content = "以目前的證據來看，不足以將蒂娜‧坎貝爾定罪。",
  ui_story_5043_50431302_90_dialog_content = "「連環斷頭雕像案」的凶手身分再次恢復謎團。",
  ui_story_5043_50431302_91_dialog_content = "太好了！！！",
  ui_story_5043_50431302_92_dialog_content = "卡蓮，他們成功了！",
  ui_story_5043_50431302_93_dialog_content = "嗯！真是太好了！",
  ui_story_5043_50431302_94_dialog_content = "能夠在審判庭見證白夜城的公正是我的榮幸！",
  ui_story_5043_50431302_95_dialog_content = "凶手身分再次恢復謎團。也就是說……",
  ui_story_5043_50431302_96_dialog_content = "我脫罪了，對吧！",
  ui_story_5043_50431302_97_dialog_content = "當然，蒂娜。妳一直是清白的啊。",
  ui_story_5043_50431302_98_dialog_content = "記得好好感謝我們啊，尤其是庶民新人。",
  ui_story_5043_50431302_99_dialog_content = "以第一次的大場面表演，他做得還不錯。",
  ui_story_5043_50431302_100_dialog_content = "嗯嗯！當然要好好感謝你們！",
  ui_story_5043_50431302_101_dialog_content = "我的好同事！",
  ui_story_5043_50431302_102_dialog_content = "喂，喂，怎麼回事？",
  ui_story_5043_50431302_103_dialog_content = "搞了半天，又抓錯人了？",
  ui_story_5043_50431302_104_dialog_content = "……",
  ui_story_5043_50431302_105_dialog_content = "天哪，不會吧。",
  ui_story_5043_50431302_106_dialog_content = "你們讓我坐在這裡聽了大半天的長篇大論，最後卻說一切又回到原點？",
  ui_story_5043_50431302_107_dialog_content = "我說過了哦！我的耐心有限！",
  ui_story_5043_50431302_108_dialog_content = "如果今天無法讓案件畫下句點，我就讓你們戀愛法庭畫下句點！！！",
  ui_story_5043_50431302_109_dialog_content = "先不要急，原告先生。事態才發展到一半。",
  ui_story_5043_50431302_110_dialog_content = "一半？",
  ui_story_5043_50431302_111_dialog_content = "蒂娜，先回到我們身邊吧。",
  ui_story_5043_50431302_112_dialog_content = "被告席接下來要讓給另一位先生了。",
  ui_story_5043_50431302_113_dialog_content = "嗯？另一位先生是……",
  ui_story_5043_50431302_114_dialog_content = "經過戀愛法庭嚴密的調查取證，本庭審判官零恩——",
  ui_story_5043_50431302_115_dialog_content = "審判官馬太——",
  ui_story_5043_50431302_116_dialog_content = "擬以「損壞公物、妨礙戀情」的罪名，起訴史瓦‧薩拉爾先生。",
  ui_story_5043_50431302_117_dialog_content = "審判長，請您移駕吧。",
  ui_story_5043_50431302_118_dialog_content = "什麼？起訴史瓦？！",
  ui_story_5043_50431302_119_dialog_content = "PlayerName，這也在你們的計畫之中嗎？",
  ui_story_5043_50431302_120_dialog_content = "呃......",
  ui_story_5043_50431302_121_dialog_content = "我們昨天確實懷疑過史瓦，但是……",
  ui_story_5043_50431302_122_dialog_content = "我不曉得要起訴他的事情……",
  ui_story_5043_50431302_123_dialog_content = "你們拿到了什麼關鍵性的證據？",
  ui_story_5043_50431302_124_dialog_content = "完全沒有……",
  ui_story_5043_50431302_125_dialog_content = "起訴我？",
  ui_story_5043_50431302_126_dialog_content = "零恩審判官，你明白自己在說什麼嗎？",
  ui_story_5043_50431302_127_dialog_content = "我只是尊重自己的職業倫理。",
  ui_story_5043_50431302_128_dialog_content = "呵，你最好真的尊重。",
  ui_story_5043_50431302_129_dialog_content = "我告訴你，三起案件發生時，我都有毫無爭議的不在場證明。",
  ui_story_5043_50431302_130_dialog_content = "稍微做過一點調查，審判庭裡的工作人員就能夠證實我的說法。",
  ui_story_5043_50431302_131_dialog_content = "對於如此蠻不講理的誣衊，我想我沒必要再辯解。",
  ui_story_5043_50431302_132_dialog_content = "請放心，史瓦先生，這些簡單調查我當然會做。",
  ui_story_5043_50431302_133_dialog_content = "我也認同你的觀點，你在每一起案件發生時都有不在場證明。",
  ui_story_5043_50431302_134_dialog_content = "那你還不收回自己愚蠢的起訴？",
  ui_story_5043_50431302_135_dialog_content = "但是，犯下罪行未必需要犯人親自在場。",
  ui_story_5043_50431302_136_dialog_content = "我可以傳喚一位證人嗎？",
  ui_story_5043_50431302_137_dialog_content = "證人？",
  ui_story_5043_50431302_138_dialog_content = "請證人入場，發表證言。",
  ui_story_5043_50431302_139_dialog_content = "（我們何時有了證人？）",
  ui_story_5043_50431302_140_dialog_content = "（到底是誰……）",
  ui_story_5043_50431302_141_dialog_content = "我、我……",
  ui_story_5043_50431302_142_dialog_content = "我可以說話嗎？",
  ui_story_5043_50431302_143_dialog_content = "暗鬼？還會說話？！",
  ui_story_5043_50431302_144_dialog_content = "狗、狗蛋！！！",
  ui_story_5043_50431302_145_dialog_content = "咦？！！怎麼會是牠！",
  ui_story_5043_50431302_146_dialog_content = "請暗鬼當證人？這是怎麼回事……",
  ui_story_5043_50431302_147_dialog_content = "你瘋了嗎！竟然把這種骯髒的東西帶上法庭！",
  ui_story_5043_50431302_148_dialog_content = "意圖擾亂庭上秩序嗎？",
  ui_story_5043_50431302_149_dialog_content = "請放心，我們已經確認過，這隻暗鬼無害。",
  ui_story_5043_50431302_150_dialog_content = "牠不會傷害任何人，只為了揭露真相而來到法庭發表證言。",
  ui_story_5043_50431302_151_dialog_content = "我相信在場應該沒人排斥真相吧？",
  ui_story_5043_50431302_152_dialog_content = "唔，若是如此，聽牠講講也不為過。",
  ui_story_5043_50431302_153_dialog_content = "狗蛋，又比上次看到時瘦了……",
  ui_story_5043_50431302_154_dialog_content = "如此特殊的一位證人，能提出何等驚人的證言呢……",
  ui_story_5043_50431302_155_dialog_content = "我、我先，我先自我介紹一下。",
  ui_story_5043_50431302_156_dialog_content = "希望你們不、不要害怕我。",
  ui_story_5043_50431302_157_dialog_content = "我原本是一隻普通的低級暗鬼。",
  ui_story_5043_50431302_158_dialog_content = "在、在迦南城不小心吃下了一個實驗道具。",
  ui_story_5043_50431302_159_dialog_content = "我不知道那是什麼，但是……",
  ui_story_5043_50431302_160_dialog_content = "我的外形因此發生變化，同時也擁有了清晰的意識。",
  ui_story_5043_50431302_161_dialog_content = "嘖，看看啟光那些傢伙又研究出了什麼鬼東西！",
  ui_story_5043_50431302_162_dialog_content = "竟然一口氣說出這麼長一段話，牠的通用語好像變流利了很多？",
  ui_story_5043_50431302_163_dialog_content = "然後我、我跟其他暗鬼的聯繫就變弱了。",
  ui_story_5043_50431302_164_dialog_content = "牠們無法控制我，我也無法控制牠們。",
  ui_story_5043_50431302_165_dialog_content = "之後在暗鬼族群中總是搞砸事情……沒辦法順利完成工作……",
  ui_story_5043_50431302_166_dialog_content = "首領忍無可忍，最終把我趕了出來……",
  ui_story_5043_50431302_167_dialog_content = "她說，如果非要添麻煩，就去給光靈添麻煩吧……",
  ui_story_5043_50431302_168_dialog_content = "呃，原來還有這種被暗鬼討厭的暗鬼啊。",
  ui_story_5043_50431302_169_dialog_content = "別同情牠，敵人的敵人未必就是朋友。",
  ui_story_5043_50431302_170_dialog_content = "再之後，我試著學習光靈的語言和文化。",
  ui_story_5043_50431302_171_dialog_content = "為、為了活下去而輾轉各處打工，只不過老是被炒魷魚……",
  ui_story_5043_50431302_172_dialog_content = "生活雖然艱苦，但我覺得過得比以前開心。",
  ui_story_5043_50431302_173_dialog_content = "我不會傷害大家。",
  ui_story_5043_50431302_174_dialog_content = "我、我喜歡光靈的生活！",
  ui_story_5043_50431302_X174_dialog_content = "我不想再被討厭了！",
  ui_story_5043_50431302_175_dialog_content = "就是啊！狗蛋才不會傷害大家呢！",
  ui_story_5043_50431302_176_dialog_content = "他比很多光靈更善良可愛！大家安心吧！",
  ui_story_5043_50431302_177_dialog_content = "嘖嘖……暗鬼都能像光靈一樣生活……",
  ui_story_5043_50431302_178_dialog_content = "時代真是變了啊。",
  ui_story_5043_50431302_179_dialog_content = "自我介紹到這裡就可以了，證人。",
  ui_story_5043_50431302_180_dialog_content = "你來到法庭上，是想為什麼事情作證呢？",
  ui_story_5043_50431302_181_dialog_content = "我、我要檢舉一個光靈的惡行。",
  ui_story_5043_50431302_182_dialog_content = "誰？",
  ui_story_5043_50431302_183_dialog_content = "坐在最高處的那個，名字叫史瓦的傢伙！",
  ui_story_5043_50431302_184_dialog_content = "你......",
  ui_story_5043_50431302_185_dialog_content = "什麼樣的惡行？",
  ui_story_5043_50431302_186_dialog_content = "他、他是破壞雕像的元兇！",
  ui_story_5043_50431302_187_dialog_content = "他有不在場證明，你怎能如此斷定？",
  ui_story_5043_50431302_188_dialog_content = "不需要在場，因為他用來摧毀雕像的方法是……是……",
  ui_story_5043_50431302_189_dialog_content = "是什麼？",
  ui_story_5043_50431302_190_dialog_content = "是操控暗鬼！！！",
  ui_story_5043_50431401_1_dialog_content = "操控暗鬼？！",
  ui_story_5043_50431401_2_dialog_content = "天啊，你知道自己在說什麼嗎？",
  ui_story_5043_50431401_3_dialog_content = "光靈與暗鬼廝混可是滔天大罪啊！",
  ui_story_5043_50431401_4_dialog_content = "呿，可笑的指證！",
  ui_story_5043_50431401_5_dialog_content = "僅憑暗鬼的一面之詞，就想給我這個白夜城貴族扣上勾結暗鬼的帽子？！",
  ui_story_5043_50431401_6_dialog_content = "別做夢了！這種證言還不比醉漢的夢話有公信力！",
  ui_story_5043_50431401_7_dialog_content = "零恩，你誣陷人的手法太低劣了！",
  ui_story_5043_50431401_8_dialog_content = "是嗎，也許我該向你學習？",
  ui_story_5043_50431401_9_dialog_content = "你......",
  ui_story_5043_50431401_10_dialog_content = "指控你有罪並不需要誣陷。",
  ui_story_5043_50431401_11_dialog_content = "如你所言，區區一隻暗鬼的說詞，不足以將你定罪。",
  ui_story_5043_50431401_12_dialog_content = "但是，如果這隻暗鬼在事件中扮演了特殊角色呢？",
  ui_story_5043_50431401_13_dialog_content = "……特殊角色？",
  ui_story_5043_50431401_14_dialog_content = "證人，請吧。",
  ui_story_5043_50431401_15_dialog_content = "對、對不起！！！",
  ui_story_5043_50431401_16_dialog_content = "我做了錯事，我在這裡認罪！！！",
  ui_story_5043_50431401_17_dialog_content = "咦？",
  ui_story_5043_50431401_18_dialog_content = "怎麼會，狗蛋不會做錯事！",
  ui_story_5043_50431401_19_dialog_content = "搞什麼啊，一下指認別人，一下又自己認罪。",
  ui_story_5043_50431401_20_dialog_content = "想清楚再發言啊！",
  ui_story_5043_50431401_21_dialog_content = "對、對不起，其實我……",
  ui_story_5043_50431401_22_dialog_content = "其實我就是摧毀雕像的當事者！",
  ui_story_5043_50431401_23_dialog_content = "什麼？！",
  ui_story_5043_50431401_24_dialog_content = "啥？是你嗎！",
  ui_story_5043_50431401_25_dialog_content = "是你殘忍地破壞了我的「妻子」和「愛人」？！",
  ui_story_5043_50431401_26_dialog_content = "沒錯，是我幹的。",
  ui_story_5043_50431401_27_dialog_content = "你這個混蛋……！",
  ui_story_5043_50431401_28_dialog_content = "但、但是！我是被強迫的！",
  ui_story_5043_50431401_29_dialog_content = "這些事情，全都是史瓦強迫我做的！",
  ui_story_5043_50431401_30_dialog_content = "求求大家，從輕發落我啊——",
  ui_story_5043_50431401_31_dialog_content = "<size=45>什麼？！！</size>",
  ui_story_5043_50431401_32_dialog_content = "……",
  ui_story_5043_50431401_33_dialog_content = "原來真相是這樣子嗎……",
  ui_story_5043_50431401_34_dialog_content = "事、事情要從半個月前開始說起。",
  ui_story_5043_50431401_35_dialog_content = "當時我來到白夜城，準備找、找一份新工作。",
  ui_story_5043_50431401_36_dialog_content = "白夜城很大，我認錯路，不知不覺就晃到晚上。",
  ui_story_5043_50431401_37_dialog_content = "然後我……我突然在中庭遇到幾隻暗鬼。",
  ui_story_5043_50431401_38_dialog_content = "唔，最近城裡數度發現到暗鬼的蹤跡。",
  ui_story_5043_50431401_39_dialog_content = "是該整頓一下治安了。",
  ui_story_5043_50431401_40_dialog_content = "我、我沒想到會在這裡見到同族，覺得有點奇怪。",
  ui_story_5043_50431401_41_dialog_content = "我還在發愣的時候，牠們就把我當、當做迷路的同伴。",
  ui_story_5043_50431401_42_dialog_content = "那些暗鬼的態度非常強硬，拖著我加入牠們的隊伍。",
  ui_story_5043_50431401_43_dialog_content = "我不明不白地跟著牠們一路走，最終……",
  ui_story_5043_50431401_44_dialog_content = "我到達了薩拉爾莊園。",
  ui_story_5043_50431401_45_dialog_content = "噢！那不是史瓦的家嗎！",
  ui_story_5043_50431401_46_dialog_content = "是的，我在那裡看到了史瓦。",
  ui_story_5043_50431401_47_dialog_content = "以、以及，非常令我震驚的畫面。",
  ui_story_5043_50431401_48_dialog_content = "他像對待奴隸一樣，奴役著這些暗鬼。",
  ui_story_5043_50431401_49_dialog_content = "暗鬼也都對他言聽計從。",
  ui_story_5043_50431401_50_dialog_content = "我、我沒有機會脫身，只好佯裝是其中一員。",
  ui_story_5043_50431401_51_dialog_content = "然後就隨著其他暗鬼一起，被、被鎖進史瓦家的地下室。",
  ui_story_5043_50431401_52_dialog_content = "地下室？！",
  ui_story_5043_50431401_53_dialog_content = "原來是圈養暗鬼的地方，怪不得……",
  ui_story_5043_50431401_54_dialog_content = "你對那裡很熟悉？",
  ui_story_5043_50431401_55_dialog_content = "呃，雖然不太適合在法庭上明說……",
  ui_story_5043_50431401_56_dialog_content = "晚點我再單獨跟妳說！",
  ui_story_5043_50431401_57_dialog_content = "<size=45>一、派、胡、言！</size>",
  ui_story_5043_50431401_58_dialog_content = "聽這傢伙說的話有多可笑，童話故事嗎？",
  ui_story_5043_50431401_59_dialog_content = "我沒理由要在法庭上忍受這樣的誣衊！",
  ui_story_5043_50431401_60_dialog_content = "是不是誣衊很快就會見分曉。",
  ui_story_5043_50431401_61_dialog_content = "證人，後來又發生了什麼事？",
  ui_story_5043_50431401_62_dialog_content = "截至目前所言內容確實驚人，但和「連環斷頭雕像案」並沒有關聯。",
  ui_story_5043_50431401_63_dialog_content = "噢！對！說回案件！",
  ui_story_5043_50431401_64_dialog_content = "偶爾為之，史瓦會找幾個暗鬼離開地下室，去執行任務。",
  ui_story_5043_50431401_65_dialog_content = "為、為了找機會逃脫，我總是表現得非常踴躍。",
  ui_story_5043_50431401_66_dialog_content = "史瓦果然選中了我。",
  ui_story_5043_50431401_67_dialog_content = "他要求我在月亮熱氣球升起的時候，摧、摧毀下方的雕像。",
  ui_story_5043_50431401_68_dialog_content = "喔！聽起來與案件的發生規律吻合！",
  ui_story_5043_50431401_69_dialog_content = "前兩次，我、我分別在審判庭門前和草地廣場摧毀了雕像。",
  ui_story_5043_50431401_70_dialog_content = "審判庭門前？！",
  ui_story_5043_50431401_71_dialog_content = "不——我的「愛人」！！！",
  ui_story_5043_50431401_72_dialog_content = "彼瑪隆先生，節哀順變。",
  ui_story_5043_50431401_73_dialog_content = "也許是因為進展順利，第三次史瓦對我提出更多要求。",
  ui_story_5043_50431401_74_dialog_content = "他、他要求我戴著一隻奇怪的手套作案。",
  ui_story_5043_50431401_75_dialog_content = "手套出現了！！！",
  ui_story_5043_50431401_76_dialog_content = "還指示我作案完成後，要把手套留在現場。",
  ui_story_5043_50431401_77_dialog_content = "於是我、我混在其他暗鬼之中，去了千星階梯。",
  ui_story_5043_50431401_78_dialog_content = "作案途中，我的右手被零恩審判官抓住，差點被當場逮捕。",
  ui_story_5043_50431401_79_dialog_content = "還好，我、我靈機一動甩掉手套，順利逃脫的同時也把手套留在了現場。",
  ui_story_5043_50431401_80_dialog_content = "你留下的手套，是這一隻嗎？",
  ui_story_5043_50431401_81_dialog_content = "沒錯！就是它！",
  ui_story_5043_50431401_82_dialog_content = "對上了，全都對上了！",
  ui_story_5043_50431401_83_dialog_content = "看來，證人狗蛋的認罪證言與證物吻合。",
  ui_story_5043_50431401_84_dialog_content = "那麼接下來……",
  ui_story_5043_50431401_85_dialog_content = "呵，吻合？",
  ui_story_5043_50431401_86_dialog_content = "不過是順著案件紀錄編造出來的故事！",
  ui_story_5043_50431401_87_dialog_content = "你所說的內容有任何證據可以佐證嗎？",
  ui_story_5043_50431401_88_dialog_content = "史瓦審判長覺得一位甘願認罪的證人還不夠可靠嗎？",
  ui_story_5043_50431401_89_dialog_content = "哼，認罪的證人未必真是犯人！",
  ui_story_5043_50431401_90_dialog_content = "我有理由相信，是有人為了誣陷我而收買了這隻暗鬼。",
  ui_story_5043_50431401_91_dialog_content = "憑一條低賤的生命就能拉我下水，實在是一筆好買賣。",
  ui_story_5043_50431401_92_dialog_content = "什、什麼叫拉你下水！明明明明、明明是你拉我下水！",
  ui_story_5043_50431401_93_dialog_content = "我只是來白夜城打工，誰想到會因為你的陰謀被抓起來，又被迫做壞事。",
  ui_story_5043_50431401_94_dialog_content = "要不是昨天你家地下室大門莫名被人打開，我可能永遠都沒法重獲自由！",
  ui_story_5043_50431401_95_dialog_content = "唔，聽起來地下室似乎是個很重要的地方。",
  ui_story_5043_50431401_96_dialog_content = "瞧，牠還在胡言亂語！",
  ui_story_5043_50431401_97_dialog_content = "我家莊園根本沒有地下室！",
  ui_story_5043_50431401_98_dialog_content = "有沒有那種地方派人去找一下不就知道了！",
  ui_story_5043_50431401_99_dialog_content = "去我家找？這可是違法的行為！",
  ui_story_5043_50431401_100_dialog_content = "薩拉爾家族有維護自己隱私的權利！",
  ui_story_5043_50431401_101_dialog_content = "怎麼這樣……",
  ui_story_5043_50431401_102_dialog_content = "史瓦審判長說得沒錯，我們無權搜查薩拉爾莊園。",
  ui_story_5043_50431401_103_dialog_content = "……",
  ui_story_5043_50431401_104_dialog_content = "除非，你能證明自己有罪。",
  ui_story_5043_50431401_105_dialog_content = "什麼？！！",
  ui_story_5043_50431401_106_dialog_content = "嘖……",
  ui_story_5043_50431401_107_dialog_content = "史瓦審判長也想到這一點了吧？所以你剛剛才說——",
  ui_story_5043_50431401_108_dialog_content = "「認罪的證人未必真是犯人」。",
  ui_story_5043_50431401_109_dialog_content = "……",
  ui_story_5043_50431401_110_dialog_content = "你必須死咬住這一點，因為你明白這就是癥結所在。",
  ui_story_5043_50431401_111_dialog_content = "一旦他被審判庭定義為犯人，他所說的一切就必須經過認真考證。",
  ui_story_5043_50431401_112_dialog_content = "因為那不只是一段證言，而是犯人的自白。",
  ui_story_5043_50431401_113_dialog_content = "人們願意相信暗鬼擔任反派的故事，也願意相信事情背後隱藏著不為人知的黑暗。",
  ui_story_5043_50431401_114_dialog_content = "審判庭將因此拿到搜查許可，針對狗蛋敘述的內容逐一探究。",
  ui_story_5043_50431401_115_dialog_content = "到時候，關於「薩拉爾莊園有沒有地下室」的問題，所有人都會知道答案。",
  ui_story_5043_50431401_116_dialog_content = "呿，別妄想了，零恩。我知道你打的如意算盤。",
  ui_story_5043_50431401_117_dialog_content = "用一樁無關緊要的案件、一隻不起眼的暗鬼做幌子，想刺探我薩拉爾家族的隱私。",
  ui_story_5043_50431401_118_dialog_content = "你不會得逞的。",
  ui_story_5043_50431401_119_dialog_content = "喂，你的意思是我的案件無關緊要嗎？！",
  ui_story_5043_50431401_120_dialog_content = "閉嘴！",
  ui_story_5043_50431401_121_dialog_content = "你……你……",
  ui_story_5043_50431401_122_dialog_content = "今天陪你們鬧夠了！",
  ui_story_5043_50431401_123_dialog_content = "本庭審判長認定，證人席上的暗鬼與本案無關。",
  ui_story_5043_50431401_124_dialog_content = "基於目前證據不足，案件審理無法進展的情況，擬於休庭後另做詳細的調查取證。",
  ui_story_5043_50431401_125_dialog_content = "將待證據確鑿後重審案情……",
  ui_story_5043_50431401_126_dialog_content = "我、我能證明自己有罪！",
  ui_story_5043_50431401_127_dialog_content = "！！！",
  ui_story_5043_50431401_128_dialog_content = "就在這裡，在法庭之上！",
  ui_story_5043_50431401_129_dialog_content = "又想編故事來誣衊我嗎？",
  ui_story_5043_50431401_130_dialog_content = "我有證據！",
  ui_story_5043_50431401_131_dialog_content = "證人，你要出示什麼證據？",
  ui_story_5043_50431401_132_dialog_content = "就是作案現場留下的手套！",
  ui_story_5043_50431401_133_dialog_content = "……手套？",
  ui_story_5043_50431401_134_dialog_content = "我、我知道，史瓦一定清潔過手套，上面不會留下暗鬼的痕跡。",
  ui_story_5043_50431401_135_dialog_content = "但是！作案之前，我用指甲在手套內側劃了一道缺口。",
  ui_story_5043_50431401_136_dialog_content = "那是清、清潔也無法抹除的傷痕！",
  ui_story_5043_50431401_137_dialog_content = "什麼？！！",
  ui_story_5043_50431401_138_dialog_content = "原來如此，只要找到那道痕跡，就能證明你是該手套的佩戴者。",
  ui_story_5043_50431401_139_dialog_content = "那也就證明了你是本案的犯人。",
  ui_story_5043_50431401_140_dialog_content = "是的！",
  ui_story_5043_50431401_141_dialog_content = "史瓦審判長，我可以檢查一下本案的核心證物嗎？",
  ui_story_5043_50431401_142_dialog_content = "……",
  ui_story_5043_50431401_143_dialog_content = "有勞您把證物遞過來給我。",
  ui_story_5043_50431401_144_dialog_content = "既然休庭在即，就別耽誤時間了，這是最後一次檢查。",
  ui_story_5043_50431401_145_dialog_content = "……",
  ui_story_5043_50431401_146_dialog_content = "史瓦審判長？",
  ui_story_5043_50431401_147_dialog_content = "……呿。",
  ui_story_5043_50431401_148_dialog_content = "所以說，我真的<color=#FFB400>討厭戀愛</color>。",
  ui_story_5043_50431401_149_dialog_content = "什麼？！",
  ui_story_5043_50431401_150_dialog_content = "他竟然說出這種話，這意思就是……",
  ui_story_5043_50431401_151_dialog_content = "我討厭被一票普通人包圍、簇擁、愛慕著。",
  ui_story_5043_50431401_152_dialog_content = "自以為是地接近我，自以為是地探究我的私事。",
  ui_story_5043_50431401_153_dialog_content = "對，就像你們的行為。",
  ui_story_5043_50431401_154_dialog_content = "你討厭戀愛？",
  ui_story_5043_50431401_155_dialog_content = "當然討厭！簡直就像永遠醒不來的惡夢！",
  ui_story_5043_50431401_156_dialog_content = "每一天被同齡的人包圍，忍受一次次態度極盡諂媚的搭話。",
  ui_story_5043_50431401_157_dialog_content = "上課時桌面堆滿情書，節假日家裡堆滿禮物。",
  ui_story_5043_50431401_158_dialog_content = "你們知道被所有人喜歡是多麼痛苦的事情嗎！！！",
  ui_story_5043_50431401_159_dialog_content = "……",
  ui_story_5043_50431401_160_dialog_content = "……他在說什麼？",
  ui_story_5043_50431401_161_dialog_content = "我、我也不明白。",
  ui_story_5043_50431401_162_dialog_content = "本以為開始工作後，狀況會好一點。",
  ui_story_5043_50431401_163_dialog_content = "沒想到，白夜城內竟然掀起了令人作嘔的戀愛風潮！",
  ui_story_5043_50431401_164_dialog_content = "甚至還、還要我擔任什麼「戀愛法庭」的審判長！",
  ui_story_5043_50431401_165_dialog_content = "是的，我受夠了，於是我想辦法毀壞那幾尊雕像！",
  ui_story_5043_50431401_166_dialog_content = "我知道膚淺的活動主辦者想藉雕像的文化韻味為活動鑲金，但我絕不允許！",
  ui_story_5043_50431401_167_dialog_content = "你……",
  ui_story_5043_50431401_168_dialog_content = "用粗濫的暴力來表達主張，你才膚淺吧！",
  ui_story_5043_50431401_169_dialog_content = "所以你就派暗鬼去摧毀它們？",
  ui_story_5043_50431401_170_dialog_content = "對，我派了暗鬼。牠們的骯髒正適合這場戀愛風潮。",
  ui_story_5043_50431401_171_dialog_content = "我可以將你剛才所說的一切視為認罪的發言吧？",
  ui_story_5043_50431401_172_dialog_content = "別高捧著那套假惺惺的繁文縟節了，零恩。",
  ui_story_5043_50431401_173_dialog_content = "你贏了這場審判，你已經拿到充足的證據。",
  ui_story_5043_50431401_174_dialog_content = "我唯一做錯的事情就是忘了銷毀「工具」，留下了一張亂說話的嘴巴。",
  ui_story_5043_50431401_175_dialog_content = "……",
  ui_story_5043_50431401_176_dialog_content = "不，你輸掉的原因其實沒那麼複雜。",
  ui_story_5043_50431401_177_dialog_content = "如果要說唯一做錯的事情，應該是你沒讓我檢查手套。",
  ui_story_5043_50431401_178_dialog_content = "<size=45>什麼？！！</size>",
  ui_story_5043_50431401_179_dialog_content = "慢著！手套裡不是有我們制勝的關鍵證據嗎？！",
  ui_story_5043_50431401_180_dialog_content = "難道說……那個證據根本不存在？",
  ui_story_5043_50431401_181_dialog_content = "呼，我都快緊張死了。幸好一切順利。",
  ui_story_5043_50431401_182_dialog_content = "零恩，你這傢伙還真有誆人的天賦。",
  ui_story_5043_50431401_183_dialog_content = "你們騙我？！",
  ui_story_5043_50431401_184_dialog_content = "這、這隻暗鬼根本沒在手套裡留下痕跡！",
  ui_story_5043_50431401_185_dialog_content = "呵呵，不只是這樣哦。",
  ui_story_5043_50431401_186_dialog_content = "你都不覺得事情太巧了嗎？",
  ui_story_5043_50431401_187_dialog_content = "從你家逃出的唯一一隻暗鬼，這麼剛好是被你派去破壞雕像的那隻。",
  ui_story_5043_50431401_188_dialog_content = "難道你……",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>昨天</color>",
  ui_story_5043_50431401_190_dialog_content = "你也準備加班？",
  ui_story_5043_50431401_191_dialog_content = "案件還沒調查清楚，在開庭前仔細檢查資料是我的份內事。",
  ui_story_5043_50431401_192_dialog_content = "倒是沒料到你也打算加班。",
  ui_story_5043_50431401_193_dialog_content = "嘖，庶民新人，你是質疑我的專業態度還是質疑我跟蒂娜的友情？",
  ui_story_5043_50431401_194_dialog_content = "算了，今天先不跟你計較，專心看案件資料吧……",
  ui_story_5043_50431401_195_dialog_content = "打、打擾一下！請問審判庭還開著嗎？",
  ui_story_5043_50431401_196_dialog_content = "咦？一隻暗鬼？",
  ui_story_5043_50431401_197_dialog_content = "好啊，竟然連審判庭都敢來！看我打死你！",
  ui_story_5043_50431401_198_dialog_content = "別打別打！！！我、我是來報案的！",
  ui_story_5043_50431401_199_dialog_content = "啥？暗鬼報案？",
  ui_story_5043_50431401_200_dialog_content = "聽牠說說吧。反正就是一隻暗鬼，想消滅牠輕而易舉。",
  ui_story_5043_50431401_201_dialog_content = "好，那就聽你說說看吧。你要報什麼案？",
  ui_story_5043_50431401_202_dialog_content = "嗯！",
  ui_story_5043_50431401_203_dialog_content = "我、我先，我先自我介紹一下……",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>十分鐘後</color>",
  ui_story_5043_50431401_205_dialog_content = "……然後就隨著其他暗鬼一起，被、被鎖進史瓦家的地下室。",
  ui_story_5043_50431401_206_dialog_content = "竟然還有這種事？怪不得我們會在地下室遇到暗鬼。",
  ui_story_5043_50431401_207_dialog_content = "嗯！我就是跟、跟著牠們逃出來的！",
  ui_story_5043_50431401_208_dialog_content = "咦！！！",
  ui_story_5043_50431401_209_dialog_content = "這樣說來，是我們救了你啊！",
  ui_story_5043_50431401_210_dialog_content = "真、真的嗎！太感謝了！！！",
  ui_story_5043_50431401_211_dialog_content = "所以你想檢舉史瓦拘禁暗鬼？",
  ui_story_5043_50431401_212_dialog_content = "是的！雖、雖然白夜城的法律不可能保護暗鬼，但我相信他還有更大的陰謀！",
  ui_story_5043_50431401_213_dialog_content = "這個好辦。你明天到法庭來，把剛才那些話重複一遍。",
  ui_story_5043_50431401_214_dialog_content = "讓大家明白，史瓦這混蛋私底下幹了些什麼勾當！",
  ui_story_5043_50431401_215_dialog_content = "嗯！沒問題！",
  ui_story_5043_50431401_216_dialog_content = "有證據嗎？",
  ui_story_5043_50431401_217_dialog_content = "證、證據？",
  ui_story_5043_50431401_218_dialog_content = "別忘了，你是一隻暗鬼。",
  ui_story_5043_50431401_219_dialog_content = "我們去過史瓦家地下室，所以會相信你說的話，但其他人呢？",
  ui_story_5043_50431401_220_dialog_content = "要是拿不出證據，只要史瓦一口咬定此事不存在，我們就莫可奈何。",
  ui_story_5043_50431401_221_dialog_content = "甚至於，事後還會遭到他的報復。",
  ui_story_5043_50431401_222_dialog_content = "這是個危險的嘗試。",
  ui_story_5043_50431401_223_dialog_content = "對、對不起，我沒有證據……",
  ui_story_5043_50431401_224_dialog_content = "我、我能逃出來就已經，拼、拼盡全力了……",
  ui_story_5043_50431401_225_dialog_content = "欸，這麼大的事情，可不能因為沒證據就不了了之啊！",
  ui_story_5043_50431401_226_dialog_content = "若是別無他法，我們可以再次潛入薩拉爾莊園？",
  ui_story_5043_50431401_227_dialog_content = "等一下，似乎不用那麼麻煩。我想到了一個計策……",
  ui_story_5043_50431401_228_dialog_content = "該怎麼做？",
  ui_story_5043_50431401_229_dialog_content = "既然找不到證據，我們就讓他自己在法庭上承認罪行。",
  ui_story_5043_50431401_230_dialog_content = "啥？你在做夢嗎？",
  ui_story_5043_50431401_231_dialog_content = "沒有證據，用什麼逼他承認？",
  ui_story_5043_50431401_232_dialog_content = "你猜猜他圈養暗鬼有何用途？",
  ui_story_5043_50431401_233_dialog_content = "嗯……風險這麼大的舉動肯定伴隨著巨大的陰謀吧？",
  ui_story_5043_50431401_234_dialog_content = "我猜是他命令暗鬼摧毀幾尊雕像。",
  ui_story_5043_50431401_235_dialog_content = "哦？此話怎講？",
  ui_story_5043_50431401_236_dialog_content = "還記得千星階梯那一次嗎，我一度抓到犯人的手。",
  ui_story_5043_50431401_237_dialog_content = "但是等你們消滅完暗鬼，附近一個人影都沒有。",
  ui_story_5043_50431401_238_dialog_content = "千星階梯頂層相當開闊，照理說犯人不可能在那麼短的時間內徹底脫離我們的視線。",
  ui_story_5043_50431401_239_dialog_content = "除非，犯人本身就是暗鬼。",
  ui_story_5043_50431401_240_dialog_content = "哦我懂了！消滅現場那群暗鬼的同時，也一併消滅了犯人的暗鬼！",
  ui_story_5043_50431401_241_dialog_content = "這就是我們找不到犯人的原因！",
  ui_story_5043_50431401_242_dialog_content = "嗯，這是最接近真相的可能性。",
  ui_story_5043_50431401_243_dialog_content = "你準備怎麼利用這個情報？",
  ui_story_5043_50431401_244_dialog_content = "我們先把狗蛋包裝成那個犯人。",
  ui_story_5043_50431401_245_dialog_content = "然後，借牠之口說出所有我們對案件真相的想像。",
  ui_story_5043_50431401_246_dialog_content = "只要我們猜得夠接近真相，史瓦就會相信狗蛋是他派去的那隻暗鬼。",
  ui_story_5043_50431401_247_dialog_content = "原來如此！讓他相信我們掌握關鍵人證，然後氣急敗壞地在法庭上認罪，對嗎！",
  ui_story_5043_50431401_248_dialog_content = "是的，這是一場心理博弈。",
  ui_story_5043_50431401_249_dialog_content = "狗蛋，你願意為此在法庭上說謊嗎？",
  ui_story_5043_50431401_250_dialog_content = "只、只要能揭露史瓦的惡行，我願意！",
  ui_story_5043_50431401_251_dialog_content = "好，那你得在今晚背下我教你的說詞。",
  ui_story_5043_50431401_252_dialog_content = "為了確保計策順利，我們還得一起腦力激盪。",
  ui_story_5043_50431401_253_dialog_content = "編造一個足以讓他信以為真，一錘定音的證據。",
  ui_story_5043_50431401_254_dialog_content = "你們……你們這些卑鄙之徒！",
  ui_story_5043_50431401_255_dialog_content = "不過是以其人之道還治其人之身。",
  ui_story_5043_50431401_256_dialog_content = "真沒想到啊，最後的犯人竟然是審判長！",
  ui_story_5043_50431401_257_dialog_content = "太黑暗了，審判庭太黑暗了！",
  ui_story_5043_50431401_258_dialog_content = "即便如此，法庭不也依舊展現了真相嗎？",
  ui_story_5043_50431401_259_dialog_content = "有黑暗存在，才需要刺破黑暗的力量！",
  ui_story_5043_50431401_260_dialog_content = "該結束了。史瓦審判長，最後的時刻，就讓自己體面一點吧。",
  ui_story_5043_50431401_261_dialog_content = "哼，最後時刻？",
  ui_story_5043_50431401_262_dialog_content = "零恩，你也有唯一一件做錯的事情。你知道是什麼嗎？",
  ui_story_5043_50431401_263_dialog_content = "……我？",
  ui_story_5043_50431401_264_dialog_content = "你誤以為找到真相就能終結一切。",
  ui_story_5043_50431401_265_dialog_content = "本庭審判長宣布！零恩、蒂娜、馬太幾位審判官係為本案之犯人！",
  ui_story_5043_50431401_266_dialog_content = "同案人等，在落槌後全數依法捉拿！",
  ui_story_5043_50431401_267_dialog_content = "史瓦，你在說什麼瘋話！",
  ui_story_5043_50431401_268_dialog_content = "所有人都聽到了，你才是真正的犯人！",
  ui_story_5043_50431401_269_dialog_content = "哎呀，看來本案之判決尚存在意見分歧。",
  ui_story_5043_50431401_270_dialog_content = "那就由合議庭投票裁決吧。",
  ui_story_5043_50431401_271_dialog_content = "合議庭？！",
  ui_story_5043_50431401_272_dialog_content = "等一下，那是……！",
  ui_story_5043_50431401_273_dialog_content = "暗鬼？！什麼時候冒出來的！",
  ui_story_5043_50431401_274_dialog_content = "零恩，說出你的結論吧。",
  ui_story_5043_50431401_275_dialog_content = "……史瓦‧薩拉爾是本案的犯人。",
  ui_story_5043_50431401_276_dialog_content = "好，同意此結論者請舉手。",
  ui_story_5043_50431401_277_dialog_content = "我來數一數……零恩、馬太、蒂娜、初階法官。",
  ui_story_5043_50431401_278_dialog_content = "好，四票，看來有不少人相信你的說詞。",
  ui_story_5043_50431401_279_dialog_content = "因為這就是真相！",
  ui_story_5043_50431401_280_dialog_content = "但是我認為，零恩、蒂娜、馬太幾位審判官才是本案真正的犯人。",
  ui_story_5043_50431401_281_dialog_content = "同意我結論的合議庭成員們，請敲響桌子。",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>砰——</color>",
  ui_story_5043_50431401_286_dialog_content = "他們……",
  ui_story_5043_50431401_287_dialog_content = "四票。",
  ui_story_5043_50431401_288_dialog_content = "加上我本人，史瓦‧薩拉爾的投票，一共五票。",
  ui_story_5043_50431401_289_dialog_content = "看來是我的裁決比較受人信賴。",
  ui_story_5043_50431401_290_dialog_content = "你……你把陪審團全換成了自己的人！",
  ui_story_5043_50431401_291_dialog_content = "自己的人？我看面具底下藏的都是暗鬼吧！",
  ui_story_5043_50431401_292_dialog_content = "投票結束！根據投票結果，本庭做出最終裁決！",
  ui_story_5043_50431401_293_dialog_content = "零恩、馬太、蒂娜三人——",
  ui_story_5043_50431401_294_dialog_content = "有罪！",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>梆——</color>",
  ui_story_5043_50431401_296_dialog_content = "那些陪審團成員有問題！",
  ui_story_5043_50431401_X296_dialog_content = "好強烈的暗能！他們真的是暗鬼啊！！！",
  ui_story_5043_50431401_X297_dialog_content = "你、你說什麼？！！",
  ui_story_5043_50431401_X298_dialog_content = "不會吧，難道跟我坐在一起的都是暗鬼嗎？！",
  ui_story_5043_50431401_297_dialog_content = "陪審團，辛苦你們幫我這個忙。",
  ui_story_5043_50431401_298_dialog_content = "不只作為聽眾，也作為我的「騎士」實踐律法。",
  ui_story_5043_50431401_299_dialog_content = "法庭有權行使其審判結果——",
  ui_story_5043_50431401_300_dialog_content = "將犯人抓捕歸案！",
  ui_story_5043_50431401_301_dialog_content = "嘎……",
  ui_story_5043_50431401_302_dialog_content = "糟了，那些戴著面具的奇怪傢伙好像不是普通的暗鬼！",
  ui_story_5043_50431401_303_dialog_content = "嗯，既然是史瓦的底牌，肯定不好對付。",
  ui_story_5043_50431401_304_dialog_content = "你這傢伙！講不過人家就直接動手嗎！",
  ui_story_5043_50431401_305_dialog_content = "不妙，審判庭的地形對牠們有利，這樣下去我們會被包圍。",
  ui_story_5043_50431401_306_dialog_content = "明明我們才是對的，怎能在法庭上任由黑暗蓋過正義……",
  ui_story_5043_50431401_307_dialog_content = "死腦筋！打贏了才叫正義！打不贏只能當「受害者」！",
  ui_story_5043_50431401_308_dialog_content = "先逃出去吧！",
  ui_story_5043_50431401_309_dialog_content = "就是說啊！別發呆了！",
  ui_story_5043_50431401_310_dialog_content = "快，來我們這邊！",
  ui_story_5043_50431402_1_dialog_content = "人們將愛情真諦高高懸掛在天上～♪",
  ui_story_5043_50431402_2_dialog_content = "包上精美外衣供千萬人一同欣賞～♪",
  ui_story_5043_50431402_3_dialog_content = "大家想像著愛情比所見的更美麗幾分～♪",
  ui_story_5043_50431402_4_dialog_content = "為了見它綻放而迫不得已髒了衣裳～♪",
  ui_story_5043_50431402_5_dialog_content = "聽說今天月亮熱氣球會炸開，是真的嗎？",
  ui_story_5043_50431402_6_dialog_content = "當然！大家就是為了看這場表演而來。",
  ui_story_5043_50431402_7_dialog_content = "聽說熱氣球裡滿是鮮花、摺紙和七彩泡沫。",
  ui_story_5043_50431402_8_dialog_content = "讚美愛情，肯定比禮花好看許多吧！",
  ui_story_5043_50431402_9_dialog_content = "咦？有一群人從審判庭門口跑出來。",
  ui_story_5043_50431402_10_dialog_content = "他們在做什麼呢？",
  ui_story_5043_50431402_11_dialog_content = "呼，總算是逃出來了。",
  ui_story_5043_50431402_12_dialog_content = "別大意，牠們還在後面追呢！",
  ui_story_5043_50431402_13_dialog_content = "……",
  ui_story_5043_50431402_14_dialog_content = "怎麼這麼死纏爛打啊！",
  ui_story_5043_50431402_15_dialog_content = "不會非要我們逃到影鎮才罷休吧。",
  ui_story_5043_50431402_16_dialog_content = "等等，好像有遊行的隊伍正往這頭走！",
  ui_story_5043_50431402_17_dialog_content = "偏偏在這種時候……",
  ui_story_5043_50431402_18_dialog_content = "我們不能再逃下去，否則會引暗鬼傷到一般民眾。",
  ui_story_5043_50431402_19_dialog_content = "嗯，必須在這裡攔截牠們。",
  ui_story_5043_50431402_20_dialog_content = "PlayerName，麻煩你疏散參加遊行的人吧。",
  ui_story_5043_50431402_21_dialog_content = "嗯，我馬上去……",
  ui_story_5043_50431402_22_dialog_content = "他們是來看表演的，一場前所未有的表演。",
  ui_story_5043_50431402_23_dialog_content = "你們忍心讓參加這場戀愛風潮的人們敗興而歸嗎？",
  ui_story_5043_50431402_24_dialog_content = "你這傢伙，就只知道說風涼話！",
  ui_story_5043_50431402_25_dialog_content = "不，我是真的很希望表演能順利進行。",
  ui_story_5043_50431402_26_dialog_content = "這場荒誕的新風氣也該迎來滑稽的高潮。",
  ui_story_5043_50431402_27_dialog_content = "<size=45>民眾們！向這邊靠過來！</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>表演要開始了！</size>",
  ui_story_5043_50431402_29_dialog_content = "……史瓦，你到底想做什麼？",
  ui_story_5043_50431402_30_dialog_content = "糟了！他一定是想破壞我們的活動！",
  ui_story_5043_50431402_31_dialog_content = "人潮湧過來了！別讓他們靠近暗鬼！",
  ui_story_5043_50431402_32_dialog_content = "好！我去保護他們！",
  ui_story_5043_50431402_33_dialog_content = "別太緊張，只是一場表演而已。",
  ui_story_5043_50431402_34_dialog_content = "不是說月亮熱氣球會在今天炸開嗎？",
  ui_story_5043_50431402_35_dialog_content = "那就讓大家看看，你們仰望的愛情裡面究竟藏了些什麼。",
  ui_story_5043_50431402_36_dialog_content = "難道你……",
  ui_story_5043_50431402_37_dialog_content = "荒誕的信仰是時候開花了。",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>砰——！！！</color>",
  ui_story_5043_50431402_39_dialog_content = "呃啊啊啊啊啊啊啊啊啊啊！！！",
  ui_story_5043_50431402_40_dialog_content = "大家小心！！！",
  ui_story_5043_50431402_41_dialog_content = "喂，天上飄下來的這些是……",
  ui_story_5043_50431402_42_dialog_content = "怎麼會，來自古老節日的饋贈——我的四葉草花束，怎麼……",
  ui_story_5043_50431402_43_dialog_content = "這是枯萎的花嗎？",
  ui_story_5043_50431402_44_dialog_content = "嗯，而且是像徵愛情的紅花四葉草……",
  ui_story_5043_50431402_45_dialog_content = "滿天都是枯萎的花……",
  ui_story_5043_50431402_46_dialog_content = "好醜啊，看到這種東西讓心情都變糟了。",
  ui_story_5043_50431402_47_dialog_content = "月亮熱氣球炸開後就是這種景象嗎？",
  ui_story_5043_50431402_48_dialog_content = "對，就是這種景象。",
  ui_story_5043_50431402_49_dialog_content = "史瓦，你別過來！",
  ui_story_5043_50431402_50_dialog_content = "戀愛說到底不就是這樣嗎？",
  ui_story_5043_50431402_51_dialog_content = "當你看不到內容物，就會把一切想像成最美好的樣子。",
  ui_story_5043_50431402_52_dialog_content = "是天上的月亮，是大家搆不著、猜不透，最神祕而美麗的東西。",
  ui_story_5043_50431402_53_dialog_content = "對，所有美好都源自於未知，源自於沒人知道裡面包含了什麼。",
  ui_story_5043_50431402_54_dialog_content = "好了，現在所有人都親眼看到了。",
  ui_story_5043_50431402_55_dialog_content = "戀愛不過就是這麼一回事。",
  ui_story_5043_50431402_56_dialog_content = "一場荒誕的騷動過後，留下滿地狼藉。",
  ui_story_5043_50431402_57_dialog_content = "然後，從此天上再也看不到月亮。",
  ui_story_5043_50431402_58_dialog_content = "是啊，以後再也看不到月亮熱氣球了。",
  ui_story_5043_50431402_59_dialog_content = "看不到也好，裝滿了枯萎花束的它不過是個垃圾袋而已啊……",
  ui_story_5043_50431402_60_dialog_content = "你、你這是詭辯！一定是你替換了熱氣球內的東西！",
  ui_story_5043_50431402_61_dialog_content = "我沒有動熱氣球裡的東西，只破壞了附加在上面的那層光能術。",
  ui_story_5043_50431402_62_dialog_content = "你……！",
  ui_story_5043_50431402_63_dialog_content = "怎麼了？是妳用光能術維持花朵的鮮豔，欺騙大眾在先吧。",
  ui_story_5043_50431402_64_dialog_content = "而我所做的僅是展現真相。",
  ui_story_5043_50431402_65_dialog_content = "大眾能看到美，是因為有人獨自承受了醜。",
  ui_story_5043_50431402_66_dialog_content = "就像那些追求我的小百合們嚐盡戀愛的甜美，因為有我為她們的一廂情願飽受煎熬。",
  ui_story_5043_50431402_67_dialog_content = "愛情的真相是這樣子嗎……",
  ui_story_5043_50431402_68_dialog_content = "過於沉重的愛，反而會給別人帶來負擔……",
  ui_story_5043_50431402_69_dialog_content = "是的，妳該學會這一課了。",
  ui_story_5043_50431402_70_dialog_content = "……",
  ui_story_5043_50431402_71_dialog_content = "（我會不會……也犯了這樣的錯誤呢……）",
  ui_story_5043_50431402_72_dialog_content = "不是的蒂娜！別被史瓦的漂亮話給唬住了！",
  ui_story_5043_50431402_73_dialog_content = "欸？",
  ui_story_5043_50431402_74_dialog_content = "他口中的真相憑什麼涵蓋別人的戀愛？",
  ui_story_5043_50431402_75_dialog_content = "同樣一件事情，每個人感受到的情緒都不一樣。",
  ui_story_5043_50431402_76_dialog_content = "我不知道戀愛的真相是什麼，但我能感受到每一次活動大家都很開心，這就夠了！",
  ui_story_5043_50431402_77_dialog_content = "而且說到底，他根本沒談過戀愛吧！",
  ui_story_5043_50431402_78_dialog_content = "有什麼資格在這裡對戀愛高談闊論！",
  ui_story_5043_50431402_79_dialog_content = "你……",
  ui_story_5043_50431402_80_dialog_content = "戀愛那麼骯髒的東西，我怎麼可能去接觸！",
  ui_story_5043_50431402_81_dialog_content = "對！PlayerName說得沒錯！",
  ui_story_5043_50431402_82_dialog_content = "根本就沒有什麼真相，你只是在放大最差的結果！",
  ui_story_5043_50431402_83_dialog_content = "況且，過程中的美好想像就不叫戀愛嗎？",
  ui_story_5043_50431402_84_dialog_content = "戀愛不是法庭上的裁決，怎能用結果囊括一切！",
  ui_story_5043_50431402_85_dialog_content = "無論暗戀、告白、共處還是離別，每一次的情感碰撞都是戀愛的一部分！",
  ui_story_5043_50431402_86_dialog_content = "史瓦！你根本不明白什麼是戀愛！",
  ui_story_5043_50431402_87_dialog_content = "呵，也許確實如你所說，我真的不明白戀愛。",
  ui_story_5043_50431402_88_dialog_content = "我不明白戀愛有何值得你們追求。",
  ui_story_5043_50431402_89_dialog_content = "對我來說那就是煩人的蝨子，擾亂我的寧靜，給了其他人涉足我生活的理由。",
  ui_story_5043_50431402_90_dialog_content = "不，不只是生活，最可惡的是還影響了我的事業，影響了白夜城的公正！",
  ui_story_5043_50431402_91_dialog_content = "為什麼這樣說？",
  ui_story_5043_50431402_92_dialog_content = "為了這麼一點無足輕重的感情，周遭這些人一個又一個拋棄了理性。",
  ui_story_5043_50431402_93_dialog_content = "甚至於變本加厲，創建出「戀愛法庭」這種數典忘祖的玩意兒！",
  ui_story_5043_50431402_94_dialog_content = "想想愛情做了什麼？它成為罪犯脫罪的理由，成為無辜者身上莫須有的罪名。",
  ui_story_5043_50431402_95_dialog_content = "它褻瀆了白夜城累積百年才建立起的法度！",
  ui_story_5043_50431402_96_dialog_content = "所以，我要對抗它，在法庭上對抗這股邪惡的風潮。",
  ui_story_5043_50431402_97_dialog_content = "我做這一切，都是為了建立一個摒除所有愛情因素的法庭。",
  ui_story_5043_50431402_98_dialog_content = "我需要與我想法一致的陪審團，他們的意志不能受到任何情感的荼毒。",
  ui_story_5043_50431402_99_dialog_content = "這些醜陋的怪物正好能滿足我的需求。",
  ui_story_5043_50431402_100_dialog_content = "……",
  ui_story_5043_50431402_101_dialog_content = "原來他是這麼想的……",
  ui_story_5043_50431402_102_dialog_content = "極度偏執卻又自圓其說。",
  ui_story_5043_50431402_103_dialog_content = "這種人比追名逐利的罪犯更加可怕。",
  ui_story_5043_50431402_104_dialog_content = "好了，關於愛情的無聊討論到此為止。",
  ui_story_5043_50431402_105_dialog_content = "我希望各位能像我一樣，把注意力放在案件、放在判決上。",
  ui_story_5043_50431402_106_dialog_content = "別忘了，你們幾個全部<color=#FFB400>有罪</color>！",
  ui_story_5043_50431402_107_dialog_content = "喂，你們看那邊！！",
  ui_story_5043_50431402_108_dialog_content = "有暗鬼從審判庭裡衝出來了！",
  ui_story_5043_50431402_109_dialog_content = "哎呀，今天真是糟透了！快跑吧！！！",
  ui_story_5043_50431402_110_dialog_content = "不妙，史瓦這傢伙又要動手了。",
  ui_story_5043_50431402_111_dialog_content = "他已經瘋了，在大庭廣眾之下招來暗鬼，衛兵很快就會捉拿他。",
  ui_story_5043_50431402_112_dialog_content = "不過我們還是得控制局面，避免無辜民眾受傷。",
  ui_story_5043_50431402_113_dialog_content = "話是這麼說，但那幾個戴著石膏面具的暗鬼還挺難搞……",
  ui_story_5043_50431402_114_dialog_content = "讓我來會會牠們吧。",
  ui_story_5043_50431402_115_dialog_content = "賭上坎貝爾家族的名譽——",
  ui_story_5043_50431402_116_dialog_content = "賭上「神之手」的力量！",
  ui_story_5043_50431402_117_dialog_content = "哇，好強大的光能！",
  ui_story_5043_50431402_118_dialog_content = "有這股力量說不定真的可以……",
  ui_story_5043_50431402_119_dialog_content = "呼啊——",
  ui_story_5043_50431402_120_dialog_content = "咦？！！怎麼打哈欠了！",
  ui_story_5043_50431402_121_dialog_content = "不行……今天已經……清醒太……太久了……",
  ui_story_5043_50431402_122_dialog_content = "哼。四騎士，拿下他們。",
  ui_story_5043_50431402_123_dialog_content = "等到這種時候才出手嗎！太卑鄙了！",
  ui_story_5043_50431402_124_dialog_content = "蒂娜！打起精神啊！",
  ui_story_5043_50431402_125_dialog_content = "嗯……看我用神之手把牠們……",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50431402_127_dialog_content = "還沒開打就睡著啦！！！",
  ui_story_5043_50431402_128_dialog_content = "怎麼辦！讓她睡在戰場上太危險了！",
  ui_story_5043_50431402_129_dialog_content = "蒂娜，妳快醒醒，敵人要來了。",
  ui_story_5043_50431402_130_dialog_content = "星星……零恩頭上……有星星……",
  ui_story_5043_50431402_131_dialog_content = "別找星星了！妳還要戰鬥呢！",
  ui_story_5043_50431402_132_dialog_content = "不行……不行了……",
  ui_story_5043_50431402_133_dialog_content = "來，張嘴，把它嚥下去。",
  ui_story_5043_50431402_134_dialog_content = "什麼時候了還餵她吃東西啊！那是巧克力嗎？",
  ui_story_5043_50431402_135_dialog_content = "我已經……已經……",
  ui_story_5043_50431402_136_dialog_content = "怎麼辦……敵人已經逼近眼前了……",
  ui_story_5043_50431402_137_dialog_content = "徹底清醒過來了！",
  ui_story_5043_50431402_138_dialog_content = "啥？！",
  ui_story_5043_50431402_139_dialog_content = "反差也太大了吧！",
  ui_story_5043_50431402_140_dialog_content = "哼，只知道直球進攻啊，光靠這樣可追求不到想要的感情哦！",
  ui_story_5043_50431402_141_dialog_content = "讓我來教你該怎麼做吧！",
  ui_story_5043_50431402_142_dialog_content = "咦？不然該怎麼做？",
  ui_story_5043_50431402_143_dialog_content = "忘記了嗎，這些是大家過去教我的啊。",
  ui_story_5043_50431402_144_dialog_content = "追求對方有很多種方法，當然也包括最直接的——<color=#FFB400>主動告白</color>！",
  ui_story_5043_50431402_145_dialog_content = "零恩！你說得沒錯，關鍵是主動將對方的注意力吸引過來！",
  ui_story_5043_50431402_X145_dialog_content = "把怪物引到遠離人群的地方！",
  ui_story_5043_50431402_146_dialog_content = "什麼……？",
  ui_story_5043_50431402_147_dialog_content = "你們這幾個戴著雕像頭套的傢伙，看招！",
  ui_story_5043_50431402_148_dialog_content = "嘎……",
  ui_story_5043_50431402_149_dialog_content = "希望你們中意「神之手」的問候～",
  ui_story_5043_50431402_X149_dialog_content = "嘎！！！",
  ui_story_5043_50431402_X150_dialog_content = "這點程度可傷不了我的騎士，繼續進攻！",
  ui_story_5043_50431402_150_dialog_content = "接下來的是馬太閣下教我的。馬太閣下，還記得嗎？",
  ui_story_5043_50431402_151_dialog_content = "庶民新人，光是主動還不夠，還要學會——<color=#FFB400>隱藏自己</color>！",
  ui_story_5043_50431402_152_dialog_content = "當然記得～！我會掩護妳！",
  ui_story_5043_50431402_153_dialog_content = "快，我們躲到牆後面去！",
  ui_story_5043_50431402_154_dialog_content = "哼，才受到一點挫折就放棄，你們的愛情果然脆弱得要命啊。",
  ui_story_5043_50431402_155_dialog_content = "剛剛不是還想保護人群嗎？",
  ui_story_5043_50431402_156_dialog_content = "嘎……",
  ui_story_5043_50431402_157_dialog_content = "嘎？",
  ui_story_5043_50431402_158_dialog_content = "我就知道！牠們找不到我們！",
  ui_story_5043_50431402_159_dialog_content = "仔細一瞧，牠們頭上的面具會不會正是弱點所在？",
  ui_story_5043_50431402_160_dialog_content = "說得對，真想看看這幾個傢伙面具下長什麼樣子！",
  ui_story_5043_50431402_161_dialog_content = "這時候就要用到第三種方法了！",
  ui_story_5043_50431402_162_dialog_content = "在前進與後退間尋求平衡——<color=#FFB400>學會試探</color>！",
  ui_story_5043_50431402_163_dialog_content = "邁出最後一步前，摸清對方內心的深淺也很關鍵！",
  ui_story_5043_50431402_X163_dialog_content = "只要找到對方的弱點，就能一擊必勝！",
  ui_story_5043_50431402_164_dialog_content = "我們試著往雕像面具進攻吧。",
  ui_story_5043_50431402_165_dialog_content = "明白，那就立刻動手吧！",
  ui_story_5043_50431402_166_dialog_content = "嘎——！！！",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>砰、砰——砰！！！</color>",
  ui_story_5043_50431402_168_dialog_content = "嘶，痛、痛……痛……",
  ui_story_5043_50431402_169_dialog_content = "想揭開面具好像沒那麼容易啊。",
  ui_story_5043_50431402_170_dialog_content = "哈哈哈哈哈，你們愚蠢的樣子實在逗笑了我。",
  ui_story_5043_50431402_171_dialog_content = "憑這樣的攻擊就妄想傷及我的騎士？",
  ui_story_5043_50431402_172_dialog_content = "哼，經歷過這麼多波折，現在才是情感的最高潮！",
  ui_story_5043_50431402_173_dialog_content = "這時候再談技巧已經沒有意義，所需的只有——",
  ui_story_5043_50431402_174_dialog_content = "就是現在！蒂娜！",
  ui_story_5043_50431402_175_dialog_content = "拿出你的真心吧！！！",
  ui_story_5043_50431402_176_dialog_content = "對！拿出真心！全心全意！",
  ui_story_5043_50431402_177_dialog_content = "接下我熱誠的一擊吧！",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>神聖光輝</color>！</size>",
  ui_story_5043_50431402_179_dialog_content = "呼，成功了嗎？",
  ui_story_5043_50431402_180_dialog_content = "戴面具的暗鬼好像被消滅了！",
  ui_story_5043_50431402_181_dialog_content = "不……怎麼可能……我的騎士……",
  ui_story_5043_50431402_182_dialog_content = "繼續戰鬥啊！我的騎士！",
  ui_story_5043_50431402_183_dialog_content = "法庭的判決還沒得到執行，你們不能倒下！！！",
  ui_story_5043_50431402_184_dialog_content = "已經結束囉。",
  ui_story_5043_50431402_185_dialog_content = "你與牠們沒有情感，只有強迫和奴役。",
  ui_story_5043_50431402_186_dialog_content = "在我們展現的真心之下，那點脆弱的聯繫自然會應聲破碎。",
  ui_story_5043_50431402_187_dialog_content = "都這種時候了妳還在胡扯！",
  ui_story_5043_50431402_188_dialog_content = "至於你說的「法庭判決還沒得到執行」就更不用擔心了。",
  ui_story_5043_50431402_189_dialog_content = "事情鬧成這樣，審判庭勢必會重審此案。",
  ui_story_5043_50431402_190_dialog_content = "我想屆時會由伊淪汀大人坐在審判長的位置。",
  ui_story_5043_50431402_191_dialog_content = "相信她會給你一個滿意的結果。",
  ui_story_5043_50431402_192_dialog_content = "……審判我？不，不行，不可能！",
  ui_story_5043_50431402_193_dialog_content = "沒有人能審判我！我是無罪的！",
  ui_story_5043_50431402_194_dialog_content = "是否無罪由不得你定義。",
  ui_story_5043_50431402_195_dialog_content = "當然由我定義！我可是審判長！",
  ui_story_5043_50431402_196_dialog_content = "這個身分恐怕也由不得你定義了。",
  ui_story_5043_50431402_197_dialog_content = "爛了！這座城市的法度已經爛透了！",
  ui_story_5043_50431402_198_dialog_content = "讓開，我要去找我父親！",
  ui_story_5043_50431402_199_dialog_content = "薩拉爾家族會為整件事主持公道！",
  ui_story_5043_50431402_200_dialog_content = "真狼狽啊，史瓦。闖了禍就想靠家世收拾嗎？",
  ui_story_5043_50431402_201_dialog_content = "真是丟臉。",
  ui_story_5043_50431402_202_dialog_content = "讓開！！！",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>啪！</color>",
  ui_story_5043_50431402_204_dialog_content = "哎唷！",
  ui_story_5043_50431402_205_dialog_content = "誰？誰打我？！",
  ui_story_5043_50431402_206_dialog_content = "只要你乖乖跟我們回審判庭解決問題，就沒人會打你。",
  ui_story_5043_50431402_207_dialog_content = "零恩！是你這傢伙！",
  ui_story_5043_50431402_208_dialog_content = "庶民出生的賤種，你明白自己在做什麼嗎！！！",
  ui_story_5043_50431402_209_dialog_content = "我可是為你好。",
  ui_story_5043_50431402_210_dialog_content = "要是換蒂娜來打你，我還怕她分不清左右手。",
  ui_story_5043_50431402_211_dialog_content = "就是說啊。",
  ui_story_5043_50431402_212_dialog_content = "你……你們……",
  ui_story_5043_50431402_213_dialog_content = "好了，現在還是工作時間，我們戀愛法庭的工作人員怎能在門口溜躂呢。",
  ui_story_5043_50431402_214_dialog_content = "走吧走吧，回去上班了。",
  ui_story_5043_50431402_215_dialog_content = "嗯對，還有工作沒做完呢。",
  ui_story_5043_50431402_216_dialog_content = "呼啊——沙發～枕頭～",
  ui_story_5043_50431402_217_dialog_content = "喂！你們別推我！",
  ui_story_5043_50431402_218_dialog_content = "拿開你們的髒手！！！",
  ui_story_5043_50431402_219_dialog_content = "喔哦！他們把史瓦帶回去了！",
  ui_story_5043_50431402_220_dialog_content = "看來事情順利解決了？",
  ui_story_5043_50431402_221_dialog_content = "嗯，史瓦即將面對的審判恐怕非常嚴苛。",
  ui_story_5043_50431402_222_dialog_content = "雖然沒造成多大損失，但他的行為太惡劣了。",
  ui_story_5043_50431402_223_dialog_content = "如果他再更有心機一點，利用這些暗鬼攪亂政局……後果不堪設想。",
  ui_story_5043_50431402_224_dialog_content = "還好他沒那麼多心機，只是討厭戀愛而已，哈哈哈哈。",
  ui_story_5043_50431402_225_dialog_content = "是啊，可能正是這種偏激讓他做出別人無法想像的事情。",
  ui_story_5043_50431402_226_dialog_content = "至少在剛才開庭的短暫時間裡，他建立了一個滿足自己理想的法庭。",
  ui_story_5043_50431402_227_dialog_content = "這回事情總算是結束了！",
  ui_story_5043_50431402_228_dialog_content = "沒想到最開始小小的案子，竟然鬧到這種地步……",
  ui_story_5043_50431402_229_dialog_content = "嗯，事情結束了。",
  ui_story_5043_50431402_230_dialog_content = "只剩下一點點尾聲，讓我們聽到最後吧。",
  ui_story_5043_50431402_231_dialog_content = "嗯，對。我們走吧！",
  ui_story_5043_50431402_232_dialog_content = "去把最後的審判聽完……",
  ui_story_5043_50431402_233_dialog_content = "咦？修女？",
  ui_story_5043_50431402_234_dialog_content = "……結束了。",
  ui_story_5043_50431402_235_dialog_content = "妳、妳怎麼哭了？",
  ui_story_5043_50431402_236_dialog_content = "遊行的人群散了，天上的熱氣球沒了。",
  ui_story_5043_50431402_237_dialog_content = "我的紅花四葉草，全都沒了……",
  ui_story_5043_50431402_238_dialog_content = "哎呀，還不都是史瓦製造的動亂……",
  ui_story_5043_50431402_239_dialog_content = "結束了，全都結束了。",
  ui_story_5043_50431402_240_dialog_content = "白夜城的戀愛風潮，到此為止……",
  ui_story_5043_50431501_1_dialog_content = "調查結果出來了，實際情況就跟零恩推理的一樣。",
  ui_story_5043_50431501_2_dialog_content = "史瓦控制暗鬼，以幕後黑手的立場犯下了「連環斷頭雕像案」。",
  ui_story_5043_50431501_3_dialog_content = "所幸，他除了破壞雕像之外，沒有做出直接傷害光靈的事情。",
  ui_story_5043_50431501_4_dialog_content = "哈哈，幸好他還抱持著幾絲模糊的正義感……",
  ui_story_5043_50431501_5_dialog_content = "事後想想，審判官們好厲害呢，竟然能在沒有線索的情況下得出正確結論。",
  ui_story_5043_50431501_6_dialog_content = "嗯，這起案件應該能讓審判庭開始重視他們三個的能力吧。",
  ui_story_5043_50431501_7_dialog_content = "不過有件事我一直不懂。",
  ui_story_5043_50431501_8_dialog_content = "史瓦究竟用了什麼辦法控制暗鬼？",
  ui_story_5043_50431501_9_dialog_content = "戰鬥期間，我似乎沒看到特殊裝置……",
  ui_story_5043_50431501_10_dialog_content = "哦，關於這件事也有了調查結論。",
  ui_story_5043_50431501_11_dialog_content = "審判庭在薩拉爾莊園找到了史瓦圈養暗鬼的地下室。",
  ui_story_5043_50431501_12_dialog_content = "可是除了地下室外，調查人員沒找到任何像是能控制暗鬼的裝置。",
  ui_story_5043_50431501_13_dialog_content = "透過對史瓦的訊問，以及在他家中的調查取證，審判庭得出一個奇怪的結論。",
  ui_story_5043_50431501_14_dialog_content = "史瓦使用類似於馴獸的方式「馴服」了那些暗鬼。",
  ui_story_5043_50431501_15_dialog_content = "馴服？！！",
  ui_story_5043_50431501_16_dialog_content = "暗鬼是可以馴服的嗎？",
  ui_story_5043_50431501_17_dialog_content = "仔細想想，這件事似乎也沒那麼天方夜譚。",
  ui_story_5043_50431501_18_dialog_content = "光靈世代與暗鬼為敵，所以我們下意識地就將對方視為對立。",
  ui_story_5043_50431501_19_dialog_content = "但是拋開種族間的仇恨，暗鬼也不過是一種低智能的生物。",
  ui_story_5043_50431501_20_dialog_content = "牠們與其他動物一樣，有自己的習性和慾望。",
  ui_story_5043_50431501_21_dialog_content = "馴服動物不就是這麼一回事嗎？細心觀察、掌握動物的特質，讓牠明白聽話就會有好的後果。",
  ui_story_5043_50431501_22_dialog_content = "史瓦只是對暗鬼做了祖先曾對狼做過的事情。",
  ui_story_5043_50431501_23_dialog_content = "原來是這樣……",
  ui_story_5043_50431501_24_dialog_content = "好有道理，但是又好不可思議。",
  ui_story_5043_50431501_25_dialog_content = "其實也能從一些細節看出端倪。",
  ui_story_5043_50431501_26_dialog_content = "史瓦瞧不起同類，但是卻願意對小動物展現出強烈的親和力。",
  ui_story_5043_50431501_27_dialog_content = "他在這件事情上付出了不可思議的耐心，自然也得到不可思議的成果。",
  ui_story_5043_50431501_28_dialog_content = "這麼說來，若不從光靈的角度去看，或許他並不那麼討人厭。",
  ui_story_5043_50431501_29_dialog_content = "欸？不對啊。我本來就不是光靈……",
  ui_story_5043_50431501_30_dialog_content = "好了，閒話就聊到這裡。",
  ui_story_5043_50431501_31_dialog_content = "史瓦的審判要開始了。",
  ui_story_5043_50431501_32_dialog_content = "被告史瓦，暗中操控暗鬼，破壞雕像。",
  ui_story_5043_50431501_33_dialog_content = "審判庭經過嚴密的調查，目前已證據確鑿。",
  ui_story_5043_50431501_34_dialog_content = "被告，你認罪嗎？",
  ui_story_5043_50431501_35_dialog_content = "……",
  ui_story_5043_50431501_36_dialog_content = "（之前那個囂張跋扈的傢伙，現在變得這麼狼狽。）",
  ui_story_5043_50431501_37_dialog_content = "本次案件中，史瓦行為惡劣，但並未造成重大損失。",
  ui_story_5043_50431501_38_dialog_content = "鑒於他年紀輕輕，尚有充裕的改過空間，本庭擬不對史瓦判處監禁處罰。",
  ui_story_5043_50431501_39_dialog_content = "哦？原來我可以不進監獄？",
  ui_story_5043_50431501_40_dialog_content = "確實，說到底史瓦也只是一個偏執的怪人。",
  ui_story_5043_50431501_41_dialog_content = "既然沒造成重大損失，就不需要真的重罰。",
  ui_story_5043_50431501_42_dialog_content = "免除監禁並不代表你可以逃過法律的制裁。",
  ui_story_5043_50431501_43_dialog_content = "薩拉爾家族以及你本人必須負責本案相關的所有重建費用。",
  ui_story_5043_50431501_44_dialog_content = "你在審判庭工作的薪資，也會全部遭到扣除。",
  ui_story_5043_50431501_45_dialog_content = "當然，我接受這些處罰。",
  ui_story_5043_50431501_46_dialog_content = "他怎麼一臉無所謂啊……",
  ui_story_5043_50431501_47_dialog_content = "錢對他來說是最無關緊要的東西。",
  ui_story_5043_50431501_48_dialog_content = "看他的樣子……感覺懲罰好像太輕了？",
  ui_story_5043_50431501_49_dialog_content = "當然，還不止是這樣。",
  ui_story_5043_50431501_50_dialog_content = "審判庭仔細研究案件後認為，史瓦犯下此次極端行為，源於貴族教育體系的失責。",
  ui_story_5043_50431501_51_dialog_content = "為了彌補這個錯誤，本庭判處被告史瓦回到專業機構重修。",
  ui_story_5043_50431501_52_dialog_content = "什麼？！要我回黎明學院重修？",
  ui_story_5043_50431501_53_dialog_content = "串通暗鬼是非常嚴重的過錯，必須嚴正處理。",
  ui_story_5043_50431501_X53_dialog_content = "本庭決定，讓罪人史瓦重新接受光之神的教誨。",
  ui_story_5043_50431501_54_dialog_content = "分配到<color=#FFB400>專供修女學習的神殿</color>。",
  ui_story_5043_50431501_55_dialog_content = "修女？！！",
  ui_story_5043_50431501_56_dialog_content = "審判長大人，有、有必要做這樣的判決嗎？！",
  ui_story_5043_50431501_57_dialog_content = "希望你改過自新。來認識一下你未來的老師吧。",
  ui_story_5043_50431501_58_dialog_content = "你好，史瓦閣下。我們又見面了。",
  ui_story_5043_50431501_59_dialog_content = "是妳？是妳提出這個餿主意的嗎！！！",
  ui_story_5043_50431501_60_dialog_content = "除了例行的神學修習之外，還有縫紉和烹飪課等充滿樂趣的課程。",
  ui_story_5043_50431501_61_dialog_content = "接下來幾年的學習生活，還請多多指教。",
  ui_story_5043_50431501_62_dialog_content = "不要！不要啊！我不要去那種全是女人的地方讀書！！！",
  ui_story_5043_50431501_63_dialog_content = "看來你的價值觀念也需要重新建立呢。",
  ui_story_5043_50431501_64_dialog_content = "把史瓦帶下去，協助他準備入學。",
  ui_story_5043_50431501_65_dialog_content = "除了他之外，本案還有些許涉案人員需要受到處罰。",
  ui_story_5043_50431501_66_dialog_content = "零恩審判官。",
  ui_story_5043_50431501_67_dialog_content = "我在！",
  ui_story_5043_50431501_68_dialog_content = "私闖薩拉爾莊園，確實是你做的吧。",
  ui_story_5043_50431501_69_dialog_content = "沒錯。",
  ui_story_5043_50431501_70_dialog_content = "（他還真的去跟審判長自首了……）",
  ui_story_5043_50431501_71_dialog_content = "好。依照審判庭的審判官守則第一百二十七條的規定……",
  ui_story_5043_50431501_72_dialog_content = "你本月的績效歸零，薪資按照白夜城最低標準發放。",
  ui_story_5043_50431501_73_dialog_content = "我、我明白了……",
  ui_story_5043_50431501_74_dialog_content = "（零恩看起來臉色好差，感覺頗受打擊！）",
  ui_story_5043_50431501_75_dialog_content = "哎呀，真是的……還有我啦！",
  ui_story_5043_50431501_76_dialog_content = "我也跟著去了，我應該一起分擔這個處罰。",
  ui_story_5043_50431501_77_dialog_content = "哦？馬太審判官？",
  ui_story_5043_50431501_78_dialog_content = "還、還有我！我也在場。",
  ui_story_5043_50431501_79_dialog_content = "很高興你們願意承認罪行。除了馬太審判官同樣需要扣除本月的薪資之外……",
  ui_story_5043_50431501_80_dialog_content = "你們三個，晚點一起去打掃審判庭門口吧。",
  ui_story_5043_50431501_81_dialog_content = "滿地都是枯萎的花，能看嗎。",
  ui_story_5043_50431501_82_dialog_content = "啊？？怎麼會是這種懲罰？",
  ui_story_5043_50431501_83_dialog_content = "還想要別的嗎？",
  ui_story_5043_50431501_84_dialog_content = "不用了不用了！感謝審判長，我們馬上就去！",
  ui_story_5043_50431501_85_dialog_content = "除此之外，還有最後一項罪行。",
  ui_story_5043_50431501_86_dialog_content = "請傳喚證人狗蛋上來。",
  ui_story_5043_50431501_87_dialog_content = "我、我在這，審判長大人！",
  ui_story_5043_50431501_88_dialog_content = "啊……是狗蛋。",
  ui_story_5043_50431501_89_dialog_content = "（哇，狗蛋怎麼穿成這個樣子！）",
  ui_story_5043_50431501_90_dialog_content = "（好精緻啊，儼然就是白夜城的打扮！）",
  ui_story_5043_50431501_91_dialog_content = "你是本案的受害者之一，卻願意為光靈提供幫助，非常值得鼓勵。",
  ui_story_5043_50431501_92_dialog_content = "但是，在法庭上做偽證依然不應該。",
  ui_story_5043_50431501_93_dialog_content = "就這一點，教唆你的零恩審判官也同罪。",
  ui_story_5043_50431501_94_dialog_content = "嗯……我明白……",
  ui_story_5043_50431501_95_dialog_content = "那麼，你們將一起受到懲罰——",
  ui_story_5043_50431501_96_dialog_content = "下去跟史瓦道個歉吧。",
  ui_story_5043_50431501_97_dialog_content = "嗚……欸？",
  ui_story_5043_50431501_98_dialog_content = "道、道個歉就好了嗎？",
  ui_story_5043_50431501_99_dialog_content = "身為受騙的一方，他肯定氣壞了，記得道歉態度要誠懇一點。",
  ui_story_5043_50431501_100_dialog_content = "好了，那麼涉案人等的全部處罰已宣布完畢。",
  ui_story_5043_50431501_101_dialog_content = "「連環斷頭雕像案」結案，今日至此休庭！",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>咚——</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>幾天後</color>",
  ui_story_5043_50431501_104_dialog_content = "咳，以上，就是關於我幾個月前龍洲行程的分享。",
  ui_story_5043_50431501_105_dialog_content = "好的，PlayerName，十分感謝。",
  ui_story_5043_50431501_106_dialog_content = "這世界的局勢變幻如風雲，但白夜城的立場堅定不移。",
  ui_story_5043_50431501_107_dialog_content = "接下來的一年，希望白夜城與空谷之間繼續保持友好的往來。",
  ui_story_5043_50431501_108_dialog_content = "希望你的意願也和我一樣，年輕人。",
  ui_story_5043_50431501_109_dialog_content = "您、您言重了，我當然樂意與所有人和諧相處！",
  ui_story_5043_50431501_110_dialog_content = "那真是再好不過了。",
  ui_story_5043_50431501_111_dialog_content = "（呼……總算是說完了！）",
  ui_story_5043_50431501_112_dialog_content = "你這次的發言還挺有那麼一回事嘛，PlayerName。",
  ui_story_5043_50431501_113_dialog_content = "是嗎？哈哈……但，但親自到了這裡還是有點緊張。",
  ui_story_5043_50431501_114_dialog_content = "會議的流程已經順利走完，各位還有其他問題嗎？",
  ui_story_5043_50431501_115_dialog_content = "審判庭的報告已全部結束了。",
  ui_story_5043_50431501_116_dialog_content = "奧托公爵呢？",
  ui_story_5043_50431501_117_dialog_content = "呵呵，我都快坐累了。",
  ui_story_5043_50431501_118_dialog_content = "那麼，散會吧，各位。",
  ui_story_5043_50431501_119_dialog_content = "（不對，我還得把握審判庭和元老院都出席的機會，說明一件事。）",
  ui_story_5043_50431501_120_dialog_content = "（白夜城中近來除了暗鬼與狂熱人群之外，還有一幫人在趁機製造混亂。）",
  ui_story_5043_50431501_121_dialog_content = "（我代表高庭守衛隊，需向元老院問責！）",
  ui_story_5043_50431501_122_dialog_content = "城主、奧托公爵，請留步。",
  ui_story_5043_50431501_123_dialog_content = "舒瓦茲殿下，高庭近期針對各種突發問題處理得越發賣力了。",
  ui_story_5043_50431501_124_dialog_content = "出乎我意料，你們還挺擅長跟民眾打交道。",
  ui_story_5043_50431501_125_dialog_content = "哈哈，奧托公爵太客氣了，這也多虧元老院的支持。",
  ui_story_5043_50431501_126_dialog_content = "若非元老院出兵幫忙驅逐暗鬼，高庭守衛隊終究無法自由去做。",
  ui_story_5043_50431501_127_dialog_content = "怎麼了，卡蓮？",
  ui_story_5043_50431501_128_dialog_content = "……",
  ui_story_5043_50431501_129_dialog_content = "既然這樣，我就不打擾你們的父女時光了，告辭。",
  ui_story_5043_50431501_130_dialog_content = "城主，元老院的衛兵在冠月節沙龍上做了什麼好事，您應該知道。",
  ui_story_5043_50431501_131_dialog_content = "我當然比你更清楚，卡蓮。",
  ui_story_5043_50431501_132_dialog_content = "妳在最近這一年，沉穩了不少，也依舊是個勇敢的女孩。",
  ui_story_5043_50431501_133_dialog_content = "但政治上的事情，不能單靠勇敢這個品性來解決。",
  ui_story_5043_50431501_134_dialog_content = "等手頭上的工作結束，我再安排高庭的各位去度假吧。",
  ui_story_5043_50431501_135_dialog_content = "不必了，謝謝。",
  ui_story_5043_50431501_136_dialog_content = "PlayerName，我們走。",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>啪——！啪——！啪——！</color>",
  ui_story_5043_50431501_138_dialog_content = "恭喜PlayerName報告工作大成功！！！",
  ui_story_5043_50431501_139_dialog_content = "剛才伊倫汀審判長出來的時候，我們就知道了！",
  ui_story_5043_50431501_140_dialog_content = "這些是替彼瑪隆準備雕像那次剩下的煙火。",
  ui_story_5043_50431501_141_dialog_content = "也算是物盡其用了。",
  ui_story_5043_50431501_142_dialog_content = "怎麼樣？夠驚喜嗎？",
  ui_story_5043_50431501_143_dialog_content = "公主殿下也別繃著臉了，高興點吧！！",
  ui_story_5043_50431501_144_dialog_content = "PlayerName，也祝賀你的工作順利結束。",
  ui_story_5043_50431501_145_dialog_content = "哇……謝謝大家！",
  ui_story_5043_50431501_146_dialog_content = "你們幾個……",
  ui_story_5043_50431501_147_dialog_content = "算了，真是拿你們沒辦法。",
  ui_story_5043_50431501_148_dialog_content = "各位，我不想掃興，不過關於審判庭的工作，還沒有結束呢。",
  ui_story_5043_50431501_149_dialog_content = "卡蓮殿下，您也一起來吧。",
  ui_story_5043_50431501_150_dialog_content = "這項工作還需要高庭這邊的配合。",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>高庭 審判庭內</color>",
  ui_story_5043_50431501_152_dialog_content = "原來如此。",
  ui_story_5043_50431501_153_dialog_content = "戀愛分部雖然已經解散，卻留下了大量的案件卷宗。",
  ui_story_5043_50431501_154_dialog_content = "審判長，你們審判庭辦事很細心。",
  ui_story_5043_50431501_155_dialog_content = "哇，這麼多卷宗，什麼時候才能看完啊……",
  ui_story_5043_50431501_156_dialog_content = "這個，就要麻煩——",
  ui_story_5043_50431501_157_dialog_content = "明白了……",
  ui_story_5043_50431501_158_dialog_content = "卡蓮殿下，這些卷宗乍看都是男女間的戀愛糾紛。",
  ui_story_5043_50431501_159_dialog_content = "但從諸多記錄裡，能看出白夜城在基礎建設、社會穩定等方面的各種潛在問題。",
  ui_story_5043_50431501_160_dialog_content = "而且，我也是第一次深入了解到中庭乃至下城區民眾的各種想法。",
  ui_story_5043_50431501_161_dialog_content = "他們對愛情的想法，他們對信仰的闡釋……都為我帶來了新的思考。",
  ui_story_5043_50431501_162_dialog_content = "我想，這些卷宗對下一次的成文法修訂會有所幫助。",
  ui_story_5043_50431501_163_dialog_content = "屆時希望城主這邊——尤其是您，可以支持審判庭的工作與判斷。",
  ui_story_5043_50431501_164_dialog_content = "說得長遠一些，為了白夜城的今後，此事至關重要。",
  ui_story_5043_50431501_165_dialog_content = "好，我答應妳的要求。",
  ui_story_5043_50431501_166_dialog_content = "不只妳一個人在為此著想，伊淪汀。",
  ui_story_5043_50431501_167_dialog_content = "卡蓮覺得高興點了嗎？",
  ui_story_5043_50431501_168_dialog_content = "是啊，很明顯嗎？",
  ui_story_5043_50431501_169_dialog_content = "這樣看起來，周遭的街道又不知不覺變回正常的樣子。",
  ui_story_5043_50431501_170_dialog_content = "沒有熱鬧的沙龍和遊行，也沒有飄在空中的月亮。",
  ui_story_5043_50431501_171_dialog_content = "這就是你大驚小怪了，零恩，我們這群貴族就是這樣。",
  ui_story_5043_50431501_172_dialog_content = "白夜城內的風向瞬息萬變，得快點追趕上新的潮流才行啊。",
  ui_story_5043_50431501_173_dialog_content = "你們看。",
  ui_story_5043_50431501_174_dialog_content = "哇？這不是我的那款手套嗎？",
  ui_story_5043_50431501_175_dialog_content = "它現在可變成最流行款式了，貴族們出入社交場合都會佩戴。",
  ui_story_5043_50431501_176_dialog_content = "雖然戴起來感覺偏厚重，但我也一口氣買了七雙呢～",
  ui_story_5043_50431501_177_dialog_content = "你也真夠閒的。",
  ui_story_5043_50431501_178_dialog_content = "真是標準紈絝子弟會做的事情……",
  ui_story_5043_50431501_179_dialog_content = "蒂娜小姐，身為這場手套潮流的領導者，妳現在有何感想呀？",
  ui_story_5043_50431501_180_dialog_content = "妳和狗蛋的進展如何？順利成為牠的飼育人了嗎？",
  ui_story_5043_50431501_181_dialog_content = "雖然白夜城本來絕對禁止這樣的事……豈不是很有意思嘛！",
  ui_story_5043_50431501_182_dialog_content = "那個，大家……我今天，約了狗蛋在這裡見面。",
  ui_story_5043_50431501_183_dialog_content = "但是，其實我是要跟他<color=#FFB400>道別</color>。",
  ui_story_5043_50431501_184_dialog_content = "呃？！",
  ui_story_5043_50431501_185_dialog_content = "等一下，這麼突然？蒂娜小姐，妳對牠的熱情這麼快就消退了？",
  ui_story_5043_50431501_186_dialog_content = "不，反而正是因為，我非常喜歡這個可愛的、善意的、到處旅行的小傢伙。",
  ui_story_5043_50431501_187_dialog_content = "暗鬼是恐怖又可恨的存在，但狗蛋不像其他的暗鬼。",
  ui_story_5043_50431501_188_dialog_content = "但也不是所有人都能理解這件事。",
  ui_story_5043_50431501_189_dialog_content = "假如我要求他跟我一起留在白夜城，反而會害他生活得不舒適。",
  ui_story_5043_50431501_190_dialog_content = "他這一個月在白夜城的生活，想必也是恐懼大過開心。",
  ui_story_5043_50431501_191_dialog_content = "……咦？",
  ui_story_5043_50431501_192_dialog_content = "唔……",
  ui_story_5043_50431501_193_dialog_content = "狗蛋，別躲了，過來吧！",
  ui_story_5043_50431501_194_dialog_content = "大、大家都在啊……",
  ui_story_5043_50431501_X194_dialog_content = "你竟然換了衣服！",
  ui_story_5043_50431501_X195_dialog_content = "好精緻啊，儼然就是白夜城的打扮！",
  ui_story_5043_50431501_X196_dialog_content = "嗯……因為今天是個重要的日子，所以想穿得正式一點。",
  ui_story_5043_50431501_195_dialog_content = "其實我也是想來向大家道別。",
  ui_story_5043_50431501_196_dialog_content = "你還是要繼續旅行嗎？",
  ui_story_5043_50431501_197_dialog_content = "嗯。只、只不過，跟大家以為的還是不太一樣。",
  ui_story_5043_50431501_198_dialog_content = "在白夜城的這些日子，確實經歷了不少可怕的事情，也經常處在恐懼之中。",
  ui_story_5043_50431501_199_dialog_content = "但是這段回憶仍然讓我感到幸福。",
  ui_story_5043_50431501_200_dialog_content = "因為我認識了你們。",
  ui_story_5043_50431501_201_dialog_content = "尤其……尤其是認識了蒂娜。",
  ui_story_5043_50431501_202_dialog_content = "謝謝你，狗蛋。",
  ui_story_5043_50431501_203_dialog_content = "我、我第一次從光靈身上感受到了，不需要理由的善意。",
  ui_story_5043_50431501_204_dialog_content = "這對我很珍貴，也使我很幸福。",
  ui_story_5043_50431501_205_dialog_content = "（不需要理由的善意……）",
  ui_story_5043_50431501_206_dialog_content = "（是啊，多麼難得的心意。）",
  ui_story_5043_50431501_207_dialog_content = "……走吧狗蛋，去繼續你的旅程吧。",
  ui_story_5043_50431501_208_dialog_content = "如果以後有機會，說不定我們還會再見。",
  ui_story_5043_50431501_209_dialog_content = "哦對了，有個東西我一直想送給你。",
  ui_story_5043_50431501_210_dialog_content = "喏，這一籃是新做的餅乾。路途遙遠，帶著當點心吃吧。",
  ui_story_5043_50431501_211_dialog_content = "嗚……謝謝……謝謝妳蒂娜……",
  ui_story_5043_50431501_212_dialog_content = "我會非常、非常珍惜地吃！",
  ui_story_5043_50431501_213_dialog_content = "哈哈哈，「非常珍惜地吃」是哪種吃法啊，別餓著肚子喔！",
  ui_story_5043_50431501_214_dialog_content = "好了，快點出發吧。",
  ui_story_5043_50431501_215_dialog_content = "白夜城的太陽永遠高掛，但其他地方可不一定，自己小心。",
  ui_story_5043_50431501_216_dialog_content = "嗚……嗯……我走了！",
  ui_story_5043_50431501_217_dialog_content = "大家再見！！！",
  ui_story_5043_50431501_218_dialog_content = "再見，狗蛋！！！",
  ui_story_5043_50431501_219_dialog_content = "噢，那個傢伙離開了～♪",
  ui_story_5043_50431501_220_dialog_content = "帶走了大家的道別和禮物～♪",
  ui_story_5043_50431501_221_dialog_content = "留下的是獨屬於牠的氣味～♪",
  ui_story_5043_50431501_222_dialog_content = "融入明天白夜城的清晨裡～♪"
}
return config
